(window.GIM_TS=window.GIM_TS||{})["Bava Metzia.6"]={"from":144,"a":[["\u0003הכא לאו\u0004 \u0005[כאן\u0006 הדבר \u0005לא]\u0006 \u0003בידו\u0004 לקנות, שמא לא ימכרו לו.","\u0003אמר רבא: הני בי תלתא דיהבי זוזי לחד למזבן להו מידי\u0004 \u0005[שלושה שנתנו כסף לאחד לקנות להם דבר\u0006 מה\u0005]\u0006 \u0003וזבן לחד מינייהו\u0004 \u0005[וקנה לאחד מהם]\u0006 — \u0003זבן לכולהו\u0004 \u0005[קנה לכולם],\u0006 ואותו אדם אינו יכול לטעון שקנה רק עבורו, אלא יתחלקו כולם במה שקנה. ו\u0003לא אמרן\u0004 \u0005[אמרנו]\u0006 דבר זה \u0003אלא\u0004 כש\u0003לא צר וחתים איניש איניש לחודיה\u0004 \u0005[אדם אדם,\u0006 כל אחד מהם, \u0005לעצמו]\u0006 את כספיו, אלא נתנו כולם בצרור אחד. \u0003אבל\u0004 אם \u0003צר וחתים איניש איניש לחודיה\u0004 \u0005[צרר וחתם אדם אדם לעצמו],\u0006 \u0003למאן דזבן\u0004 \u0005[למי שקנה]\u0006 — \u0003זבן\u0004 \u0005[קנה],\u0006 \u0003ולמאן\u0004 \u0005[ולמי]\u0006 ש\u0003לא זבן\u0004 \u0005[קנה]\u0006 — \u0003לא זבן\u0004 \u0005[קנה].\u0006","\u0003אמר רב פפי משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא: האי סיטומתא\u0004 \u0005[סימון זה]\u0006 — \u0003קניא\u0004 \u0005[קונה],\u0006 שהיו נותנים לעשות סימן על דברים שנמכרו, לומר שהם שייכים לו, ואף שלא שילם עדיין הרי זה קנין. ושואלים: \u0003למאי הלכתא\u0004 \u0005[למה,\u0006 לאיזו \u0005הלכה]\u0006 כלומר, מה תוקפו של קנין זה? \u0003רב חביבא אמר: למקניא\u0004 \u0005[לקנות]\u0006 \u0003ממש,\u0004 שהחפץ נחשב כשייך לקונה לכל דבר.","\u0003רבנן אמרי\u0004 \u0005[\u0006ו\u0005חכמים אמרו]:\u0006 \u0003לקבולי עליה\u0004 \u0005[לקבל עליו]\u0006 קללת \u0003\"מי שפרע\",\u0004 שאם חזר בו — הרי זה כמי שנתן דמים וחזר בו, שאין בית דין כופים אותו לגמור הקנין, אבל אומרים עליו קללת \"מי שפרע\".","ומסכמים: \u0003והלכתא\u0004 \u0005[והלכה\u0006 היא\u0005]\u0006 שקנין סיטומתא הוא רק \u0003לקבולי עליה\u0004 \u0005[לקיבל עליו]\u0006 \u0003\"מי שפרע\".\u0004 ומעירים: \u0003ו\u0004אולם \u0003באתרא דנהיגו למקני\u0004 \u0005[שנהגו לקנות]\u0006 \u0003ממש\u0004 — \u0003קנו,\u0004 שלענין זה הכל כמנהג המקום.","שנינו במשנה שאם \u0003היה הוא תחלה\u0004 (ראשון) \u0003לקוצרים,\u0004 פוסק עמו רק כאשר הדבר שמוכר כבר מוכן ממש למסירה. \u0003אמר רב:\u0004 אם היה הדבר \u0003מחוסר\u0004 רק \u0003שתים,\u0004 שתי עבודות, עד לגמר מלאכתו — \u0003פוסק\u0004 עמו, שהדבר נחשב כבר כגמור. אבל אם היה מחוסר \u0003שלש\u0004 — \u0003אינו פוסק,\u0004 שהדבר נחשב בלתי גמור עדיין, ויש בקביעת השער המוקדם חשש ריבית. \u0003ושמואל אמר:\u0004 אם העבודות עד לגמר המלאכה הן עבודות הנעשות \u0003בידי אדם\u0004 — \u0003אפילו\u0004 מחוסר \u0003מאה\u0004 מלאכות \u0003פוסק,\u0004 אם היה הדבר תלוי \u0003בידי שמים\u0004 — \u0003אפילו\u0004 חסר מלאכה \u0003אחת אינו פוסק.\u0004","ומעתה מביאים ראיות מן המשנה לכאן ולכאן. \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]\u0006 ש\u0003פוסק עמו על הגדיש, והא\u0004 \u0005[והרי]\u0006 מן הגדיש עד לעשייתו גרעיני חיטה \u0003מחוסר\u0004 עדיין \u0003משדא\u0004 \u0005[להטילו,\u0006 להניחו\u0005]\u0006 \u0003בחמה למיבש ולמידש ומדרא\u0004 \u0005[ליבשו ולדוש ולזרות],\u0006 נמצא שמחוסר שלוש מלאכות, ובכל זאת פוסק! ומשיבים: \u0003כגון דשדא\u0004 \u0005[ש\u0006כבר \u0005הטילו,\u0006 הניחו\u0005]\u0006 \u0003בחמה ויבש.\u0004","ושואלים: \u0003ול\u0004שיטת \u0003שמואל,\u0004 ש\u0003אמר:\u0004 אם זו מלאכה העתידה להיעשות \u0003בידי שמים אפילו\u0004 לא היתה חסרה אלא \u0003מלאכה\u0004 \u0003אחת אינו פוסק, והא\u0004 \u0005[והרי]\u0006 \u0003מחוסר מידרא\u0004 \u0005[זריה],\u0006 ש\u0003בידי שמים היא,\u0004 שהרי זורים רק כשיש רוח, ומשיבים: \u0003אפשר\u0004 לזרות \u0003בנפוותא\u0004 \u0005[\u0006\u0005בניפוח],\u0006 שאמנם עושים כך רק בשעת הדחק, אבל כיון שהדבר אפשרי בידי אדם — משום כך אין זה קרוי עוד בידי שמים.","שנינו במשנה שפוסק \u0003על העביט של ענבים.\u0004 ומקשים לשיטת רב: \u0003והא\u0004 עדיין הוא \u0003מחוסר מכמר\u0004 \u0005[חימום\u0006 בערימה\u0005],\u0006 \u0003ועיולי לבי מעצרתא,\u0004 \u0003למידש\u0004 \u0003ולמנגד\u0004 \u0005[והכנסה לגת,\u0006 ו\u0005לדוש,\u0006 לסחוט\u0005,\u0006 \u0005ולמשוך],\u0006 להעביר את היין מן הגת אל הבור! ומשיבים: \u0003כדתני\u0004 \u0005[כפו ששנה]\u0006 \u0003ר' חייא\u0004 בענין דומה, שלא שנה \"על העביט\" שהיא כלי שבו שמים פירות מיד לאחר הבציר אלא \u0003על הכומר של זיתים, הכא נמי\u0004 \u0005[כאן גם כן]\u0006 מדובר על \u0003הכומר של ענבים,\u0004 כלומר, ערימת ענבים שכבר התחממו די הצורך.","ושואלים: \u0003והא מחוסרי תלת\u0004 \u0005[והרי\u0006 עדיין \u0005מחוסרים שלוש\u0006 מלאכות\u0005]!\u0006 ומשיבים; \u0003באתרא דההוא דזבין\u0004 \u0005[במקום שבו זה שקונה]\u0006 \u0003הוא\u0004 זה \u0003דנגיד\u0004 \u0005[שמושך]\u0006 את היין לבור, ואם כן יש רק שתי מלאכות בדבר.","שנינו במשנה \u0003ועל המעטן של זיתים.\u0004 ומקשים לרב: \u0003והא\u0004 \u0005[והרי]\u0006 עדיין הוא \u0003מחוסר מכמר ועיולי לבי דפי למידש ולמנגד\u0004 \u0005[חימום\u0006 בערימה \u0005והכנסה לבית הבד, ודישה,\u0006 סחיטה, \u0005ומשיכת\u0006 השמן לבור\u0005]!\u0006 ומשיבים: \u0003תני\u0004 \u0005[שנה]\u0006 \u0003ר' חייא\u0004 בברייתא בנוסח אחר: \u0003על כומר של זיתים,\u0004 כלומר, ערימת זיתים שנתחממו כבר. ושואלים: \u0003והא איכא תלת\u0004 \u0005[והרי\u0006 עדיין \u0005יש\u0006 עוד \u0005שלוש\u0006 מלאכות\u0005]\u0006 — הכנסה, דישה ומשיכה! ומשיבים: \u0003באתרא דההוא דזבין ההוא מנגיד\u0004 \u0005[במקום ש\u0006בו \u0005זה שקונה הוא שמושך\u0006 את השמן\u0005].\u0006","שנינו במשנה כי פוסקים על \u0003הביצים של יוצר.\u0004 ושואלים לשיטת רב: \u0003אמאי\u0004 \u0005[מדוע]\u0006 יהא מותר? \u0003והא מחוסר לפופי\u0004 \u0005[גילגול\u0006 לפי מידה\u0005],\u0006 \u0003ויבושי\u0004 (יבוש), \u0003עיולי לאתונא למשרף\u0004 \u0003ולמיפק\u0004 \u0005[הכנסה לכבשן לשרוף ולהוציא]!\u0006 ומשיבים: \u0003כגון דמלפפה ויבישו\u0004 \u0005[ש\u0006כבר היו \u0005מעוגלים ויבשים].\u0006 ושואלים עוד: \u0003והא איכא תלת\u0004 \u0005[והרי יש\u0006 עדיין \u0005שלוש\u0006 מלאכות\u0005]!\u0006 ומשיבים: \u0003באתרא דההוא דזבין\u0004 \u0005[במקום שזה שקונה]\u0006 \u0003הוא\u0004 גם זה \u0003דמפיק\u0004 \u0005[שמוציא\u0006 מן הכבשן\u0005].\u0006","שנינו \u0003ועל הסיד משישקענו בכבשן.\u0004 ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 עדיין הוא \u0003מחוסר מקלה ואפוקי ומידק\u0004 \u0005[שריפה והוצאה וטחינה]!\u0006 ומשיבים: \u0003באתרא דההוא דזבין ההוא דייק\u0004 \u0005[במקום שבו הוא הקונה הוא הטוחן].\u0006 ושואלים: \u0003ול\u0004שיטת \u0003שמואל,\u0004 ש\u0003אמר\u0004 כי כל מלאכה שעתידה להיעשות \u0003בידי אדם\u0004 — \u0003אפילו\u0004 עדיין חסרות \u0003מאה\u0004 מלאכות \u0003פוסק, למה לי משישקענו בכבשן?\u0004 הלא גם קודם לכן מותר, כיון שהמלאכות הללו הן מלאכות הנעשות בידי אדם! ומשיבים: לשיטתו יש לתקן קצת בגרסה ו\u0003אימא\u0004 \u0005[אמור]\u0006 \u0003\"משראוי לשקעו בכבשן\".\u0004","שנינו במשנה שפוסקים \u0003על הביצים של יוצר. תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אין פוסקים על הביצים של יוצר עד שיעשו,\u0004 כלומר, שהחימר יהיה כבר בצורת כדורים מגובלים, אלו \u0003דברי ר' מאיר. אמר ר' יוסי: במה דברים אמורים\u0004 — \u0003בעפר לבן\u0004 שהוא חימר משובח שעושים ממנו כלי חרס מובחרים, \u0003אבל בעפר שחור\u0004 (חימר פשוט וגולמי), \u0003כגון\u0004 של \u0003כפר חנניא וחברותיה,\u0004 או של \u0003כפר שיחין וחברותיה\u0004 — \u0003פוסקין\u0004 מיד. ומדוע — \u0003אף על פי שאין לזה יש לזה,\u0004 שעפר שחור מצוי תמיד לכל.","מסופר: \u0003אמימר יהיב זוזי מכי מעיילי עפרא\u0004 \u0005[היה נותן כסף מזמן שהיו מכניסים\u0006 את \u0005העפר,\u0006 החימר, בביתו\u0005]\u0006 ולא קודם לכן. ושואלים: \u0003כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי]\u0006 נהג? \u0003אי\u0004 \u0005[אם]\u0006 \u0003כ\u0004שיטת \u0003ר' מאיר\u0004 נהג — \u0003האמר\u0004 \u0005[הרי אמר]\u0006 \u0003עד שיעשו\u0004 ודי בכך. \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003כ\u0004שיטת \u0003ר' יוסי\u0004 נהג — \u0003האמר\u0004 \u0005[הרי אמר]\u0006 יתירה מזו: \u0003אף על פי שאין לזה יש לזה!\u0004 ומשיבים: \u0003לעולם\u0004 פסק \u0003כ\u0004שיטת \u0003ר' יוסי, ו\u0004אולם \u0003באתריה\u0004 \u0005[במקומו]\u0006 של \u0003אמימר עשיק עפרא\u0004 \u0005[\u0006היה \u0005העפר נדיר],\u0006 שאפילו עפר (חימר) שחור לא היה מצוי, ולכן, \u0003אי דמעיילי עפרא סמכא דעתיה ויהיב להו זוזי\u0004 \u0005[אם מכניסים\u0006 את \u0005העפר סומכת דעתו\u0006 על כך \u0005ונותן להם כסף],\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 — \u0003לא סמכא דעתיה\u0004 \u0005[אין דעתו סומכת].\u0006","שנינו במשנה ש\u0003פוסק עמו על הזבל כל ימות השנה\u0004 ור' יוסי מצריך שיהא לפחות זבל באשפתו, וחכמים מתירים. ועל כך שואלים: \u0003חכמים היינו\u0004 \u0005[הרי הם\u0006 זהים\u0005]\u0006 לשיטת ה\u0003תנא קמא\u0004 \u0005[הראשון],\u0006 ומה טעם בחזרה על דברים שנאמרו? \u0003אמר רבא:\u0004"],["\u0003ימות הגשמים\u0004 — \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל למעשה\u0005],\u0006 שלדעת תנא קמא כל ימות השנה ובכללם ימות הגשמים, ולדעת חכמים אינו כולל ימות הגשמים, שבהם אין הזבל מצוי.","שנינו במשנה: \u0003ופוסק עמו כשער הגבוה\u0004 (הזול), שיכול לקבוע מחיר ולומר כי אם יוזל המחיר יקנה לפי השער הזול יותר.","מסופר: \u0003ההוא גברא דיהיב זוזי לנדוניא דבי חמוה\u0004 \u0005[אדם אחד שנתן כסף לנדוניה\u0006 בשביל \u0005בית חמיו],\u0006 שחותנו המיועד עשאו שליח לקנות את התכשיטים שישמשו חלק מן הנדוניה, \u0003לסוף זל\u0004 \u0005[\u0006ו\u0005לבסוף הוזלה]\u0006 ה\u0003נדוניא,\u0004 שירד המחיר של המתנות שקנה, ורצה אותו אדם לחזור בו מן הקניה. \u0003אתו לקמיה\u0004 \u0005[באו לפני]\u0006 \u0003רב פפא\u0004 להתדיין. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003פסקת עמו כשער הגבוה\u0004 — \u0003שקיל כהשתא\u0004 \u0005[קח כמו\u0006 המחיר \u0005עכשיו]\u0006 שהרי התנית על המחיר הזול ביותר. \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 — \u0003שקיל כי מעיקרא\u0004 \u0005[קח כמו מתחילה]\u0006 ובאותו מחיר שקבעת.","\u0003אמרו ליה רבנן\u0004 \u0005[לו חכמים]\u0006 \u0003לרב פפא: ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 — \u0003פסק שקיל כמעיקרא\u0004 \u0005[יקח כמתחילה]?\u0006 הלא \u0003מעות נינהו\u0004 \u0005[הם],\u0006 שנתן \u0003ומעות\u0004 בלבד \u0003לא קנו! אמר להו\u0004 \u0005[להם]:\u0006 אף אני לא התכוונתי שהקנין גמור, אלא \u0003אנא נמי לקבולי עליה\u0004 \u0005[אני גם כן לקבל עליו]\u0006 קללת \u0003\"מי שפרע\" קא אמינא\u0004 \u0005[הוא\u0006 ש\u0005אמרתי].\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003פסק כשער הגבוה\u0004 הצדק עם הקונה, ואם כן ה\u0003מוכר קא הדר ביה\u0004 \u0005[הוא\u0006 ש\u0005חוזר בו]\u0006 מן העיסקה, ולכן \u0003מקבל עליה\u0004 \u0005[יקבל עליו]\u0006 ה\u0003מוכר \"מי שפרע\", אי\u0004 \u0005[אם]\u0006 \u0003לא פסק\u0004 \u0005[פסק]\u0006 — ה\u0003לוקח קא הדר ביה\u0004 \u0005[הוא\u0006 זה ש\u0005חוזר בו]\u0006 ולכן מקבל עליו ה\u0003לוקח \"מי שפרע\".\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב פפא: וממאי\u0004 \u0005[וממה,\u0006 מהיכן\u0005]\u0006 יודע אתה \u0003דרבנן\u0004 \u0005[ש\u0006כשיטת \u0005חכמים]\u0006 \u0003היא\u0004 אותם \u0003דפליגי עליה\u0004 \u0005[שחלוקים עליו]\u0006 על שיטת \u0003ר' שמעון\u0004 \u0003דאמרי\u0004 \u0005[שאומרים]\u0006 \u0003מעות לא קנו, ואפילו הכי\u0004 \u0005[כך]\u0006 מסכימים הם: \u0003אי\u0004 \u0005[אם]\u0006 \u0003פסק כשער הגבוה\u0004 — \u0003שקיל כדהשתא\u0004 \u0005[לוקח כמו\u0006 השער של \u0005עכשיו],\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003לא פסק\u0004 — \u0003שקיל כדמעיקרא\u0004 \u0005[לוקח כמו מתחילה],\u0006","\u0003דלמא\u0004 \u0005[שמא]\u0006 כשיטת \u0003ר' שמעון היא,\u0004 ש\u0003אמר מעות קונות\u0004 קנין גמור, ואז פשוט \u0003וכי\u0004 \u0005[וכאשר]\u0006 \u0003פסק כשער הגבוה\u0004 — \u0003שקיל כי השתא\u0004 \u0005[לוקח כמו עכשיו],\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003לא פסק\u0004 — \u0003שקיל כמעיקרא\u0004 \u0005[לוקח כמו מתחילה]\u0006 וטעמו אינו משום שפסק מראש אלא \u0003משום דקני להו זוזי\u0004 \u0005[שקנה להם הכסף].\u0006 \u0003אבל לרבנן\u0004 \u0005[ל\u0006שיטת \u0005חכמים],\u0006 \u0003בין\u0004 ש\u0003פסק בין\u0004 ש\u0003לא פסק\u0004 — \u0003שקיל כי השתא\u0004 \u0005[לוקח כמו עכשיו],\u0006 \u0003דדעתיה דאיניש אתרעא זילא\u0004 \u0005[שדעתו של אדם על השער הזול],\u0006 וכיון שאין הוכחה בדבר ראוי היה ללכת בעקביות אחר שיטת חכמים!","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אימור\u0004 \u0005[אמור]\u0006 ש\u0003אמר ר' שמעון בחד תרעא\u0004 \u0005[בשער אחד],\u0006 כלומר, שלא השתנה המחיר בינתים, שאז הכסף גומר את הקנין, ואולם \u0003בתרי תרעי מי\u0004 \u0005[בשני שערים האם]\u0006 \u0003אמר?\u0004 ודאי גם הוא יודה שיכול לחזור בו כשנשתנה השער. \u0003דאי\u0004 \u0005[שאם]\u0006 \u0003לא תימא הכי\u0004 \u0005[תאמר כך]\u0006 שאף לדעת ר' שמעון יש אפשרות של חזרה, אם כן \u0003\"מי שפרע\" בלוקח\u0004 — \u0003לר' שמעון לית ליה\u0004 \u0005[אין לו]\u0006 כלל, כיון שנתן כסף אינו יכול להתחרט!","\u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003הכי נמי\u0004 \u0005[כך הוא גם כן],\u0006 שבאמת אינו סובר שיש \"מי שפרע\" בזה, \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מכל מקום כך הלכה, אבל אמרו חכמים \"מי שפרע\" וכו'.\u0004","ונברר: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003מכל מקום? לאו\u0004 \u0005[האם לא]\u0006 ש\u0003לא שנא\u0004 \u0005[שונה]\u0006 אם היה זה \u0003לוקח ולא שנא\u0004 \u0005[שונה]\u0006 אם היה זה \u0003מוכר\u0004 \u0003מקבל עליו\u0004 קללת \u0003\"מי שפרע\"? אלא,\u0004 בהכרח יש לומר: \u0003כי קאמר\u0004 \u0005[כאשר אמר]\u0006 \u0003ר' שמעון\u0004 שכסף קונה — הרי זה \u0003בחד תרעא\u0004 \u0005[בשער אחד],\u0006 ואולם \u0003בתרי תרעי\u0004 \u0005[בשני שערים]\u0006 כשהשתנה השער \u0003לא אמר.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא לרב אשי: ותיפוק ליה\u0004 \u0005[ותצא לו]\u0006 לרב פפא הלכה זו מטעם פשוט יותר: ש\u0003שליח שוייה מעיקרא\u0004 \u0005[עשה אותו מתחילה],\u0006 וכיון שהיה חתן זה שליח בלבד, יכול החותן־המשלח לומר לו: לא שלחתיך על מנת לקלקל, ובטלה שליחותך, וממילא בטל גם המקח! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 כאן מדובר כשלא עשאו החותן שליח ממש, אלא \u0003בתגרא דזבין ומזבין\u0004 \u0005[בתגר שקונה ומוכר],\u0006 וכיון שידע בו שעשה מסחר מובן שלא תמיד ירויח במסחרו, ועל דעת כן עשה.","\u0003מלוה אדם את אריסיו חטין בחטין\u0004 לשם \u0003זרע\u0004 ובשעת הקציר יוסיפו לו האריסים על חלקו גם את התבואה שהלוה להם, באותה כמות. \u0003אבל לא\u0004 ילוה חיטים \u0003לאכול\u0004 שיש בכך חשש ריבית, שמא יעלה המחיר. והוצרכו חכמים לומר הלכה זו כיון \u0003שהיה רבן גמליאל מלוה את אריסיו חטין בחטין לזרע, ביוקר והוזלו, או בזול והוקרו\u0004 — היה \u0003נוטל מהן\u0004 תמיד \u0003כשער הזול.\u0004 ובאו חכמים ללמד ש\u0003לא\u0004 עשה כן \u0003מפני שהלכה כן, אלא שרצה להחמיר על עצמו.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מלוה אדם את אריסיו חטים בחטים לזרע. במה דברים אמורים\u0004 — \u0003שלא ירד\u0004 עדיין האריס לשדה להתחיל לעבדו, \u0003אבל\u0004 אם \u0003ירד\u0004 כבר — \u0003אסור.\u0004 ושואלים: \u0003מאי שנא\u0004 \u0005[במה שונה]\u0006 ה\u0003תנא דידן דלא קא מפליג\u0004 \u0005[שלנו\u0006 במשנתנו \u0005שאינו מחלק]\u0006 \u0003בין ירד ובין לא ירד, ומאי שנא\u0004 \u0005[במה שונה]\u0006 ה\u0003תנא ברא דקא מפליג\u0004 \u0005[החיצון,\u0006 של הברייתא, \u0005שמחלק]\u0006 \u0003בין ירד ובין לא ירד?\u0004","\u0003אמר רבא: ר' אידי אסברה ניהלי\u0004 \u0005[הסביר לי]\u0006 את הדבר: \u0003באתרא\u0004 \u0005[במקום]\u0006 של ה\u0003תנא דידן\u0004 \u0005[שלנו]\u0006 \u0003אריסא יהיב ביזרא\u0004 \u0005[האריס\u0006 הוא שנוהג \u0005לתת\u0006 את \u0005הזרעים\u0006 משלו\u0005]\u0006 ולכן, \u0003בין ירד ובין לא ירד\u0004 — \u0003כמה\u0004 (כל עוד) ש\u0003לא יהיב ביזרא מצי מסליק ליה\u0004 \u0005[נתן\u0006 האריס \u0005את הזרע\u0006 בשדה \u0005יכול\u0006 המשכיר \u0005לסלק אותו\u0006 מן השדה\u0005]\u0006 ולכן כשנותן לו זרע הריהו גומר בכך את עיסקת האריסות, \u0003וכי קא נחית\u0004 \u0005[וכאשר הוא יורד]\u0006 לשדה — \u0003לבציר מהכי קא נחית\u0004 \u0005[\u0006\u0005לפחות מזה הוא יורד],\u0006 שיפחית מחלקו ביבול ויתן למשכיר את זרעיו.","ואילו \u0003באתרא\u0004 \u0005[במקום]\u0006 של ה\u0003תנא ברא מרי ארעא יהיב ביזרא\u0004 \u0005[החיצון בעל הקרקע\u0006 הוא ש\u0005נותן\u0006 את \u0005הזרעים]\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003לא ירד\u0004 עדיין \u0003דמצי מסליק ליה\u0004 \u0005[יכול\u0006 המחכיר \u0005לסלק אותו]\u0006 כיון שנתן לו זרעים, \u0003כי קא נחית\u0004 \u0005[אם כאשר הוא יורד]\u0006 — \u0003לבציר מהכי קא נחית\u0004 \u0005[לפחות מזה הוא יורד],\u0006 אבל \u0003אי\u0004 \u0005[אם]\u0006 \u0003ירד דלא מצי מסליק ליה\u0004 \u0005[שאינו יכול לסלק אותו עוד]\u0006 — הרי זה \u0003אסור.\u0004 שכיון שקיבל על עצמו לרדת לשדה ולעבדו מראש בלא קבלת זרעים מבעל השדה נמצא שזרעים אלה הם כהלוואה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אומר אדם לחבירו:\u0004"],["\u0003הלויני כור חטין וקוצץ לו דמים,\u0004 שקובע מה מחיר כור חיטים באותה שעה, \u0003הוזלו\u0004 החיטים בשעת התשלום — \u0003נותן לו חטים, הוקרו\u0004 — \u0003נותן דמיהם\u0004 כפי שקצץ ולא יותר.","ותוהים: מדוע משהוזלו החיטים ישלם לו בחיטים שערכן פחות מן ההלוואה? \u0003והלא קצץ\u0004 סכום מסויים בשעת ההלוואה, ונמצא שסכום זה חייב לו, ואין זו ריבית! \u0003אמר רב ששת: הכי קאמר\u0004 \u0005[כך אמר,\u0006 כך יש להבין\u0005].\u0006 \u0003אם לא קצץ\u0004 אלא הלוה חיטים, אם \u0003הוזלו\u0004 — \u0003נוטל חטיו,\u0004 שהרי לא נדברו שישלם לפי הערך בשעת הנתינה. אם \u0003הוקרו\u0004 — \u0003נותן דמיהם\u0004 כדי שלא ישלם ריבית.","\u0003לא יאמר אדם לחבירו: הלויני כור חטין ואני אתן לך\u0004 אותו בשעת ה\u0003גורן,\u0004 שמא יעלו מחירי החטים, וכשיחזיר לו כור חטה בשעת הגורן — מחזיר יותר משלוה, ונמצא לווה בריבית. \u0003אבל אומר לו: הלויני\u0004 לזמן קצר, כגון \u0003עד שיבא בני או עד שאמצא מפתח\u0004 — שכאן אין לחשוש לשינוי מחירים. \u0003והלל אוסר\u0004 אפילו במקרה זה. \u0003וכן היה הלל אומר: לא תלוה אשה ככר לחברתה עד שתעשיה דמים,\u0004 כלומר, עד שתקצוב מה מחיר ככר זו, \u0003שמא יוקרו\u0004 ה\u0003חטין,\u0004 שעד שתחזירנה לחברתה יתייקר מחיר ככר לחם, \u0003ונמצאו באות לידי\u0004 איסור \u0003רבית.\u0004","\u0003אמר רב הונא:\u0004 מי ש\u0003יש לו סאה\u0004 בעין — \u0003לוה סאה,\u0004 שכיון שיש סאה ברשותו ויכול להחזירה מיד — יכול ללוות סאה אחרת. יש לו \u0003סאתים\u0004 — \u0003לוה סאתים. ר' יצחק אומר: אפילו יש לו סאה\u0004 אחת בלבד — \u0003לוה עליה כמה כורין,\u0004 שכיון שיכול להחזיר משהו מיד, אין ריבית באותה שעה, וכיון שכל האיסור איננו אלא מפני חשש ריבית, אין אנו אוסרים כשאין כל ההלוואה בחשש זה.","ומעירים: \u0003תני\u0004 \u0005[שנה]\u0006 \u0003ר' חייא\u0004 את הברייתא הבאה \u0003לסיועיה\u0004 \u0005[לסייע לו]\u0006 \u0003לר' יצחק: טיפת יין אין לו, טיפת שמן אין לו\u0004 — אינו יכול ללוות סאה בסאה, ומכאן נלמד: \u0003הא\u0004 \u0005[הרי]\u0006 אם \u0003יש לו\u0004 — \u0003לוה עליה כמה\u0004 וכמה \u0003טיפין,\u0004 שוודאי אין מסתבר שבאו להתיר ללוות רק טיפה אחת.","שנינו במשנה ש\u0003הלל אוסר\u0004 אפילו אם הלווה לו בדרך זו לזמן קצר מאד. \u0003אמר רב נחמן אמר שמואל: הלכה כדברי הלל.\u0004 ומעירים: \u0003ולית הלכתא כוותיה\u0004 \u0005[ואין הלכה כמותו],\u0006 כשמואל.","עוד שנינו במשנה, \u0003וכן היה הלל אומר: לא תלוה אשה\u0004 אף ככר לחם בלא לקצוב בשעת ההלוואה את מחירה, שמא תבוא לידי ריבית. \u0003אמר רב יהודה אמר שמואל: זו דברי הלל, אבל חכמים אומרים: לוים\u0004 מיני מאכל \u0003סתם ופורעים סתם,\u0004 כי כאשר אין מדקדקים בחשבונות אין חוששים לדברי הלל.","\u0003ואמר רב יהודה אמר שמואל: בני חבורה ה\u0004אוכלים בצוותא ו\u0003מקפידין זה על זה,\u0004 שכל אחד ישלם בדיוק וללא ויתור מחלקו, אם אוכלים יחד בשבת \u0003עוברין משום מדה, ומשום משקל, ומשום מנין\u0004 שאסור לעשותם בשבת, \u0003ומשום לוין ופורעין ביום טוב, וכדברי הלל אף משום רבית.\u0004","\u0003ואמר רב יהודה אמר שמואל: תלמידי חכמים מותרים ללוות זה מזה ברבית.\u0004 ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 — הלא \u0003מידע ידעי\u0004 \u0005[יודעים הם]\u0006 ש\u0003רבית אסורה,\u0004 ואין מתכוונים ממש לעיסקה מסחרית, אלא מראש ומדעת הם מוחלים, \u0003ומתנה הוא דיהבו אהדדי\u0004 \u0005[היא ש\u0006הם \u0005נותנים זה לזה].\u0006 וכיוצא בזה מסופר: \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003שמואל לאבוה בר איהי: הלויני מאה פלפלין במאה ועשרין פלפלין\u0004 שאתן לך לאחר זמן \u0003ו\u0004דע כי דבר זה \u0003אריך\u0004 \u0005[הגון,\u0006 ראוי\u0005],\u0006 לפי שמראש מכוון הוא לשם מתנה.","כעין זה \u0003אמר רב יהודה אמר רב: מותר לו לאדם להלוות בניו ובני ביתו ברבית, כדי להטעימן טעם רבית,\u0004 שידעו כמה גדלה הריבית וכמה קשה לשלם — שלא יבואו ללוות בריבית. ומעירים: \u0003ולאו מילתא היא\u0004 \u0005[ואין זה דבר\u0006 ראוי\u0005]\u0006 \u0003משום דאתי למיסרך\u0004 \u0005[שעלול להתרגל]\u0006 בענין זה של הלוואה בריבית. וימשיכו לעשותו גם עם אחרים, כשאין בכך כל היתר.","\u0003אומר אדם לחבירו: נכש\u0004 (הוצא את עשבי הבר) \u0003עמי\u0004 עכשיו בשדה שלי, ואני \u0003אנכש עמך\u0004 ליום אחר, \u0003עדור עמי ואעדור עמך.\u0004 אבל \u0003לא יאמר לו: נכש עמי\u0004 היום \u0003ואעדור עמך\u0004 מחר, או \u0003עדור עמי\u0004 היום \u0003ואנכש עמך\u0004 מחר, שכיון שאין המלאכות שוות — יתכן שהחבר יצטרך לעבוד יותר משעבדו עבורו, ונמצא כאן מעין ריבית של תוספת מלאכה."],["\u0003כל ימי גריד\u0004 (ימי היובש) — שיעורם \u0003אחד.\u0004 שמי שהסכים לעבוד יום תמורת יום מחשיבים אנו את ימי הגריד כאילו היו באותו אורך בדיוק (למרות ההבדל הקטן בין יום ליום), וכן \u0003כל ימי רביעה\u0004 נחשבים לתקופה \u0003אחת,\u0004 אבל \u0003לא יאמר לו: חרוש עמי בגריד ואני אחרוש עמך ברביעה\u0004 וכיוצא בזה.","ולענין הגדרת תחומה של ריבית: \u0003רבן גמליאל אומר: יש רבית מוקדמת ויש רבית מאוחרת,\u0004 ושתיהן אסורות. \u0003כיצד? נתן עיניו ללוות הימנו\u0004 (ממנו), שרצונו ללוות מחבירו, \u0003והוא משלח לו\u0004 כסף או מתנה \u0003ואומר:\u0004 הריני נותן לך מתנה זו \u0003בשביל שתלוני\u0004 — \u0003זו היא רבית מוקדמת,\u0004 שהרי משלם לו יותר על ההלוואה אף כי עדיין לא לוה. וכן אם \u0003לוה הימנו והחזיר לו את מעותיו, והוא משלח לו\u0004 אחר כך מתנה \u0003ואומר: בשביל מעותיך שהיו בטילות\u0004 מלהרויח עבורך והיו \u0003אצלי\u0004 — \u0003זו היא רבית מאוחרת.\u0004 \u0003ר' שמעון אומר: יש רבית\u0004 לא רק בכסף ושווה כסף, אלא גם ב\u0003דברים.\u0004 וכגון: \u0003לא יאמר לו\u0004 הלווה למלוה \u0003\"דע כי בא איש פלוני ממקום פלוני\"\u0004 כשהוא יודע שהמלוה היה מעונין בידיעה זו, שכיון שמתכוון לעשות הנאה למלווה, ונמצא כמשלם לו תמורה נוספת על הכסף שהלווהו, ויש בכך משום ריבית.","","\u0003ואלו עוברין\u0004 במצוות \u0003\"לא תעשה\"\u0004 שבריבית: \u0003המלוה, והלוה, והערב\u0004 על שטר זה, \u0003והעדים. וחכמים אומרים: אף הסופר\u0004 הכותב את השטר. משום איסורים אלה \u0003עוברים\u0004 המשתתפים בהלוואה, כל אחד לפי עניינו \u0003משום\u0004 \"את כספך \u0003לא תתן\u0004 לו בנשך\" (ויקרא כה, לז), \u0003ומשום \"אל תקח מאתו\u0004 נשך ותרבית\u0003\"\u0004 (שם לו), \u0003ומשום \"לא תהיה לו כנשה\"\u0004 (שמות כב, כד), \u0003ומשום \"לא תשימון עליו נשך\"\u0004 (שם), \u0003ומשום \"ולפני עור לא תתן מכשל ויראת מאלהיך אני ה'\"\u0004 (ויקרא יט, יד).","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' שמעון בן יוחי אומר: מנין לנושה בחבירו מנה, ואינו רגיל\u0004 בדרך כלל \u0003להקדים לו שלום\u0004 למלוה, \u0003שאסור\u0004 לאחר ההלוואה \u0003להקדים לו שלום\u0004 — \u0003תלמוד לומר: \"נשך כל דבר אשר ישך\"\u0004 (דברים כג, כ) — לומר: \u0003אפילו דיבור\u0004 (\"דבר\") \u0003אסור,\u0004 שגם הוא יש בו משום ריבית.","שנינו במשנה: \u0003ואלו עוברין\u0004 משום ריבית, ורשימה של לאוין האמורים בענין זה. \u0003אמר אביי: מלוה\u0004 בריבית \u0003עובר בכולן,\u0004 בכל מצוות לא תעשה הללו. \u0003לוה עובר משום \"לא תשיך לאחיך\"\u0004 (שם), שהרי הוא מסייע לאחיו לנשוך. והוא המשיך: ועוברים משום \u0003\"ולאחיך לא תשיך\"\u0004 (שם כא), ומשום \u0003\"ולפני עור לא תתן מכשל\"\u0004 (ויקרא יט, יד), ה\u0003ערב והעדים אין עוברין אלא משום \"לא תשימון עליו נשך\".\u0004 \u0003תניא, ר' שמעון אומר: מלוי\u0004 ב\u0003רבית יותר ממה שמרויחים\u0004 — \u0003מפסידים,\u0004 שהרי לבסוף ייענשו בידי שמים. \u0003ולא עוד אלא\u0004 שבעשיית הלוואה כזו יש משום חילול השם \u0003שמשימים משה רבינו חכם ותורתו אמת.\u0004 כלומר, אמר בלשון נקיה וכוונתו שבמעשיהם שמים הם ללעג את משה ותורת משה, ואומרים: \u0003אילו היה יודע משה רבינו שיהיה ריוח בדבר לא היה כותבו,\u0004 שיש איסור בכך, ונמצא שלא רק שעברו על המצוה אלא אף זלזלו בתורה.","","ועוד מביאים דברים אחדים בענין ההלוואות בכלל. \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל \u0003אמר: מנין לנושה בחבירו מנה, ויודע שאין לו\u0004 לחבר לשלם \u0003שאסור לעבור לפניו\u0004 שלא יתבייש ולא יצטער החבר — \u0003תלמוד לומר: \"לא תהיה לו כנשה\"\u0004 (שמות כב, כד), שגם אם אינו נושה ותובע — הריהו כנושה, ומצער אותו. \u0003ור' אמי ור' אסי דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 מי שמצער את חבירו הרי זה \u0003כאילו דנו בשני דינין,\u0004 בשני מיני יסורים, \u0003שנאמר: \"הרכבת אנוש לראשנו באנו באש ובמים\"\u0004 (תהילים סו, יא), שאם נעשה לו כנושה הרי זה כאילו מביאו באש ובמים.","","\u0003אמר רב יהודה אמר רב: כל מי שיש לו מעות ומלוה אותן שלא בעדים\u0004 — \u0003עובר משום \"ולפני עור לא תתן מכשל\"\u0004 (ויקרא יט, יד), שעלול להגרם מכשול בדבר שמא יתפתה אותו אדם ולא ירצה לפרוע. \u0003וריש לקיש אמר: גורם קללה לעצמו, שנאמר: \"תאלמנה שפתי שקר הדברות על צדיק עתק\u0004 בגאוה ובוז\u0003\"\u0004 (תהלים לא, יט), שהרי כשיבוא המלוה לתבוע, ולא תהיה בידו ראיה, יאמרו הבריות שהעליל לחינם על אחר, ונמצא שהביא קללה על עצמו מידי הבריות.","אגב כך מספרים, \u0003אמרו ליה רבנן\u0004 \u0005[לו חכמים]\u0006 \u0003לרב אשי: קא מקיים רבינא\u0004 את \u0003כל מה דאמור רבנן\u0004 \u0005[שאמרו חכמים]\u0006 דבר קטן ודבר גדול. רצה רב אשי לנסותו, \u0003שלח ליה\u0004 \u0005[לו]\u0006 שליח \u0003בהדי פניא דמעלי שבתא\u0004 \u0005[סמוך לערב של יום ששי]\u0006 קרוב לשבת, בשעה שהכל טרודים, לומר לו: \u0003לישדר\u0004 \u0005[ישלח]\u0006 \u0003לי מר\u0004 \u0005[אדוני]\u0006 \u0003עשרה זוזי\u0004 \u0005[זוזים]\u0006 בהלוואה \u0003דאתרמי\u0004 \u0005[שהזדמנה]\u0006 \u0003לי קטינא דארעא למזבן\u0004 \u0005[\u0006חלקה \u0005קטנה של קרקע לקנות]\u0006 ואני זקוק לכסף. \u0003שלח ליה\u0004 \u0005[לו]:\u0006 \u0003ניתי מר סהדי ונכתב כתבא\u0004 \u0005[שיביא אדוני עדים ושיכתוב כתב],\u0006 שטר על ההלוואה הזאת. \u0003שלח ליה\u0004 \u0005[לו]\u0006 רב אשי: \u0003אפילו אנא נמי\u0004 \u0005[אני גם כן]?!\u0006 האם גם בי אתה חושד שלא אשלם? \u0003שלח ליה\u0004 \u0005[לו]:\u0006 \u0003כל שכן מר דטריד בגירסיה משתלי\u0004 \u0005[אדוני ש\u0006הוא \u0005טרוד בלימודו\u0006 ועלול באמת \u0005לשכוח]\u0006 ונמצא אני \u0003גורם קללה לעצמי.\u0004","בדומה לזה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003שלשה צועקין ואינן נענין\u0004 כיון שהם גרמו לעצמם, \u0003ואלו הן: מי שיש לו מעות ומלוה אותן שלא בעדים, והקונה אדון לעצמו, ומי שאשתו מושלת עליו.\u0004","ומסבירים: \u0003קונה אדון לעצמו מאי היא\u0004 \u0005[מה הוא\u0006 מה עניינו\u0005]?\u0006 \u0003איכא דאמרי\u0004 \u0005[יש אומרים]:\u0006 \u0003תולה נכסיו בגוי,\u0004 שלעיתים רצונו להשתמט ואומר על נכסיו שהם של גוי, ומזדמן שהגוי משתמש בהודעה זו, ובא ולוקח את נכסיו. \u0003איכא דאמרי\u0004 \u0005[יש אומרים]\u0006 שהכוונה היא לזה \u0003הכותב\u0004 (נותן במתנה) \u0003נכסיו לבניו בחייו,\u0004 שעושה אותם אדונים עליו, ו\u0003איכא דאמרי\u0004 \u0005[ויש אומרים]:\u0006 \u0003דביש ליה בהא מתא ולא אזיל למתא אחריתא\u0004 \u0005[מי שרע לו בעיר זו ואינו הולך לעיר אחרת]\u0006 שנמצא שהוא גרם לעצמו את הצרה.","","\u0003השוכר את האומנין והטעו זה את זה\u0004 — \u0003אין להם זה על זה אלא תרעומות,\u0004 ואולם אין כאן מקום לגבות כספים על הנזקים שנגרמו. אבל אם \u0003שכר את החמר ואת הקדר להביא פרייפרין\u0004 (מוטות לאפיריון), או \u0003חלילים ל\u0004נגן לכבוד ה\u0003כלה או למת,\u0004 או ששכר \u0003פועלין להעלות\u0004 את \u0003פשתנו מן המשרה\u0004 (המים שהפשתן שרוי בהם כשלב ראשון של עיבוד), \u0003ו\u0004כן \u0003כל דבר שאבד\u0004 אם לא יעשוהו בזמנו, \u0003וחזרו בהן\u0004 אלה, אם היה זה \u0003מקום שאין שם אדם\u0004 אחר לעשות מלאכה זו — \u0003שוכר עליהן\u0004 במקומם אנשים בשכר מרובה \u0003או מטען\u0004 (מטעה ומרמה אותם) כדי שיחזרו לעבודה. ודין אחר: \u0003השוכר את האומנין\u0004 לעשות מלאכה \u0003וחזרו בהן\u0004 באמצע המלאכה — \u0003ידם על התחתונה,\u0004 כלומר, הם יצטרכו לשלם באופן שלעולם לא יפסיד הוא בכך.",""],["\u0003אם בעל הבית חוזר בו\u0004 — \u0003ידו על התחתונה.\u0004 כלל הוא: \u0003כל המשנה\u0004 דבר ממה שהסכים עליו מראש — \u0003ידו על התחתונה, וכל החוזר בו\u0004 מן ההסכם — \u0003ידו על התחתונה.\u0004","בתחילה מנסים לפרש את לשון המשנה \"והטעו זה את זה\". ומעירים: \u0003\"חזרו זה בזה\"\u0004 \u0003לא קתני\u0004 \u0005[שנה],\u0006 משמע שאין הכוונה שבעל הבית או הפועלים חזרו בהן, \u0003אלא\u0004 בהכרח יש להבין כי \u0003\"הטעו זה את זה\",\u0004 משמעו: \u0003דאטעו\u0004 \u0005[שהטעו]\u0006 ה\u0003פועלים אהדדי\u0004 \u0005[זה את זה].\u0006 ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק הדבר]?\u0006 ומסבירים: כגון ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003בעל הבית\u0004 לפועל אחד: \u0003זיל, אוגר\u0004 \u0005[לך\u0006 ו\u0005שכור]\u0006 \u0003לי פועלים,\u0004 \u0003ואזל איהו ואטעינהו\u0004 \u0005[והלך הוא והטעה אותם,\u0006 את הפועלים\u0005].\u0006","ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק]\u0006 הטעה אותם? \u0003אי\u0004 \u0005[אם]\u0006 ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003בעל הבית\u0004 שישכור פועלים \u0003בארבעה\u0004 זוזים, \u0003ואזיל איהו\u0004 \u0005[והלך הוא]\u0006 השליח ו\u0003אמר להו\u0004 \u0005[להם]\u0006 שרוצה בעל הבית לתת להם \u0003ב\u0004שכרם \u0003תלתא\u0004 \u0005[שלושה]\u0006 ונשכרו בשלושה, \u0003תרעומת\u0004 זו \u0003מאי עבידתיה\u0004 \u0005[מה מעשיה]?\u0006 הלא \u0003סבור וקביל\u0004 \u0005[סברו וקבלו]\u0006 לעבוד בשלושה, ומה להם להתרעם עליו? \u0003אי\u0004 \u0005[אם]\u0006 ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003בעל הבית\u0004 שכור לי פועלים \u0003בתלתא\u0004 \u0005[בשלושה],\u0006 \u0003ואזיל איהו\u0004 \u0005[והלך הוא]\u0006 השליח ו\u0003אמר להו\u0004 \u0005[להם]\u0006 שרוצה בעל הבית לתת להם \u0003ב\u0004שכרם \u0003ארבעה\u0004 — נבדוק, \u0003היכי דמי\u0004 \u0005[כיצד בדיוק הדבר]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 ש\u0003אמר להו\u0004 \u0005[להם]\u0006 השליח בשעה ששכרם: \u0003\"שכרכם עלי\"\u0004 — \u0003נתיב להו מדידיה\u0004 \u0005[שיתן להם משלו],\u0006","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005];\u0006 \u0003השוכר את הפועל לעשות\u0004 מלאכה \u0003ב\u0004שדה מ\u0003שלו והראהו בשל חבירו\u0004 ועשה הפועל בשדה החבר — \u0003נותן לו\u0004 לפועל \u0003שכרו משלם\u0004 ככל שהתנה עמו, \u0003וחוזר ונוטל מבעל הבית מה שההנהו,\u0004 מה שהרויח בעל השדה מכך, אבל לא את כל שכרו של הפועל. ומכאן, שאם אמר \"שכרכם עלי\" — הריהו משלם כפי שאמר.","ומסבירים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא לאופן ש\u0003אמר להו\u0004 \u0005[להם]\u0006 השליח: \u0003שכרכם על בעל הבית,\u0004 ואחר כך התברר שבעל הבית משלם פחות, ואז אין להם אלא תרעומת על השליח.","ושואלים: \u0003ולחזי\u0004 \u0005[ושנראה]\u0006 \u0003פועלים היכי מיתגרי\u0004 \u0005[איך\u0006 הם \u0005נשכרים]\u0006 באותו מקום, וישלם בעל הבית לפועלים כמקובל! ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא לאופן \u0003דאיכא דמגר\u0004 \u0005[שיש\u0006 מי \u0005שנשכר]\u0006 \u0003בארבעה ואיכא דמתגר בתלתא\u0004 \u0005[ויש\u0006 מי \u0005שנשכר בשלושה],\u0006 \u0003דאמרו ליה\u0004 \u0005[שאומרים לו]\u0006 הפועלים: \u0003אי לאו\u0004 \u0005[אם לא]\u0006 ש\u0003אמרת לן\u0004 \u0005[לנו]\u0006 ש\u0003בארבעה\u0004 — \u0003טרחינן ומתגרינן\u0004 \u0005[אם לא שאמרת לנו שבארבעה,\u0006 היינו \u0005טורחים\u0006 עד שנמצא \u0005ונשכרים]\u0006 \u0003בארבעה\u0004 ואתה גרמת שנפסיד.","\u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 שהוא הדין אף כשיש במקום שכר קבוע לפועל, ואולם \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003בבעל הבית\u0004 הנשכר לעבודה, שאינו שכיר קבוע, \u0003עסקינן\u0004 \u0005[\u0006\u0005עוסקים אנו],\u0006 אלא יש לו קרקע לעצמו, ולהשלמת פרנסתו נשכר לפעמים לאחרים. \u0003דאמרו ליה\u0004 \u0005[שאומרים לו]\u0006 השכירים: \u0003אי לאו\u0004 \u0005[אם לא]\u0006 ש\u0003אמרת לן\u0004 \u0005[לנו]\u0006 \u0003בארבעה הוה זילא בן מילתא לאתגורי\u0004 \u0005[היה מזולזל בעינינו להישכר\u0006 כפועלים\u0005]\u0006 ועל הזלזול שגרמת לנו יש לנו תרעומת.","\u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]:\u0006 \u0003לעולם בפועלים,\u0004 שכירים רגילים, \u0003עסקינן\u0004 \u0005[אנו עוסקים]\u0006 ולא בבעל בית, ותרעומת שלהם; \u0003דאמרי ליה\u0004 \u0005[ש\u0006הם \u0005אומרים לו]\u0006 לשליח: \u0003כיון\u0004 ש\u0003אמרת לן\u0004 \u0005[לנו]\u0006 \u0003בארבעה\u0004 — \u0003טרחינן ועבדינן\u0004 \u0005[אנחנו טורחים ועושים]\u0006 \u0003לך עבידתא שפירתא\u0004 \u0005[מלאכה טובה יותר].\u0006 ושואלים: \u0003ולחזי עבידתייהו\u0004 \u0005[ונראה\u0006 את \u0005עבודתם],\u0006 שאם אמנם היתה עבודתם משובחת יותר, מגיע להם יותר. ומשיבים: כאן מדובר \u0003בריפקא\u0004 \u0005[בעידור],\u0006 שאין טיב העבודה ניכר היטב. ושואלים: \u0003ריפקא נמי מידע ידע\u0004 \u0005[עידור גם כן יודע הוא]\u0006 מה טיב העבודה. ומשיבים: \u0003דמלי מיא ולא ידיע\u0004 \u0005[שמילא מים ואינו ידוע],\u0006 שהפועלים עבדו וחפרו אמת מים, וכבר נתמלאה במים, כך שאין לדעת כיצד עבדו.","\u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]:\u0006 \u0003לעולם\u0004 מדובר באופן ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003בעל הבית\u0004 לשליח: שכור פועלים \u0003בארבעה, ואזל איהו\u0004 \u0005והלך הוא\u0006 ו\u0003אמר להו בתלתא\u0004 \u0005[להם בשלושה],\u0006 \u0003ודקאמרת סבור וקביל\u0004 \u0005[ו\u0006מה \u0005שאתה אומר\u0006 שהרי הם \u0005סברו וקבלו]\u0006 הדבר נכון לענין הדין, אבל יש להם מקום לתרעומת, \u0003דאמרי ליה\u0004 \u0005[ש\u0006הם \u0005אומרים לו]\u0006 וכי \u0003לית\u0004 \u0005[אין]\u0006 \u0003לך,\u0004 אינך סבור שצריך לקיים את דברי הכתוב \u0003\"אל תמנע טוב מבעליו\u0004 בהיות לאל ידך לעשות\" (משלי ג, כז)?","הגענו איפוא להסבר לגבי מצב הדברים שמדובר בו במשנתנו, ומעתה באים לברר כמה בעיות בנושא זה. ומקדימים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003בעל הבית\u0004 לשליח שישכור פועלים \u0003בתלתא\u0004 \u0005[בשלושה],\u0006 \u0003ואזל איהו\u0004 \u0005[והלך הוא]\u0006 ו\u0003אמר להו\u0004 \u0005[הם]\u0006 \u0003בארבעה,\u0004 \u0003ואמרי ליה\u0004 \u0005[ו\u0006הם \u0005אומרים לו]\u0006 אנו נקבל תשלום \u0003כמה שאמר בעל הבית\u0004 — במקרה כזה מובן כי \u0003דעתייהו אעילויא\u0004 \u0005[דעתם\u0006 היא \u0005על הוספה]\u0006 שמא אמר בעל הבית יותר, ולא נתכוונו לפחות משכרם.","\u0003אלא אי\u0004 \u0005[אם]\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003בעל הבית בארבעה, ואזל איהו\u0004 \u0005[והלך הוא]\u0006 ו\u0003אמר להו בתלתא\u0004 \u0005[להם בשלושה],\u0006 \u0003ואמרי\u0004 \u0005[ואומרים\u0006 הם\u0005]\u0006 לו: \u0003כמה שאמר בעל הבית, מאי\u0004 \u0005[מה]\u0006 יהא הדין? האם נאמר כי \u0003אדיבורא דידיה קא סמכי\u0004 \u0005[על הדיבור שלו הם סומכים],\u0006 \u0003דאמרי ליה\u0004 \u0005[ש\u0006הם \u0005אומרים לו,\u0006 כוונתם לומר\u0005]\u0006 \u0003מהימנת לן דהכי\u0004 \u0005[נאמן אתה עלינו שכך]\u0006 \u0003אמר בעל הבית,\u0004 \u0003או דלמא אדיבורא\u0004 \u0005[שמא על הדיבור]\u0006 של \u0003בעל הבית קא סמכי\u0004 \u0005[הם סומכים]\u0006 ולכן מגיע להם כמו שאמר בעל הבית.","ומציעים: \u0003תא שמע\u0004 \u0005[בא\u0006 ו\u0005שמע],\u0006 פתרון לשאלה זו ממה ששנינו לענין גיטין: אמרה אשה לשליח \u0003\"הבא לי גיטי\".\u0004 שידעה שבעלה יכתוב לה גט, וביקשה מן השליח שהוא יביא את הגט לידה, וכאשר תקבל את הגט — אז תהיה מגורשת,","והלך השליח ואמר לבעל: \u0003אשתך אמרה \"התקבל לי גיטי\".\u0004 כלומר, אשתך מינתה אותי לשליח לקבל במקומה את הגט, ואם השליח הוא אכן 'שליח קבלה לגט', הרי כשמגיע הגט לידי השליח — מיד האשה מגורשת. \u0003והוא,\u0004 הבעל שנותן גט, \u0003אומר: \"הילך כמה שאמרה\u0004 אשתי\u0003\".\u0004 בנושא זה \u0003אמר רב נחמן אמר רבה בר אבוה אמר רב: אפילו\u0004 כאשר \u0003הגיע\u0004 ה\u0003גט לידה\u0004 — \u0003אינה מגורשת.\u0004","ואם כן \u0003שמעת מינה אדיבורא דידיה קא סמיך\u0004 \u0005[שומע אתה מכאן\u0006 כי \u0005על הדיבור שלו,\u0006 של השליח, \u0005הוא סומך],\u0006 שכיון שהבעל סבור שהשליח הוא שליח לקבלה — ממילא לא עשאו להולכת הגט אל האשה, וכיון שבאמת לא היה שליח לקבלה לא היתה כאן מסירת גט כראוי, ולכן אינה מגורשת. \u0003דאי סלקא דעתך אדיבורא דידה קא סמיך\u0004 \u0005[שאם עולה בדעתך\u0006 לומר כי \u0005על הדיבור שלה הוא סומך]\u0006 — \u0003מכי מטי גיטא לידה מיהא תיגרש\u0004 \u0005[מכאשר מגיע הגט לידה על כל פנים תתגרש],\u0006 שהרי נעשה שליח להולכה, וכשיגיע הגט לידה — הרי זה גט. ומכאן נלמד שבמקרה כגון זה, השומע סומך על דברי השליח וסבור שכך אכן אמר לו המשלח. \u0003אמר רב אשי:\u0004"],["\u0003הכי השתא\u0004 \u0005[כיצד אתה משווה]?!\u0006 \u0003בשלמא אי איתמר איפכא\u0004 \u0005[נניח אילו היה נאמר ההיפך],\u0006 שהיינו דנים במקרה הפוך; שהיא אמרה לשליח \u0003\"התקבל לי גיטי\" ו\u0004הוא הלך לבעל ואמר \u0003\"אשתך אמרה הבא לי גיטי\", והוא\u0004 הבעל \u0003אומר: \"הילך כמו שאמרה\". ו\u0004אילו \u0003אמר רב נחמן אמר רבה בר אבוה אמר רב\u0004 על זה: \u0003משיגיע גט לידו\u0004 הריהי \u0003מגורשת,\u0004 הרי היתה זו ראיה — \u0003אלמא\u0004 \u0005[מכאן]\u0006 \u0003דאדיבורא דידה קא סמיך\u0004 \u0005[שעל הדיבור שלה הוא סומך].\u0006","\u0003אי נמי\u0004 \u0005[או גם כן]\u0006 אם באותו מקרה היה אומר: \u0003משהגיע גט לידה מגורשת\u0004 — הייתי מוכיח \u0003אלמא\u0004 \u0005[מכאן]\u0006 \u0003דאדיבורא דידיה קא סמיך\u0004 \u0005[שעל הדיבור שלו הוא סומך].\u0006 \u0003אלא התם\u0004 \u0005[שם]\u0006 במקרה שבאמת אמר רבה בר אבוה — אין הטעם משום שסמך או לא סמך על דעתה שלה, אלא \u0003משום\u0004 ש\u0003עקר\u0004 ה\u0003שליח לשליחותיה\u0004 \u0005[את שליחותו]\u0006 \u0003לגמרי\u0004 ובעצם אינו עוד שליח. ומדוע — ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 לבעל: \u0003\"שליח לקבלה הוינא\u0004 \u0005[אני],\u0006 ו\u0003להולכה לא הוינא\u0004 \u0005[אינני]\u0006 \u0003\",\u0004 וכיון שלא נתמנה כלל להיות שליח לקבלה — פסקה שליחותו, ולכן אין בה ממש. והשאלה לא נפתרה איפוא.","ושוב אנו חוזרים לפירוש המשנה גופה, לגבי הביטוי של \"הטעו זה את זה\", ומציעים הצעה שונה לגמרי: \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]:\u0006 \u0003האי תנא\u0004 \u0005[תנא זה]\u0006 במשנתנו גם אם \u0003\"חזרו\"\u0004 בהם הצדדים \u0003נמי\u0004 \u0005[גם כן]\u0006 בלשון \u0003\"הטעו\" קרי ליה\u0004 \u0005[קורא לו],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 כיוצא בזה: \u0003השוכר את האומנין והטעו את בעל הבית, או\u0004 ש\u0003בעל הבית הטעה אותן\u0004 — \u0003אין להם זה על זה אלא תרעומת.\u0004","וממשיכה הברייתא: \u0003במה דברים אמורים\u0004 — \u0003שלא הלכו\u0004 למקום העבודה אלא חזר בו בעל הבית מיד. \u0003אבל\u0004 אם כבר \u0003הלכו\u0004 ה\u0003חמרים ולא מצאו תבואה\u0004 להוביל, או שהלכו ה\u0003פועלין\u0004 לעבוד \u0003ומצאו שדה כשהיא לחה\u0004 ואי אפשר לעבד אותה בעידור — \u0003נותן להן\u0004 בעל הבית \u0003שכרן משלם, אבל\u0004 אינו נותן להם שכר עבודה מלא, כי \u0003אינו דומה הבא טעון לבא ריקן,\u0004 ואינו דומה ה\u0003עושה מלאכה ליושב ובטל.\u0004","\u0003במה דברים אמורים\u0004 שאם חזרו בהם אין להם אלא תרעומת — כ\u0003שלא התחילו\u0004 כלל \u0003במלאכה, אבל\u0004 אם כבר \u0003התחילו במלאכה\u0004 — \u0003שמין\u0004 (מעריכים) \u0003להן מה שעשו,\u0004 ומקבלים תמורה מסויימת עבור מה שגמרו. \u0003כיצד?\u0004 — \u0003קבלו קמה לקצור\u0004 את כולה בקבלנות \u0003בשני סלעים,\u0004 ו\u0003קצרו חציה והניחו חציה.\u0004 או שקיבלו על עצמם \u0003בגד לארוג\u0004 את כולו \u0003בשני סלעים,\u0004 ו\u0003ארגו חציו והניחו חציו\u0004 — במקרה כזה \u0003שמין להן את מה שעשו,\u0004 כיצד?","— אם \u0003היה\u0004 מה שצריכים להשלים \u0003יפה\u0004 (שווה) \u0003ששה דינרים\u0004 שהוא סלע וחצי, כגון שנתייקר שכר העבודה — \u0003נותן להם סלע\u0004 כפי הסכום שהתנו מראש, שאין העובדים מפסידים שכר שנקצב להם, \u0003או יגמרו מלאכתן ויטלו שני סלעים. ואם\u0004 צריך להשלים כדי \u0003סלע\u0004 — \u0003נותן להם סלע.\u0004","ואילו \u0003ר' דוסא אומר: שמין\u0004 (מעריכים) \u0003להם\u0004 את \u0003מה שעתיד להעשות,\u0004 אם \u0003היה יפה\u0004 לפי האומדן \u0003ששה דינרים,\u0004 כלומר, שעדיין שווה ששה דינרים, שמה שצריך להיעשות אפשר לעשותו על ידי פועלים אחרים רק בששה דינרים — \u0003נותן להם שקל\u0004 (חצי סלע), \u0003או\u0004 ש\u0003יגמרו מלאכתן ויטלו שני סלעים. ואם\u0004 צריך להשלים כדי \u0003סלע\u0004 — \u0003נותן להם סלע.\u0004","\u0003במה דברים אמורים,\u0004 שהפועלים מקבלים שכר על מה שעבדו ואין לבעל הבית אלא תרעומת — \u0003בדבר שאין אבוד\u0004 על ידי שביתת הפועלים, \u0003אבל בדבר\u0004 \u0003ה\u0004עלול להיות \u0003אבוד\u0004 — \u0003שוכר עליהן\u0004 (על חשבונם) פועלים אחרים ביוקר \u0003או מטען. כיצד מטען?\u0004 — \u0003אומר להן\u0004 למשל: \u0003סלע קצצתי לכם\u0004 — \u0003באו וטלו שתים. ועד כמה שוכר עליהן\u0004 — \u0003עד ארבעים וחמשים זוז,\u0004 שיכול לשכור פועלים אחרים ולהוסיף להם הרבה מאוד על שכרם כדי שיגמרו את העבודה.","ובדבר האבוד, \u0003במה דברים אמורים\u0004 — \u0003בזמן שאין שם פועלים\u0004 אחרים \u0003לשכור\u0004 באותו מקום ונמצא בעל הבית מפסיד הרבה, ומותר לו להשתמש בדרכים אלה. \u0003אבל\u0004 אם \u0003יש שם פועלים\u0004 אחרים \u0003לשכור, ואמר\u0004 הפועל שחזר בו לבעל הבית: \u0003\"צא ושכור מאלו\"\u0004 — \u0003אין לו עליהן אלא תרעומת.\u0004","\u0003תני תנא קמיה\u0004 \u0005[שנה חוזר המשניות בפני]\u0006 \u0003רב\u0004 בברייתא זו: \u0003נותן להם שכרן משלם. אמר ליה\u0004 \u0005[לו]:\u0006 \u0003חביבי\u0004 \u0005[דודי,\u0006 ר' חייא\u0005]\u0006 \u0003אמר: אילו אנא הואי\u0004 \u0005[אני הייתי\u0006 פוסק\u0005]\u0006 — \u0003לא הוה יהיבנא\u0004 \u0005[הייתי נותן,\u0006 פוסק\u0005]\u0006 \u0003להן\u0004 \u0003אלא כפועל בטל\u0004 ולא יותר, \u0003ואת אמרת\u0004 \u0005[ואתה אומר]\u0006 \u0003נותן להם שכרם משלם!\u0004 ושואלים: \u0003והא עלה קתני\u0004 \u0005[והרי עליה,\u0006 על קטע זה שבברייתא, \u0005שנו\u0006 מיד אחר כך\u0005]:\u0006 \u0003אינו דומה הבא טעון להבא ריקן, עושה מלאכה ליושב ובטל!\u0004 ומשיבים: \u0003לא סיימוה,\u0004 את הברייתא \u0003קמיה\u0004 \u0005[לפניו]\u0006 ולכן אמר שאין מגיע להם כל שכרם.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 ושונים בנוסח אחר: שבאמת \u0003סיימוה קמיה\u0004 \u0005[לפניו],\u0006 \u0003והכי קאמר\u0004 \u0005[וכך אמר],\u0006 \u0003חביבי אמר: אי הואי אנא\u0004 \u0005[אם הייתי אני]\u0006 פוסק — \u0003לא הוה יהיבנא ליה\u0004 \u0005[הייתי נון,\u0006 פוסק \u0005לו]\u0006 \u0003כלל,\u0004 \u0003ואת אמרת\u0004 \u0005[ואתה אומר]\u0006 \u0003כפועל בטל!\u0004 ושואלים: \u0003אלא\u0004 אם כן \u0003קשיא\u0004 \u0005[קשה\u0006 באמת\u0005]\u0006 וכיצד נסביר את ההבדל בין הברייתות והשיטות? ומשיבים: \u0003הך\u0004","\u0003לא קשיא\u0004 \u0005[זו אינה קשה]:\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שאמר שאינם מקבלים כלל — הרי זה באופן \u0003דסיירא לארעיה מדאורתא\u0004 \u0005[שסייר\u0006 ובדק את \u0005אדמתו מבערב]\u0006 והוליך גם את הפועלים עימו, ומכיון שהם עצמם ראוה הרי שהיה להם להעלות על דעתם שיירדו גשמים ולא תהיה השדה ראויה לעיבוד, שעל דעת כן נשכרו לו, ולא היה להם איפוא ללכת אליה בבוקר, ולכך הפסידו. \u0003הא\u0004 \u0005[זה]\u0006 שאמר שהם מקבלים כפועל בטל — הרי זה באופן ש\u0003לא סיירא לארעיה מאורתא\u0004 \u0005[סייר באדמתו מבערב],\u0006 שכיון שלא עשה את המוטל עליו ולא בדק כראוי — האחריות עליו.","\u0003כי הא\u0004 \u0005[כמו זו]\u0006 ש\u0003אמר רבא:\u0004 \u0003האי מאן דאגר אגירי לרפקא\u0004 \u0003ואתא מטרא ומלייה מיא\u0004 \u0005[מי ששכר שכירים לעדור ובא הגשם ומילא\u0006 את האדמה הזו \u0005מים]\u0006 שאי אפשר לעדור בה, \u0003אי סיירא לארעיה מאורתא\u0004 \u0005[אם סייר באדמתו מבערב]\u0006 עם הפועלים ועשה כל מה שהוא יכול"],["\u0003פסידא\u0004 \u0005[הפסד]\u0006 של ה\u0003פועלים\u0004 ומזלם הרע הוא שגרם. ואם \u0003לא סיירא לארעיה מאורתא\u0004 \u0005[סייר את קרקעו מן הערב]\u0006 — הרי זה \u0003פסידא\u0004 \u0005[הפסד]\u0006 של \u0003בעל הבית ויהיב להו\u0004 \u0005[ונותן להם]\u0006 שכרם \u0003כ\u0004מו שמשלמים ל\u0003פועל בטל.\u0004","ועוד \u0003אמר רבא: האי מאן דאוגיר אגורי לדוולא\u0004 \u0005[מי ששכר פועלים לדלות מים]\u0006 מן הנהר או מן התעלה, להשקות את שדהו, \u0003ואתא מטרא\u0004 \u0005[ובא הגשם]\u0006 ולא הוצרך עוד לפועלים — הרי זה \u0003פסידא\u0004 \u0005[הפסד]\u0006 של ה\u0003פועלים,\u0004 ולא ישלם להם, שהרי לא יכול לדעת מראש. אבל אם \u0003אתא נהרא\u0004 \u0005[בא נהר]\u0006 שגאה והשקה את השדה — הרי זה \u0003פסידא\u0004 \u0005[הפסד]\u0006 של \u0003בעל הבית,\u0004 שהיה צריך להביא זאת בחשבון, ונותן להם שכרם \u0003כפועל בטל.\u0004","\u0003ואמר רבא: האי מאן דאוגיר אגורי לדוולא\u0004 \u0005[מי ששוכר את הפועלים לדלות]\u0006 מן הנהר או מן התעלה, להשקות את שדהו, \u0003ופסק נהרא בפלגא דיומא\u0004 \u0005[ופסקה\u0006 זרימת חלק \u0005הנהר\u0006 המשקה את שדהו \u0005בחצי היום],\u0006 \u0003אי לא עביד דפסיק\u0004 \u0005[אם אינו עשוי שיפסק]\u0006 הרי זה \u0003פסידא\u0004 \u0005[הפסד]\u0006 של ה\u0003פועלים,\u0004 שמזלם הרע גרם. ואם הוא \u0003עביד דפסיק\u0004 \u0005[שיפסוק]\u0006 — \u0003אי בני מתא\u0004 \u0005[אם בני העיר]\u0006 הם הפועלים ויודעים שהדבר עלול לקרות, הרי זה \u0003פסידא\u0004 \u0005[הפסד]\u0006 של ה\u0003פועלים,\u0004 ואם \u0003לאו בני מתא\u0004 \u0005[אינם בני העיר]\u0006 ואינם יודעים זאת — הרי זה \u0003פסידא\u0004 \u0005[הפסד]\u0006 של \u0003בעל הבית.\u0004","\u0003ואמר רבא: האי מאן דאגר אגורי לעבידתא\u0004 \u0005[מי ששכר פועלים לעבודה]\u0006 מסויימת, \u0003ושלים עבידתא בפלגא דיומא\u0004 \u0005[ונשלמה\u0006 אותה \u0005עבודה בחצי היום],\u0006 \u0003אי אית ליה עבידתא דניחא מינה\u0004 \u0005[אם יש לו עבודה\u0006 אחרת \u0005קלה ממנה]\u0006 — \u0003יהיב להו\u0004 \u0005[נותן להם],\u0006 \u0003אי נמי דכותה\u0004 \u0005[או גם כן\u0006 עבודה אחרת \u0005שכמותה]\u0006 — \u0003מפקד להו\u0004 \u0005[\u0006יכול \u0005לתת להם],\u0006 ואולם \u0003אם יש לו עבודה אחרת שהיא\u0004 \u0003קשה מינה\u0004 \u0005[ממנה]\u0006 הריהו \u0003לא מפקד להו\u0004 \u0005[נותן להם]\u0006 אותה, \u0003ונותן להם שכרן משלם.\u0004","ושואלים: \u0003אמאי\u0004 \u0005[מדוע]\u0006 יתן להם כל שכרם? \u0003וליתיב להו\u0004 \u0005[ושיתן להם\u0006 לכל היותר\u0005]\u0006 \u0003כפועל בטל!\u0004 ומשיבים: \u0003כי קאמר\u0004 \u0005[כאשר אמר]\u0006 \u0003רבא\u0004 את דעתו בענין זה, הרי זה מדובר \u0003באכלושי\u0004 \u0005[בפועלי]\u0006 העיר \u0003מחוזא,\u0004 \u0003דאי\u0004 \u0005[שאם]\u0006 הם \u0003לא עבדי\u0004 \u0005[עובדים]\u0006 — \u0003חלשי\u0004 \u0005[\u0006הם \u0005נחלשים],\u0006 שהיו פועלים אלה רגילים מאד בעבודה קשה ורצופה, והבטלה קשה עליהם ואין היא להם בה הנאה אלא צער.","ומכאן חוזרים לברייתא ששנינו. \u0003אמר מר\u0004 \u0005[החכם]\u0006 שם: \u0003שמין להם את מה שעשו, כיצד?\u0004 — \u0003היה יפה\u0004 (שווה) \u0003ששה דינרים\u0004 — \u0003נותן להם סלע\u0004 שהוא מחצית השכר שקבע להם מראש. ומסבירים: \u0003קא סברי רבנן\u0004 \u0005[סבורים חכמים\u0006 אלה\u0005]\u0006 בברייתא: \u0003יד פועל על העליונה\u0004 ולכן גם אם הפועל חוזר בו איננו מפסיד הכל.","עוד שנינו בברייתא: \u0003או יגמרו מלאכתן ויטלו שני סלעים.\u0004 ותוהים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005],\u0006 והרי כך התנו מתחילה! ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא לאופן \u0003דאייקר עבידתא ואימרו\u0004 \u0005[כשנתייקרה\u0006 בינתים במשך היום שכר \u0005העבודה ומרדו]\u0006 ה\u0003פועלים\u0004 ולא רצו עוד לעבוד, \u0003ואזל\u0004 \u0005[והלך]\u0006 \u0003בעל הבית ופייסינהו\u0004 \u0005[ופייס אותם]\u0006 שיגמרו את מלאכתם. \u0003מהו דתימא\u0004 \u0005[שתאמר],\u0006 \u0003מצו אמרי ליה\u0004 \u0005[יכולים הם לומר לו]:\u0006 \u0003כי מפייסינן\u0004 \u0005[כאשר התפייסנו]\u0006 הרי זה \u0003אדעתא דטפת לן אאגרא\u0004 \u0005[על דעת שתוסיף לנו על שכרנו],\u0006 על כן \u0003קא משמע לן דאמר להו\u0004 \u0005[השמיע לנו שאומר להם]\u0006 בעל הבית: פייסתי אתכם והבטחתי להיטיב את התנאים \u0003אדעתא דטרחנא לכו\u0004 \u0005[על דעת,\u0006 באופן, \u0005שאטרח לכם\u0006 יותר\u0005]:\u0006 \u0003באכילה ושתיה,\u0004 שאני מספק לכם, ולא להוסיף על השכר.","עוד שנינו בברייתא שאם עשו עבודה ב\u0003סלע\u0004 — \u0003נותן להם סלע.\u0004 ותוהים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]!\u0006 ומסבירים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא במקרה \u0003דזל עבידתא מעיקרא, ואגרינהו בטפי זוזא\u0004 \u0005[ש\u0006היה שכר \u0005העבודה זול מתחילה, ו\u0006הוא \u0005שכר אותם בזוז אחד יותר],\u0006 \u0003ולסוף אייקר עבידתא וקם בטפי זוזא\u0004 \u0005[ולבסוף התייקרה העבודה ו\u0006השכר \u0005עומד,\u0006 עובר עכשיו \u0005בתוספת\u0006 של \u0005זוז\u0006 אחד\u0005]\u0006","\u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 \u0003אמרי ליה\u0004 \u0005[\u0006שיכולים הם \u0005לומר לו]:\u0006 \u0003טפי זוזא אמרת לן\u0004 \u0005[זוז אחד יותר\u0006 מהמחיר המקובל \u0005אמרת לנו]\u0006 — אם כן גם עכשיו \u0003טפי זוזא הב לן\u0004 \u0005[זוז יותר\u0006 על המחיר של עכשיו \u0005תן לנו],\u0006 ועל כן \u0003קא משמע לן דאמר להו\u0004 \u0005[השמיע לנו ש\u0006יכול הוא \u0005לומר להם]\u0006 \u0003כי אמרי לכו טפי זוזא\u0004 \u0005[כאשר אמרתי לכם\u0006 שאוסיף לכם \u0005זוז יתר]\u0006 — הרי זה היה כאשר \u0003לא הוה קים לכו\u0004 \u0005[היה ברור לכם]\u0006 שאתם רוצים להישכר בשכר המועט ולכן הוספתי, \u0003השתא קים לכו\u0004 \u0005[\u0006ו\u0005עכשיו שברור לכם]\u0006 וקבלתם שכר המספק אתכם אינני מתכוון להוסיף יותר.","עוד שנינו באותה ברייתא ש\u0003ר' דוסא אומר: שמין להן את מה שעתיד להיעשות,\u0004 ואם \u0003היה יפה\u0004 (שווה) \u0003ששה דינרים נותן להם\u0004 רק \u0003שקל. קסבר\u0004 \u0005[סבור\u0006 הוא\u0005]\u0006 ש\u0003יד פועל על התחתונה\u0004 לפי הכלל: החוזר בו ידו על התחתונה.","עוד שנינו שם: \u0003או יגמרו מלאכתן ויטלו שני סלעים.\u0004 ותוהים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 שכן הוא! ומסבירים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא לאופן \u0003דזל עבידתא ואימר\u0004 \u0005[שהוזלה העבודה\u0006 באמצע \u0005ומרד,\u0006 חזר בו\u0005]\u0006 \u0003בעל הבית\u0004 \u0003ואזול\u0004 \u0005[והלכו]\u0006 ה\u0003פועלים ופייסוהו.\u0004 \u0003מהו דתימא\u0004 \u0005[שתאמר],\u0006 כי \u0003מצי אמר להו\u0004 \u0005[יכול\u0006 בעל הבית \u0005לומר להם]:\u0006 כאשר התפייסתי הרי זה היה \u0003אדעתא דבצריתו\u0004 \u0005[על דעת שתורידו]\u0006 \u0003לי מאגריי\u0004 \u0005[משכרכם],\u0006 ועל כן \u0003קא משמע לן דאמרי ליה\u0004 \u0005[השמיע לנו ש\u0006יכולים הם \u0005לומר לו]:\u0006 היה זה \u0003אדעתא דעבדינן\u0004 \u0005[על דעת שנעשה]\u0006 \u0003לך עבידתא שפירתא\u0004 \u0005[עבודה טובה\u0006 יותר\u0005].\u0006","עוד שנינו בברייתא שאם עשו ב\u0003סלע\u0004 — \u0003נותן להם סלע.\u0004 ותוהים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]!\u0006 \u0003אמר רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב נתן:\u0004 \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 לא לאופן \u0003דאוזילו אינהו גביה זוזא מעיקרא\u0004 \u0005[שהוזילו הם עבורו מתחילה בזוז\u0006 אחד\u0005]\u0006 מן המקובל, \u0003ולסוף זל עבידתא\u0004 \u0005[ולבסוף הוזלה העבודה]\u0006 והשכר המקובל הוא כפי שקיבלו עליהם.","\u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 שיכול בעל הבית לומר להם ולטעון: \u0003בציר זוזא אמריתו לי\u0004 \u0005[\u0006\u0005פחות זוז\u0006 מן המחיר המקובל \u0005אמרתי לכם]\u0006 — \u0003בציר זוזא יהיבנא לכו\u0004 \u0005[פחות זוז אני נותן לכם],\u0006 ועל כן \u0003קא משמע לן דאמרי ליה\u0004 \u0005[השמיע לנו ש\u0006יכולים הם \u0005לומר לו]:\u0006 \u0003כי אמרנא\u0004 \u0005[כאשר אמרנו]\u0006 \u0003לך\u0004 היה זה \u0003בבציר זוזא\u0004 \u0005בפחות זוז\u0006 — כאשר \u0003לא הוה קים\u0004 \u0005[היה ברור]\u0006 \u0003לך\u0004 \u0003השתא קים\u0004 \u0005[עכשיו ברור]\u0006 \u0003לך\u0004 ואין אתה יכול לשלם לפחות משכרנו.","לגבי אותה מחלוקת בברייתא \u0003אמר רב: הלכה כ\u0004שיטת \u0003ר' דוסא.\u0004 ותוהים: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר רב הכי\u0004 \u0005[כך]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב: פועל יכול לחזור בו\u0004 מעבודתו \u0003אפילו בחצי היום! וכי תימא\u0004 \u0005[ואם תאמר]\u0006 כי \u0003שאני ליה\u0004 \u0005[שונה לו]\u0006 \u0003לר' דוסא בין שכירות לקבלנות,\u0004 שר' דוסא סבור ששכיר רשאי לחזור בו, אבל מי שקיבל על עצמו עבודה בקבלנות אינו יכול לחזור בו, \u0003ו\u0004אולם \u0003מי שאני ליה\u0004 \u0005[האם שונה\u0006 הדבר \u0005בעיניו]?\u0006 \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 בענין זה: \u0003השוכר את הפועל, ולחצי יום שמע\u0004 הפועל \u0003שמת לו מת\u0004 והוא צריך לטפל במתו, \u0003או שאחזתו\u0004 את הפועל \u0003חמה\u0004 (חום) ואינו יכול לעבוד, \u0003אם שכיר הוא\u0004 —"],["\u0003נותן לו שכרו, אם קבלן הוא\u0004 — \u0003נותן לו קבלנותו.\u0004","ונברר: \u0003מני\u0004 \u0005[\u0006כשיטת \u0005מי היא]\u0006 הלכה זאת? \u0003אילימא רבנן\u0004 \u0005[אם תאמר\u0006 כשיטת \u0005חכמים],\u0006 \u0003מאי איריא\u0004 \u0005[מה שייך,\u0006 מדוע דווקא\u0005]\u0006 אמרו במקרה ש\u0003שמע שמת לו מת או שאחזתו חמה דאניס\u0004 \u0005[ש\u0006הוא \u0005אנוס],\u0006 \u0003כי לא אניס נמי\u0004 \u0005[כאשר אינו אנוס גם כן]\u0006 — \u0003הא\u0004 \u0005[הרי]\u0006 \u0003אמרו רבנן\u0004 \u0005[חכמים]\u0006 \u0003יד פועל על העליונה! אלא לאו\u0004 \u0005[האם לא]\u0006 שיטת \u0003ר' דוסא היא, ושמע מינה\u0004 \u0005[ולמד מכאן]\u0006 כי \u0003לא שאני ליה\u0004 \u0005[שונה לו]\u0006 \u0003לר' דוסא בין שכירות לקבלנות!\u0004","\u0003אמר רב נחמן בר יצחק:\u0004 בברייתא זו מדובר \u0003בדבר האבוד,\u0004 שאז הדין עם בעל הבית, וכיון שאנוס הוא הרי זה כ\u0003דברי הכל.\u0004","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003כל המשנה\u0004 — \u0003ידו על התחתונה, וכל החוזר בו\u0004 — \u0003ידו על התחתונה.\u0004 ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 לענין \u0003כל המשנה ידו על התחתונה\u0004 — ש\u0003סתם לן\u0004 \u0005[לנו]\u0006 ה\u0003תנא\u0004 בלי לפרש שם אומרה, הרי על ידי כך קבע הלכה כשיטת \u0003ר' יהודה. אלא, כל החוזר בו ידו על התחתונה לאתויי מאי\u0004 \u0005[להביא\u0006 את \u0005מה]\u0006 באה תוספת זו, מה היא באה ללמדנו? \u0003לאו לאתויי\u0004 \u0005[האם לא להביא,\u0006 ללמד\u0005]\u0006 דין \u0003פועל\u0004 \u0003וכ\u0004שיטת \u0003ר' דוסא\u0004 שסבור שפועל אסור לו לחזור בו?","וכיון שכך אין לצרף את דברי ר' דוסא ורב, \u0003אלא\u0004 יש לומר כך: \u0003ר' דוסא תרתי קאמר\u0004 \u0005[שתי\u0006 הלכות \u0005אמר],\u0006 \u0003ורב סבר לה כוותיה בחדא ופליג עליה בחדא\u0004 \u0005[סבור\u0006 הוא \u0005כמותו באחת וחלק עליו באחת],\u0006 שלענין יד פועל על התחתונה לא הסכים רב, אבל לענין דרך חישוב השכר הסכים.","\u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 שאין פירוש המשנה כמו שאמרנו, אלא \u0003\"כל החוזר בו ידו על התחתונה\"\u0004 אינו דן בדיני פועלים אלא בענין אחר, \u0003לכדתניא\u0004 \u0005[לכפי ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003כל החוזר בו כיצד?\u0004 — \u0003הרי שמכר שדה לחבירו באלף זוז, ונתן לו\u0004 הקונה \u0003מעות מהן מאתים זוז,\u0004 ואחר כך חזר בו אחד מהם. \u0003בזמן שהמוכר חוזר בו\u0004 — \u0003יד\u0004 ה\u0003לוקח על העליונה,\u0004 כיצד?","\u0003רצה\u0004 — \u0003אומר לו \"תן לי מעותי\u0004 שנתתי לך \u0003\",\u0004 \u0003או \"תן לי קרקע כנגד מעותי\",\u0004 שאם אינך נותן לי כל הקרקע שהסכמנו עליה, על כל פנים מה ששילמתי לך אני רוצה לקבל בקרקע. \u0003מהיכן מגביהו\u0004 (נותן לו) לקונה זה — \u0003מן העידית\u0004 שבקרקעות. \u0003ובזמן ש\u0004ה\u0003לוקח חוזר בו\u0004 — \u0003יד\u0004 ה\u0003מוכר על העליונה, רצה\u0004 — \u0003אומר לו\u0004 המוכר: \u0003הילך מעותיך, רצה\u0004 — \u0003אומר לו\u0004 המוכר: \u0003הילך קרקע כנגד מעותיך. מהיכן מגביהו\u0004 — אפילו \u0003מן הזיבורית.\u0004","\u0003רבן שמעון בן גמליאל אומר: מלמדין אותן שלא יחזרו,\u0004 שדואגים מראש שההסכם לא יוכל להתבטל ולא יגיעו לסכסוך. \u0003כיצד?\u0004 — \u0003כותב לו\u0004 בשטר המכירה: \u0003\"אני פלוני בן פלוני מכרתי שדה פלונית לפלוני באלף זוז, ונתן לי מהם מאתים זוז, והריני נושה בו שמונה מאות זוז\",\u0004 ואז \u0003קנה\u0004 מיד את כל השדה כולו, \u0003ומחזיר לו את השאר,\u0004 שמונה מאות זוז, \u0003אפילו לאחר כמה שנים,\u0004 שהרי נעשה זה כשטר חוב רגיל.","ומבררים ענייניה של ברייתא זו. \u0003אמר מר\u0004 \u0005[החכם]\u0006 והשאר \u0003מהיכן מגביהו\u0004 — \u0003מן העידית. קא סלקא דעתך\u0004 \u0005[עלתה על דעתך]\u0006 לפרש מתחילה ש\"עידית\" כאן פירושו \u0003מעידית\u0004 שב\u0003נכסיו\u0004 שהוא המובחר שבכל נכסיו של המוכר. ושואלים: \u0003ולא יהא\u0004 קונה זה \u0003אלא\u0004 כ\u0003בעל חוב\u0004 אחר, וכלל כתבה המשנה: \u0003בעל חוב דינו\u0004 שהוא גובה \u0003בבינונית\u0004 ולא במובחר מזה! \u0003ועוד: הא ארעא דיהיב זוזי\u0004 \u0005[הרי\u0006 נמצאת \u0005קרקע\u0006 מסויימת \u0005שעליה נתן כסף]\u0006 ומדוע יקבל קרקע מובחרת ממנה?","\u0003אמר רב נחמן בר יצחק:\u0004 הכוונה היא \u0003מעידית שבה\u0004 — שמאותו שדה שקנה גובה מחלק העידית שבו. \u0003ו\u0004כן מה שנאמר בהמשך \"בזיבורית\" כוונתו \u0003מזיבורית שבה.\u0004","\u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב איקא אמר: אפילו תימא\u0004 \u0005[תאמר]\u0006 ותפרש שהכוונה היא \u0003מעידית\u0004 שב\u0003נכסיו\u0004 כולם, אבל כאן יש טעם בדבר: כי \u0003סתם\u0004 כרגיל \u0003מאן דזבין ארעא באלפא זוזי\u0004 \u0005[מי שקונה קרקע באלף זוז]\u0006 אין בידו סכום זה במזומן, אלא \u0003אוזולי\u0004 \u0005[להוזיל]\u0006 הוא \u0003מוזיל\u0004 המחיר המקובל \u0003ומזבין\u0004 \u0005[ומוכר]\u0006 \u0003נכסיו\u0004 בהפסד. ואם לא יקבל קרקע אחרת תמורתם — נמצא שמפסיד הרבה, \u0003ו\u0004משום כך \u0003הוה ליה\u0004 \u0005[הריהו\u0006 נחשב\u0005]\u0006 \u0003כניזק,\u0004 שהרי חזרתו של המוכר גרמה לו נזק של ממש. \u0003ותנן\u0004 \u0005[ושנינו\u0006 במשנה\u0005]:\u0006 \u0003הניזקין שמין להן בעידית,\u0004 ומשום כך משלם גם הוא כאן מעידית.","עוד שנינו שם ש\u0003רבן שמעון בן גמליאל אומר: מלמדין אותן שלא יחזרו. כיצד?\u0004 — \u0003כותב לו: \"אני פלוני בן פלוני\" וכו'.\u0004 ושואלים: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 \u0003דכתב ליה הכי\u0004 \u0005[ש\u0006הוא \u0005כותב לו כך],\u0006 \u0003הא\u0004 \u0005[הרי]\u0006 אם \u0003לא כתב הכי\u0004 \u0005[\u0006היה \u0005כותב כך]\u0006 — \u0003לא קני\u0004 \u0005[\u0006היה \u0005קונה]?\u0006","\u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003הנותן ערבון לחבירו\u0004 לאחר שהסכימו ביניהם על מכר מסויים \u0003ואמר לו: \"אם אני חוזר בי\u0004 — \u0003ערבוני מחול לך\", והלה אומר: \"אם אני חוזר בי\u0004 — \u0003אכפול לך ערבונך\"\u0004 — \u0003נתקיימו התנאין,\u0004 כלומר, מקיימים את התנאים שהתנו ביניהם לפי חוזה זה, אלו \u0003דברי ר' יוסי.\u0004","ומעירים: \u0003ר' יוסי\u0004 הולך \u0003לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005]\u0006 ש\u0003אמר: אסמכתא קניא\u0004 \u0005[קונה],\u0006 שאם מקבל אדם על עצמו לשלם כעין קנס דבר שאינו שווה לנזק הממשי שנגרם, הרי זה הסכם שיש בו קנין גמור, ואינו בטל גם אם מתחרט אחד הצדדים לאחר זמן.","\u0003ר' יהודה אומר: דיו שיקנה כנגד ערבונו,\u0004 כלומר, שיקבל מן הסחורה לפי סכום הערבון שנתן. \u0003אמר רבן שמעון בן גמליאל: במה דברים אמורים\u0004 — \u0003בזמן שאמר לו\u0004 בפירוש: \u0003ערבוני יקון,\u0004 שאז קונה כנגד הערבון. \u0003אבל\u0004 אם \u0003מכר לו שדה באלף זוז\u0004 בלא לפרט תנאים \u0003ונתן לו\u0004 הקונה \u0003מהם חמש מאות זוז\u0004 — \u0003קנה\u0004 הכל, \u0003ומחזיר לו את השאר אפילו לאחר כמה שנים.\u0004 הרי שלדעת רבן שמעון בן גמליאל גם אם לא כתב חוזה מפורש — קנה הכל וחייב לשלם את השאר, ומדוע נאמר בברייתא שלדעת רבן שמעון בן גמליאל צריך לכתוב חוזה מפורש!","ומשיבים: \u0003לא קשיא\u0004 \u0005[אינו קשה],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 — \u0003דקא עייל ונפיק אזוזי\u0004 \u0005[שהוא,\u0006 המוכר, \u0005נכנס ויוצא על הכסף]\u0006 שאז ברור שהמוכר עשה את העיסקה מפני שהיה זקוק לכסף, וכיון שלא קיבל את כל הכסף הריהו ניזוק, ואם לא פירטו בחוזה מכירה מיוחד — תתבטל העיסקה. \u0003הא\u0004 \u0005[זה]\u0006 — \u0003דלא קא עייל ונפיק אזוזי\u0004 \u0005[שאינו נכנס ויוצא על הכסף],\u0006 הרי המכר קיים גם בלא תנאי מפורש.","ש\u0003אמר רבא: האי מאן דזבין מידי לחבריה וקא עייל ונפיק אזוזי\u0004 \u0005[מי שמכר דבר לחבירו ו\u0006אחר כך \u0005הוא יוצא ונכנס\u0006 כדי לקבל את \u0005הכסף]\u0006 — \u0003לא קני\u0004 \u0005[קנה]\u0006 הקונה את הדבר, שהרי ברור שמכר המוכר רק משום שנזדקק לכסף מזומן מיד, ואם לא קיבל מיד — בטל המכר מעיקרו, שלא לכך נתכוון. אבל אם \u0003לא קא עייל ונפיק אזוזי\u0004 — \u0005[איננו נכנס ויוצא על הכסף]\u0006 — הריהו \u0003קני\u0004 \u0005[קונה]\u0006 ושאר הסכום הריהו כמלווה, וישלם לו הקונה כשיוכל.","\u0003ואמר רבא: האי מאן דאוזפיה מאה זוזי לחבריה ופרעיה זוזא זוזא\u0004 \u0005[מי שהלוה מאה זוז לחבירו ופרע לו דינר דינר]\u0006 — \u0003פרעון הוי\u0004 \u0005[הוא],\u0006 \u0003אלא דאית ליה\u0004 \u0005[שיש לו]\u0006 \u0003תרעומת גביה\u0004 \u0005[עליו]\u0006 על שמחזיר בדרך זו. \u0003דאמר ליה\u0004 \u0005[ש\u0006המלוה \u0005אומר לו]:\u0006 \u0003אפסדתינהו מינאי\u0004 \u0005[הפסדת אותם עבורי],\u0006 שכיון שאינו מקבל סכום כסף גדול בבת אחת — אינו יכול להשתמש בו.","מסופר: \u0003ההוא גברא דזבין ליה חמרא לחבריה\u0004 \u0005[אדם אחד מכר חמור לחבירו]\u0006 \u0003ופש ליה חד זוזא, וקא עייל ונפיק אזוזא\u0004 \u0005[ונשאר דינר אחד\u0006 שלא שילם לו הקונה, \u0005והיה נכנס ויוצא על\u0006 אותו \u0005זוז\u0006 לגבות אותו\u0005].\u0006 \u0003יתיב\u0004 \u0005[ישב]\u0006 \u0003רב אשי וקא\u0004 \u0005[והיה]\u0006 \u0003מעיין בה\u0004 בבעיה זו: \u0003כי האי גוונא מאי\u0004 \u0005[כגון זה מה\u0006 הדין\u0005]?\u0006 האם \u0003קני\u0004 \u0005[קונה]\u0006 \u0003או\u0004 \u0003לא קני\u0004 \u0005[קונה],\u0006 האם נאמר כי כיון שדחוק בכסף וזקוק לזוז זה בטל המכר, או שמא כיון שהוא רק סכום קטן — לא יבטל את המכר כולו? \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב מרדכי לרב אשי: הכי\u0004 \u0005[כך]\u0006 \u0003אמר אבימי\u0004 מן המקום \u0003הגרוניא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא: זוזא כזוזי דמי, ולא קני\u0004 \u0005[דינר\u0006 אחד \u0005כדינרים\u0006 רבים הוא \u0005נחשב, ואינו קונה].\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יוסף לרב אשי: והא אמרינן\u0004 \u0005[והרי אנו אומרים]\u0006 \u0003משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא\u0004 שבמקרה הזה \u0003קני\u0004 \u0005[קונה]!\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 כדי ליישב את הסתירה \u0003תתרגם שמעתיך\u0004 \u0005[תרגם\u0006 הסבר \u0005את השמועה,\u0006 ההלכה\u0005]\u0006 שמסרת, שמדובר שם \u0003במוכר שדהו\u0004"],["\u0003מפני רעתה\u0004 שלא בגלל חוסר כסף מכר אלא משום שרצה להיפטר משדה זה, שאז אנחנו אומרים שהוא מחזר אף על דינר אחד, מפני שהקונה עלול להתחרט.","ועוד בעיה באותו נושא. ותחילה מקדימים: \u0003פשיטא\u0004 \u0005[פשוט\u0006 לנו\u0005]\u0006 שאם \u0003בעי לזבוני\u0004 \u0005[רצה למכור]\u0006 קרקע שלו \u0003במאה\u0004 דינרים \u0003ולא אשכח\u0004 \u0005[מצא]\u0006 קונה, \u0003וזבין\u0004 \u0005[ומכר]\u0006 קרקע \u0003במאתים, וקא עייל ונפיק אזוזי\u0004 \u0005[והוא נכנס ויוצא על הכסף]\u0006 — \u0003לא קני\u0004 \u0005[אינו קונה],\u0006 שברור שמפני דחקו עשה. \u0003אלא, אי בעי לזבוני\u0004 \u0005[אילו רצה למכור]\u0006 \u0003במאה ולא אשכח\u0004 \u0005[מצא],\u0006 \u0003ואי טרח הוה משכח\u0004 \u0005[ואילו היה טורח\u0006 בכך \u0005היה מוצא],\u0006 \u0003ולא טרח וזבין\u0004 \u0005[ומכר]\u0006 \u0003במאתים, וקא עייל ונפיק אזוזי מאי\u0004 \u0005[והוא יוצא ונכנס על הכסף מה\u0006 דינו\u0005]?\u0006 האם \u0003כמוכר שדהו מפני רעתה דמי\u0004 \u0005[\u0006הוא \u0005נחשב],\u0006 \u0003או לא?\u0004 לשאלה זו לא נמצאה תשובה, ולכן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","שנינו במשנה שאם \u0003שכר את החמר,\u0004 או \u0003את הקדר\u0004 והם חזרו בהם, והיה זה דבר האבוד — הריהו \u0003שוכר עליהן\u0004 במקומם אנשים בשכר מרובה, \u0003או מטען\u0004 (מטעה ומרמה אותם) כדי שיחזרו לעבודה. ושואלים: \u0003עד כמה שוכר עליהן? אמר רב נחמן: עד כדי שכרן.\u0004 שאם עשו מקצת המלאכה ולא שילם להם שכר מלאכתם, הריהו יכול להוסיף לפועלים האחרים בשכרם את אותו סכום שהוא חייב להם.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רבא לרב נחמן:\u0004 והלא שנינו ששוכר עליהם \u0003עד ארבעים וחמשים זוז! אמר ליה\u0004 \u0005[לו]:\u0006 \u0003כי תניא ההיא\u0004 \u0005[כאשר שנויה אותה\u0006 ברייתא\u0005]\u0006 — הרי זה כ\u0003שבאתה חבילה לידו.\u0004 כלומר, כשיש בידו חפצים משלהם, שכיון שהוא מוחזק בשלהם, יכול לשכור עליהם אף בסכום גדול, שהרי יש לו ממה להפרע.","\u0003השוכר את החמור להוליכו בהר והוליכו בבקעה\u0004 (במקום מישור), או ששכרו להוליכו \u0003בבקעה והוליכו בהר, אפילו\u0004 דרך \u0003זו עשר מילין וזו עשר מילין, ומתה\u0004 הבהמה — \u0003חייב. השוכר את החמור להוליכה בהר והוליכה בבקעה, אם החליקה\u0004 ונפגעה מכך — \u0003פטור\u0004 השוכר, \u0003ואם הוחמה,\u0004 שהחמור התאמץ יותר מדי והתחמם ואחר כך הצטנן — \u0003חייב,\u0004 שהרי הולכתה בבקעה היא שגרמה לכך. שכר את החמור \u0003להוליכה בבקעה והוליכה בהר, אם החליקה\u0004 — \u0003חייב\u0004 שהרי ההר גרם לכך, \u0003ואם הוחמה\u0004 — \u0003פטור,\u0004 ו\u0003אם מחמת המעלה\u0004 (המאמץ לעלות) הוחמה — הרי זה \u0003חייב.\u0004","\u0003השוכר את החמור והבריקה\u0004 (חלתה) \u0003או שנעשית אנגריא,\u0004 שהשלטונות החרימו את החמור לפי שעה לצורך עבודת המלך — \u0003אומר לו\u0004 המשכיר: \u0003הרי שלך לפניך,\u0004 כלומר, הלא הבהמה היא בידך וטפל בענין כפי שסוכם, ואין אני אחראי לנזק שנגרם לה. ואם \u0003מתה\u0004 הבהמה \u0003או נשברה\u0004 (שברה רגל) — \u0003חייב להעמיד לו חמור\u0004 אחר.","שואלים: \u0003מאי שנא רישא דלא קא מפליג\u0004 \u0005[מה שונה בראש\u0006 המשנה \u0005שאינו מחלק]\u0006 באיזה אופן מתה הבהמה, ומחייב בכל מקרה, \u0003ומאי שנא סיפא דקא מפליג\u0004 \u0005[ומה שונה בסופה\u0006 \u0005שהוא מחלק]\u0006 אם הוחלקה או הוחמה?","ומשיבים, \u0003אמרי דבי\u0004 \u0005[אמרו\u0006 החכמים \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ינאי:\u0004 \u0003רישא\u0004 \u0005[בתחילה]\u0006 מדובר \u0003שמתה מחמת אויר, דאמרינן\u0004 \u0005[שאומרים אנו]\u0006 \u0003אוירא\u0004 \u0005[האויר]\u0006 של \u0003ה\u0004\u0003הר קטלה\u0004 \u0005[הרגה],\u0006 \u0003ואמרינן אוירא\u0004 \u0005[\u0006או \u0005אומרים\u0006 ש\u0005האויר]\u0006 של ה\u0003בקעה קטלה\u0004 \u0005[הרגה],\u0006 שמן הסתם שינוי המקום או מזג האויר הוא שגרם לכך. \u0003ר' יוסי בר חנינא אמר: כגון שמתה מחמת אובצנא\u0004 \u0005[העייפות],\u0006 שסברה היא שמזג האויר הוא שגרם לה לכך. \u0003רבה אמר: כגון שהכישה נחש,\u0004 שאפשר לומר שבמקום האחר שכיחים נחשים יותר.","ואילו \u0003ר' חייא בר אבא אמר\u0004 בשם \u0003ר' יוחנן: הא מני\u0004 \u0005[זו,\u0006 תחילת המשנה, כשיטת \u0005מי היא]\u0006 — כשיטת \u0003ר' מאיר היא,\u0004 ש\u0003אמר: כל המעביר על דעת של בעל הבית,\u0004 שעושה בניגוד להסכם שביניהם"],["\u0003נקרא גזלן,\u0004 שכיון שעשה שלא כפי ההסכם, שהרי לכך לא קיבל רשות — נחשב כאילו גזל את הבהמה מבעליה, והרי הגזלן חייב בכל אונס שיארע.","ושואלים: \u0003הי\u0004 \u0005[איזה]\u0006 מדברי \u0003ר' מאיר\u0004 מלמדנו שהוא מחזיק בשיטה זו? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שזו שיטת \u0003ר' מאיר\u0004 בענין ה\u0003צבע,\u0004 ששנינו במשנה: \u0003הנותן צמר לצבע לצבוע לו\u0004 אותו \u0003אדום וצבעו שחור,\u0004 או לצובעו \u0003שחור וצבעו אדום, ר' מאיר אומר: נותן לו\u0004 הצבע לבעל הצמר את \u0003דמי צמרו.\u0004","\u0003ר' יהודה אומר: אם השבח,\u0004 תוספת הערך שבאה על ידי הצביעה \u0003יתר על היציאה\u0004 (הוצאה) שהוציא הצבע — \u0003נותן לו\u0004 בעל הצמר \u0003את היציאה\u0004 בלבד, \u0003ואם היציאה יתירה על השבח\u0004 — \u0003נותן לו את השבח,\u0004 שידו על התחתונה. ולכאורה אפשר ללמוד שר' מאיר סבור שכיון ששינה הצבע מדעת בעל הצמר — הרי זה כאילו גזלו, ומחזיר הכל.","אך יש לדחות: מכאן אין להוכיח, \u0003ממאי\u0004 \u0005[ממה]\u0006 אתה מסיק זאת? \u0003דלמא שאני התם דקניא\u0004 \u0005[שמא שונה שם שקנה]\u0006 הצבע את הצמר \u0003בשינוי מעשה\u0004 ולא בגלל השינוי מדעת הבעלים, אלא בגלל מעשה של ממש נחשב הדבר כגזילה.","\u0003אלא הא\u0004 \u0005[זו]\u0006 דברי \u0003ר' מאיר\u0004 של \u0003מגבת פורים; דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מגבת פורים\u0004 — \u0003לפורים,\u0004 שכסף שגובים בפורים לחלק לעניים לצורך הסעודה ניתנת רק לפורים. \u0003מגבת העיר,\u0004 שגובים כסף עבור עניי העיר, נותנים אותו \u0003לאותה העיר, ואין מדקדקין בדבר\u0004 לצמצם בדיוק כדי צורך הסעודה. \u0003אבל לוקחין\u0004 (קונים) מכסף זה \u0003את העגלים ושוחטין ואוכלים אותן, והמותר,\u0004 אם נשאר מן הסכום יתר על דמי הסעודה, \u0003יפול לכיס של צדקה,\u0004 וינתן למטרות צדקה אחרות.","\u0003ר' אליעזר אומר:\u0004 אינו כן, אלא \u0003מגבת פורים\u0004 לסעודת \u0003פורים\u0004 בלבד, \u0003ואין העני רשאי ליקח מהן רצועה לסנדלו, אלא אם כן התנה במעמד אנשי העיר\u0004 שיכול לעשות בכסף כרצונו, אלו \u0003דברי ר' יעקב שאמר משום\u0004 (בשם) \u0003ר' מאיר. ורבן שמעון בן גמליאל מיקל.\u0004 משמע שאסור לשנות מדעתו של נותן הצדקה כלל.","ועדיין דוחים: \u0003דלמא התם נמי, דאדעתא\u0004 \u0005[שמא שם גם כן, שעל דעת]\u0006 \u0003פורים הוא דיהיב ליה\u0004 \u0005[שנותן לו],\u0006 \u0003אדעתא דמידי אחרינא\u0004 \u0005[על דעת דבר אחר]\u0006 — \u0003לא יהיב ליה\u0004 \u0005[נתן לו],\u0006 שהרי זה כתנאי מפורש בענין, ואז אם שינה מדעת הנותן — מובן מדוע ר' מאיר מחמיר.","\u0003אלא הא\u0004 \u0005[זו]\u0006 מדברי \u0003ר' מאיר, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' שמעון בן אלעזר אומר משום ר' מאיר: הנותן דינר לעני ליקח\u0004 (לקנות) \u0003לו\u0004 בו \u0003חלוק\u0004 — \u0003לא יקח בו\u0004 העני \u0003טלית,\u0004 לקנות \u0003טלית\u0004 — \u0003לא יקח בו חלוק, מפני שמעביר על דעתו של בעל הבית.\u0004","ודוחים: \u0003ודלמא שאני התם\u0004 \u0003דאתו למחשדיה\u0004 \u0005[ושמא שונה שם שיבואו לחשוד אותו,\u0006 את הנותן\u0005],\u0006 \u0003דאמרי אינשי\u0004 \u0005[שאומרים אנשים],\u0006 \u0003אמר פלניא\u0004 \u0005[פלוני]:\u0006 \u0003זבנינא ליה לבושא\u0004 \u0005[אני קונה לבוש]\u0006 \u0003לפלוני עניא\u0004 \u0005[העני],\u0006 \u0003ולא זבן ליה\u0004 \u0005[קנה לו].\u0006 \u0003אי נמי\u0004 \u0005[או גם כן]\u0006 שהוא \u0003אומר:\u0004 \u0003זבנינא ליה\u0004 \u0005[אני קונה לו]\u0006 \u0003גלימא ולא זבן ליה\u0004 \u0005[קנה לו],\u0006 שהרי הנותן חשב שהעני אכן קונה לבוש, והעני קנה דבר אחר, וכדי שלא ייחשד הנותן — אסור לעני לשנות.","ומשיבים: \u0003אם כן,\u0004 זהו אם זה היה הטעם, \u0003ליתני\u0004 \u0005[שישנה]\u0006 בלשון: \u0003\"מפני החשד\", מאי\u0004 \u0005[מה]\u0006 משמעות הלשון: \u0003\"מפני שמעביר על דעתו של בעל הבית\"\u0004 — \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 \u0003משום דשני\u0004 \u0005[ששינה]\u0006 \u0003הוא\u0004 שאסור לו, \u0003וכל המעביר על דעת בעל הבית נקרא גזלן,\u0004 והרי הוכחה שזו היא שיטת ר' מאיר.","שנינו במשנה כי \u0003השוכר את החמור והבריקה\u0004 אין האחריות על המשכיר. ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"והבריקה\"?\u0004 ואומרים: \u0003הכא תרגימו\u0004 \u0005[כאן,\u0006 בבבל \u0005תרגמו]\u0006 \u0003\"נהוריתא\",\u0004 שהוא לובן הנכנס לאישון עינו של החמור ומעוור אותו בכך. \u0003רבא אמר:\u0004 הכוונה היא ל\u0003אבזקת,\u0004 תולעים השורצים ברגלי החמור.","וכיון שנזכרה המלה \"אבזקת\", מסופר, \u0003ההוא דאמר להו\u0004 \u0005[אדם אחד שאמר להם]:\u0006 ראיתי \u0003אבזקת במילתא דמלכא\u0004 \u0005[\u0006\u0005עש\u0006 שאוכל את \u0005בגדי המלך],\u0006 \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003במאי\u0004 \u0005[במה]\u0006 ראית? האם \u0003בטלי\u0004 \u0005[בכלי]\u0006 \u0003כסף,\u0004 כלומר, פשתן, \u0003או בטלי דהב\u0004 \u0005[\u0006\u0005או בכלי זהב,\u0006 בבגדי צמר\u0005]?\u0006 \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 ש\u0003בטלי\u0004 \u0005[בכלי]\u0006 \u0003כסף אמר, וקטלוה\u0004 \u0005[והרגוהו],\u0006 משום שבכלים אלה אין התולעים מצויים. \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 ש\u0003בטלי דהב\u0004 \u0005[בכלי זהב,\u0006 בבגדי צמר\u0005]\u0006 \u0003אמר, ושבקוה\u0004 \u0005[והניחוהו].\u0006","שנינו במשנה: \u0003או שנעשית אנגריא אומר לו הרי שלך לפניך. אמר רב: לא שנו\u0004 שכן הדין \u0003אלא באנגריא חוזרת,\u0004 כלומר, שלקחו את החמור רק לזמן מסויים, ואחר כך יחזירו אותו. \u0003אבל\u0004 ב\u0003אנגריא שאינה חוזרת,\u0004 שהחרימו את החמור לגמרי, \u0003חייב להעמיד לו חמור\u0004 אחר.","\u0003ושמואל אמר: בין אנגריא חוזרת בין אנגריא שאינה חוזרת, אם בדרך הליכה ניטלה,\u0004 שהוחרם החמור לצורך האנגריא וממשיך ללכת באותו כיוון שהלך בו זה מתחילה — \u0003אומר לו: הרי שלך לפניך. ואם לאו\u0004 \u0005[לא]\u0006 \u0003בדרך הליכתה ניטלה\u0004 אלא לכיוון אחר — \u0003חייב להעמיד לו חמור\u0004 \u0005[אחר].\u0006","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו בברייתא: \u0003השוכר את החמור והבריקה או שנשתטתה\u0004 הבהמה, \u0003אומר לו\u0004 המשכיר: \u0003הרי שלך לפניך. מתה או שנעשית אנגריא\u0004 — \u0003חייב להעמיד לו חמור.\u0004","ומעתה, \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003רב לא קשיא\u0004 \u0005[אינו קשה]\u0006 מן הברייתא למשנה, שיכול להסביר כי \u0003כאן\u0004 במשנה מדובר \u0003באנגריא חוזרת\u0004 אינו חייב להעמיד לו אחר, \u0003כאן\u0004 בברייתא \u0003באנגריא שאינה חוזרת. אלא לשמואל קשיא\u0004 \u0005[קשה]!\u0006","\u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003לשמואל נמי\u0004 \u0005[גם כן]\u0006 \u0003לא קשיא\u0004 \u0005[קשה],\u0006 שהרי הוא יכול לתרץ בצורה דומה: \u0003כאן שבדרך הליכתה ניטלה, כאן שלא בדרך הליכתה ניטלה.\u0004","\u0003הא מדקתני סיפא\u0004 \u0005[הרי ממה ששנינו בסופה\u0006 של אותה ברייתא\u0005]:\u0006 \u0003ר' שמעון בן אלעזר אומר: אם בדרך הליכתה ניטלה\u0004 — \u0003אומר לו: הרי שלך לפניך, ואם לאו\u0004 \u0005[לא]\u0006 — \u0003חייב להעמיד לו חמור. מכלל\u0004 הדברים אתה למד כי \u0003ל\u0004דעת ה\u0003תנא קמא לא שאני ליה\u0004 \u0005[הראשון אינו שונה]\u0006 באיזו דרך ניטלה, וקשה לשמואל!","ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך שמואל:\u0004 \u0003לאו מי איכא\u0004 \u0005[האם לא ישנו]\u0006 \u0003ר' שמעון בן אלעזר דקאי כוותי\u0004 \u0005[העומד בשיטתי]?\u0006 \u0003אנא דאמרי\u0004 \u0005[אני שאמרתי]\u0006 \u0003כ\u0004דברי \u0003ר' שמעון בן אלעזר. איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 תירוץ אחר: כל הברייתא \u0003כולה\u0004 כשיטת \u0003ר' שמעון בן אלעזר היא, וחסורי מיחסרא והכי קתני\u0004 \u0005[וחסרה\u0006 הברייתא \u0005וכך\u0006 יש \u0005לשנותה]:\u0006 \u0003השוכר את החמור והבריקה או נשתטית, אומר לו: הרי שלך לפניך. מתה או שנעשית אנגריא\u0004 — \u0003חייב להעמיד לו חמור\u0004 אחר. \u0003במה דברים אמורים\u0004 — \u0003שלא בדרך הליכתה ניטלה, אבל\u0004 כאשר \u0003ניטלה בדרך הליכתה\u0004 — \u0003אומר לו: הרי שלך לפניך.\u0004"],["\u0003דברי ר' שמעון בן אלעזר. שהיה רבי שמעון בן אלעזר אומר: אם בדרך הילוכה ניטלה\u0004 — \u0003אומר לו: הרי שלך לפניך, ואם לא\u0004 — \u0003חייב להעמיד לו חמור.\u0004","ושואלים: \u0003ומי מצית מוקמת לה\u0004 \u0005[האם יכול אתה להעמיד אותה]\u0006 את הברייתא הזו כולה כשיטת \u0003ר' שמעון בן אלעזר? והא קתני רישא\u0004 \u0005[והרי שנה בראשה]\u0006 של הברייתא: \u0003השוכר את החמור והבריקה או שנשתטתה, אומר לו: הרי שלך לפניך. ואילו ר' שמעון בן אלעזר אמר\u0004 בברייתא אחרת: \u0003השוכר את החמור לרכוב עליה והבריקה או שנשתטתה\u0004 — \u0003חייב להעמיד לו חמור!\u0004","\u0003אמר רבה בר רב הונא:\u0004 אין זו סתירה, כי \u0003לרכוב עליה שאני\u0004 \u0005[שונה],\u0006 משום שלצורך זה נחוץ חמור שהילוכו יציב, וחמור שחלה הרי הוא לענין זה כמת. והעיר \u0003רב פפא:\u0004 \u0003ו\u0004אם לקחו לשים עליו \u0003כלי זכוכית\u0004 — \u0003כלרכוב עליה דמי\u0004 \u0005[נחשב],\u0006 שהרי גם כלי זכוכית צריכים חמור שהלוכו יציב, שלא יפול המשא ממנו.","\u0003אמר רבה בר רב הונא אמר רב: השוכר את החמור לרכוב עליה ומתה לו בחצי הדרך\u0004 — \u0003נותן לו שכרו של חצי הדרך, ואין לו עליו אלא תרעומות,\u0004 שצריך לטרוח ולחפש חמור אחר.","ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק הדבר]?\u0006 \u0003אי דשכיח לאגורי\u0004 \u0005[אם שמצוי,\u0006 ניתן \u0005לשכור]\u0006 חמור אחר — \u0003תרעומות מאי עבידתיה\u0004 \u0005[תרעומת מה מעשיה],\u0006 מה טיבה כאן? ישכור חמור אחר, ואין בכך כל הפסד! \u0003אי\u0004 \u0005[אם]\u0006 ש\u0003לא שכיח לאגורי\u0004 \u0005[מצוי לשכור]\u0006 חמור — \u0003אגרא בעי למיתב ליה\u0004 \u0005[שכר היה צריך לתת לו]\u0006 למשכיר? הרי אינו יכול להוביל את משאו!","ומשיבים: \u0003לעולם\u0004 תפרש ש\u0003לא שכיח לאגורי\u0004 \u0005[מצוי לשכור],\u0006 \u0003ומשום דאמר ליה\u0004 \u0005[שאומר לו]\u0006 בעל החמור: \u0003אילו בעית למיתי\u0004 \u0005[היית רוצה להגיע]\u0006 \u0003עד הכא\u0004 \u0005[כאן]\u0006 — וכי \u0003לאו אגרא בעית למיתב\u0004 \u0005[\u0006\u0005לא שכר היית צריך לתת]?\u0006 אם כן, תשלם אתה שכרי עד המקום שהגעת אליו!","ושואלים עוד: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 ש\u0003אמר לו ליה\u0004 \u0005[לו]\u0006 המשכיר: \u0003\"חמור סתם\u0004 אני משכיר לך \u0003\"\u0004— \u0003הא\u0004 \u0005[הרי]\u0006 \u0003חייב להעמיד לו חמור אחר,\u0004 שהרי אמר שמשכיר לו חמור, ואם אין חמור זה — יתן לו אחר. \u0003אי\u0004 \u0005[אם]\u0006 ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003\"חמור זה\u0004 אני משכיר לך \u0003\"\u0004— הרי החמור הזה משועבד לשכירות זו, ו\u0003אם יש בדמיה\u0004 של הנבילה כדי \u0003ליקח\u0004 (לקנות) — חמור אחר \u0003יקח!\u0004","ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא \u0003בשאין בדמיה\u0004 כדי \u0003ליקח\u0004 חמור אחר. ושואלים: גם אז, \u0003אם יש בדמיה\u0004 כדי \u0003לשכור\u0004 חמור אחר — \u0003ישכור\u0004 חמור אחר, וימשיך במסעו, ומדוע יש מקום לתרעומת? ומשיבים: \u0003רב\u0004 הולך בענין זה \u0003לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005],\u0006 ש\u0003אמר רב: לא מכלינן קרנא\u0004 \u0005[אין אנחנו מכלים את הקרן]\u0006 את גוף הממון, כדי לשלם עבור שכירות. ולכן אין רשות לשוכר למכור את הנבילה, שלא תכלה הקרן — כל דמי החמור.","\u0003דאתמר\u0004 \u0005[שנאמר]\u0006 שנחלקו אמוראים בבעיה זו: \u0003השוכר את החמור ומתה לו בחצי הדרך. אמר רב: אם יש בדמיה\u0004 של הנבילה כדי \u0003ליקח\u0004 חמור אחר — \u0003יקח,\u0004 אבל יש בדמיה רק כדי \u0003לשכור\u0004 — \u0003אל ישכור. ושמואל אמר: אף לשכור\u0004 — \u0003ישכור.\u0004","ושואלים: \u0003במאי קמיפלגי\u0004 \u0005[במה,\u0006 באיזה עקרון, \u0005נחלקו]?\u0006 ומשיבים, \u0003רב סבר\u0004 \u0005[סבור]:\u0006 \u0003לא מכלינן קרנא\u0004 \u0005[אין אנו מכלים את הקרן],\u0006 את גוף הממון, ומכיון שעכשיו הנבילה היא גוף הממון — אין להוציא אותה על שכירות, שבסופו של דבר לא ישאר ממנה דבר לבעלים. \u0003ושמואל סבר\u0004 \u0005[סבור]:\u0006 אף \u0003מכלינן קרנא\u0004 \u0005[מכלים אנו את הקרן].\u0006","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך, ממה ששנו חכמים, שאם נתן אדם לחבירו כמשכנתא אילן, והמלוה יאכל מפירותיו עד שתשתלם על ידי כך ההלוואה, ובינתים \u0003יבש האילן או\u0004 ש\u0003נקצץ\u0004 — \u0003שניהם,\u0004 גם הלווה וגם המלוה \u0003אסורין בו\u0004 להשתמש בגופו. אלא \u0003כיצד יעשה? ילקח\u0004 (ייקנה) \u0003בו\u0004 במה שיש באילן היבש הזה \u0003קרקע, והוא,\u0004 המלוה שקיבל את האילן, \u0003אוכל פירות\u0004 מקרקע זו. ומסיקים: \u0003והא הכא\u0004 \u0005[והרי כאן]\u0006 \u0003כיון דכי מטי\u0004 \u0005[שיבוא]\u0006 ה\u0003יובל קא הדרא ארעא למרה\u0004 \u0005[תחזור הקרקע לבעליה]\u0006 הראשונים, \u0003וקא כליא קרנא\u0004 \u0005[ו\u0006נמצא ש\u0005כלתה הקרן],\u0006 שהרי האילן הזה הושקע בדבר שבסופו כלה לגמרי, משמע שמכלים את הקרן!","ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003דזבין ליה לשתין שנין\u0004 \u0005[שקנה אותה\u0006 קרקע \u0005לששים שנה].\u0006 ש\u0003אמר רב חסדא אמר רב קטינא: מנין למוכר שדהו לששים שנה\u0004 או לכל זמן קצוב אחר \u0003שאינה חוזרת ביובל\u0004 — \u0003שנאמר: \"והארץ לא תמכר לצמיתת\"\u0004 (ויקרא כה, כג). \u0003מי,\u0004 איזו מכירה אסורה — במקרה שאם \u0003אין שם יובל\u0004 — היתה \u0003נצמתת,\u0004 ואם \u0003יש שם יובל\u0004 — \u0003אינה נצמתת. יצתה\u0004 (יצאה) \u0003זו,\u0004 שנמכרה לזמן קצוב, \u0003שאף על פי שאין שם יובל\u0004 — \u0003אינה נצמתת.\u0004 ולענייננו כיון שקנה קרקע לזמן קצוב — אין יובל חל עליה.","ומקשים: ו\u0003סוף סוף, לכי מטו שיתין שנין\u0004 \u0005[כאשר יגיעו שישים השנים]\u0006 — \u0003קא הדרא ארעא למרה, וקא כליא קרנא\u0004 \u0005[תחזור האדמה לבעליה, ונמצא שכלתה הקרן]!\u0006 ומשיבים: \u0003אלא, הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003בזמן שאין היובל נוהג,\u0004 ואז אפשר לקנות קרקע לצמיתות. ומעירים: \u0003הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר]\u0006 לומר, \u0003דאי סלקא דעתך\u0004 \u0005[אם עולה על דעתך\u0006 לומר\u0005]\u0006 שמדובר כאן \u0003בזמן שהיובל נוהג, ו\u0004הברייתא סבורה כי \u0003מכלינן קרנא\u0004 \u0005[שמכלים את הקרן],\u0006 מדוע לעשות את העיסקה המורכבת הזו? \u0003נצלחיה לציבי ונשקליה\u0004 \u0005[שיחתוך\u0006 את העץ \u0005לעצים\u0006 קטנים יותר לצורך הסקה \u0005ויקח אותו]\u0006 וימכרנו מיד!","ומשיבים: \u0003אי\u0004 \u0005[אם]\u0006 \u0003משום הא\u0004 \u0005[זה]\u0006 — \u0003לא קשיא\u0004 \u0005[אינו קשה],\u0006 כי אפשר לומר \u0003זמנין דשלמו שני\u0004 \u0005[לפעמים נגמרות שנות\u0006 ה\u0003משכנתא מקמי\u0004 \u0005[לפני]\u0006 ה\u0003יובל,\u0004 ויקבל בעל האילן בחזרה את הקרקע לזמן ידוע ואם כן אינו הכרח שתכלה הקרן. \u0003אי נמי דמטו ליה זוזי ופריק לה\u0004 \u0005[או גם שמגיעים לו כספים\u0006 לבעל הקרקע \u0005ופודה אותה]\u0006 \u0003ארבע\u0004 או \u0003חמש שנין מקמי\u0004 \u0005[שנים לפני]\u0006 ה\u0003יובל\u0004 ונמצא שהקרן לא כלתה, שהרי עכשיו נשאר בידו כסף.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003השוכר את הספינה וטבעה לה בחצי הדרך, ר' נתן אומר: אם נתן\u0004 כבר השוכר כסף עבור הספינה — \u0003לא יטול\u0004 בחזרה, \u0003ואם לא נתן\u0004 — \u0003לא יתן.\u0004","ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה]\u0006 החוזה? \u0003אילימא\u0004 \u0005[אם לומר]\u0006 שאמר המשכיר שנותן לו \u0003\"ספינה זו\"\u0004 \u0003ו\u0004אמר השוכר שהוא מוביל \u0003\"יין סתם\",\u0004 אם כן \u0003אם נתן אמאי\u0004 \u0005[מדוע]\u0006 ש\u0003לא יטול\u0004 בחזרה את ממונו? \u0003נימא ליה\u0004 \u0005[שיאמר לו]:\u0006 \u0003הב\u0004 \u0005[תן]\u0006 \u0003לי ספינתא, דאנא מייתינא חמרא\u0004 \u0005[את האניה, שאני אוביל\u0006 בה \u0005את היין]\u0006 וכיון שאבדה האניה — החזר לי את מה ששילמתי, שאוכל להוביל יין זה או יין אחר. \u0003אלא\u0004 תאמר שמדובר שהמשכיר אמר לו \u0003\"ספינה סתם\" ו\u0004אמר השוכר שהוא מוביל \u0003\"יין זה\", אם לא נתן אמאי\u0004 \u0005[מדוע]\u0006 \u0003לא יתן\u0004 את שכרו?"],["\u0003נימא ליה\u0004 \u0005[שיאמר לו]\u0006 המשכיר: \u0003הב לי\u0004 \u0005[תן]\u0006 \u0003ההוא חמרא ואנא מייתינא ספינתא\u0004 \u0005[את היין ההוא ואני אביא ספינה\u0006 להוביל אותו\u0005],\u0006 וכיון שהיין איננו קיים — אין השוכר יכול למלא התנאי, וחייב לשלם.","\u0003אמר רב פפא:\u0004 \u0003לא משכחת לה\u0004 \u0005[תמצא אותה],\u0006 כלומר, אין אפשרות להבין זאת \u0003אלא\u0004 כאשר התנה אתו \u0003\"בספינה זו\" ו\"יין זה\",\u0004 שאז שניהם יכולים לטעון זה כנגד זה. אבל אם היה מדובר על \u0003ספינה סתם ויין סתם\u0004 — \u0003חולקין.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003השוכר את הספינה ופרקה לה\u0004 פרק את משאה של הספינה \u0003בחצי הדרך\u0004 ואינו רוצה להוביל בה עוד — \u0003נותן לו שכרו של חצי הדרך, ואין לו\u0004 למשכיר הספינה \u0003עליו אלא תרעומת.\u0004 ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006 \u0003אילימא דקא משכח לאגורה\u0004 \u0005[אם תאמר\u0006 שבמקום \u0005שיכול להשכירה]\u0006 לאחר — \u0003אמאי אית ליה\u0004 \u0005[מדוע יש לו]\u0006 \u0003תרעומת?\u0004 \u0003ואי דלא קא משכח לאגורה\u0004 \u0005[ואם שאינו מוצא להשכירה]\u0006 — \u0003כוליה אגרה בעי שלומי\u0004 \u0005[את כל השכר צריך לשלם]\u0006 המשכיר. שהרי קיבל על עצמו לשכור ספינה לכל הדרך!","ומשיבים: \u0003לעולם\u0004 תפרש שמדובר באופן \u0003דקא משכח לאגורה\u0004 \u0005[שהוא מוצא להשכירה],\u0006 \u0003אלא אמאי אית ליה\u0004 \u0005[מדוע יש לו]\u0006 \u0003תרעומת\u0004 — \u0003משום רפסתא דספינתא\u0004 \u0005[התרועעות הספינה]\u0006 בהכנסת והוצאת הסחורות פעם נוספת, שלא לפי ההסכם. ותוהים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 וזו היא טענתו — \u0003טענתא מעלייתא הוא וממונא אית ליה גביה\u0004 \u0005[טענה מעולה היא וממון יש לו אצלו],\u0006 שיש בכך יותר מתרעומת בלבד, וחוב כספי של ממש הוא.","\u0003אלא\u0004 יש להבין להיפך: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"פרקה\"\u0004 — ש\u0003פרקה לטועניה בגויה\u0004 \u0005[שפרק את המטען שלו בתוכה],\u0006 שבאמצע הדרך הוסיף בה השוכר משא נוסף. ושואלים: \u0003אלא מאי\u0004 \u0005[מה\u0006 היא\u0005]\u0006 ה\u0003תרעומת\u0004 — \u0003משום שינוי דעתא\u0004 \u0005[הדעת],\u0006 שלא לכך התכוון בשעת ההשכרה. \u0003אי נמי לאשלא יתירא\u0004 \u0005[או גם כן\u0006 משום \u0005החבלים היתרים]\u0006 שזקוק להם כדי לקשור את החבילות הנוספות.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003השוכר את החמור לרכוב עליה\u0004 — ה\u0003שוכר מניח עליה כסותו ולגנותו\u0004 (קנקן מים שלו) \u0003ומזונות של אותה דרך, מכאן ואילך\u0004 אם בא להוסיף יותר — \u0003חמר מעכב עליו\u0004 ואומר שאינו רוצה להעמיס על החמור עוד. וה\u0003חמר מניח עליו שעורים ותבן\u0004 עבור החמור \u0003ומזונותיו\u0004 שלו \u0003של אותו היום, מכאן ואילך\u0004 אם רצה להוסיף עוד — \u0003שוכר מעכב עליו.\u0004","ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד היה הדבר]?\u0006 \u0003אי דשכיח למזבן\u0004 \u0005[אם שמצוי לקנות]\u0006 דברי אוכל בדרך — שה\u0003חמר נמי ליעכב\u0004 \u0005[גם כן יעכב]\u0006 על שהשוכר לוקח את כל המזונות עמו, \u0003ואי\u0004 \u0005[ואם]\u0006 ש\u0003לא שכיח למזבן\u0004 \u0005[מצוי לקנות\u0006 מזון\u0005]\u0006 — ה\u0003שוכר נמי\u0004 \u0005[גם כן]\u0006 ש\u0003לא ליעכב\u0004 \u0005[יעכב]\u0006 את החמר מלהניח את מזונותיו!","\u0003אמר רב פפא:\u0004 \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא לאופן \u0003דשכיח למטרח ולמזבן מאוונא לאוונא\u0004 \u0005[שמצוי לטרוח ולקנות מתחנה לתחנה]\u0006 ולכן, ה\u0003חמר דרכיה למטרח ולמזבן\u0004 \u0005[דרכו לטרוח ולקנות],\u0006 \u0003שוכר לאו דרכיה למטרח ולמזבן\u0004 \u0005[אין דרכו לטרוח ולקנות].\u0006","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003השוכר את החמור\u0004 כדי \u0003לרכוב עליה איש\u0004 — \u0003לא תרכב עליה אשה.\u0004 אם שכרו שתרכב עליו \u0003אשה\u0004 — \u0003רוכב עליה איש. ו\u0004אם השכירו שתרכב עליו \u0003אשה\u0004 יכול להרכיב כל אשה, \u0003בין גדולה ובין קטנה, ואפילו\u0004 היתה \u0003מעוברת\u0004 שיש תוספת משא בוולד שבמעיה, \u0003ואפילו מניקה\u0004 שלוקחת את התינוק אתה.","ושואלים: \u0003השתא\u0004 \u0005[עכשיו]\u0006 הרי \u0003מניקה אמרת\u0004 שאין המשכיר יכול לעכב, אף שהיא לוקחת איתה ילד נוסף, אם כן \u0003מעוברת מיבעיא\u0004 \u0005[נצרכה\u0006 לומר\u0005]\u0006 שיכולה לרכב?! \u0003אמר רב פפא:\u0004 הכוונה היא \u0003מעוברת והיא מניקה קאמר\u0004 \u0005[אמר],\u0006 שיש פה תוספת יתירה.","\u0003אמר אביי: שמע מינה ביניתא אכרסה תקלה\u0004 \u0005[מכאן אתה למד שהדג בכרסו משקלו]\u0006 ולפי גודל הכרס מתרבה המשקל. שהרי כך אפשר ללמוד מענין המעוברת. ושואלים: \u0003למאי נפקא מינה\u0004 \u0005[מה יוצא מזה]\u0006 ממה שאמר אביי בענין דג? ומשיבים: \u0003למקח וממכר,\u0004 שידע אדם כיצד להעריך את משקלו של הדג, ולא יטעה בדבר."],["\u0003השוכר את הפרה לחרוש בהר וחרש בבקעה, אם נשבר הקנקן\u0004 (חלקה התחתון של המחרשה) — \u0003פטור,\u0004 שהרי בהר עשוי היה להישבר יותר. ואולם אם שכרה לחרוש \u0003בבקעה וחרש בהר, אם נשבר הקנקן\u0004 — \u0003חייב.\u0004 שכר את הפרה \u0003לדוש בקטנית ודש בתבואה\u0004 והחליקה הפרה ושברה רגלה — \u0003פטור,\u0004 ואולם אם שכרה \u0003לדוש בתבואה ודש בקטנית\u0004 — \u0003חייב, מפני שהקטנית מחלקת\u0004 (גורמת להחליק).","ושואלים: \u0003היכא\u0004 \u0005[\u0006ו\u0005במקום]\u0006 ש\u0003לא שני\u0004 \u0005[שינה]\u0006 \u0003בה, מאן\u0004 \u0005[מי]\u0006 \u0003משלם?\u0004 שהרי במשנה מדובר כששינה השוכר מתנאי השכירות, ואולם אם היו שני אנשים שעבדו אצלו במקום שהתנה, ונשברה המחרשה, מי מהם משלם? \u0003אמר רב פפא: דנקיט פרשא\u0004 \u0005[\u0006זה \u0005שמחזיק את המרדע]\u0006 לכוון את פרה הוא זה ש\u0003משלם,\u0004 שמפני שלא הוליכה למישרין, בכך גרם שנשברה המחרשה. \u0003רב שישא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אידי אמר: דנקיט מנא\u0004 \u0005[\u0006זה \u0005שמחזיק בכלי,\u0006 במחרשה עצמה\u0005]\u0006 הוא זה ש\u0003משלם.\u0004 ומסכמים: \u0003והלכתא\u0004 \u0005[והלכה\u0006 היא\u0005]:\u0006 \u0003דנקיט מנא\u0004 \u0005[המחזיק בכלי,\u0006 במחרשה\u0005]\u0006 הוא זה ש\u0003משלם.\u0004 \u0003ואי דוכתא דמחזקי גונדרי\u0004 \u0005[ואם\u0006 הוא מקום \u0005שמוחזק באבנים]\u0006 — \u0003תרוייהו משלמין\u0004 \u0005[שניהם משלמים],\u0006 שבמקרה זה עיוות כלשהו בתלם גם הוא גורם לשבירה.","\u0003אמר ר' יוחנן: המוכר פרה לחבירו, ואמר לו:\u0004 דע לך ש\u0003פרה זו\u0004 יש בה מומים: \u0003נגחנית היא, נשכנית היא, בעטנית היא, רבצנית היא\u0004 — שנוהגת לרבוץ תמיד, \u0003והיה בה\u0004 באמת רק \u0003מום אחד\u0004 מאלה \u0003וסנפו\u0004 (הכניסו) \u0003בין המומים\u0004 הללו שכולם לא היו בה — \u0003הרי זה מקח טעות,\u0004 שהקונה ראה שאין בה מומים אחרים, וסבר שלא מנה המוכר אותם מומים ברצינות. ואולם אם מנה בה \u0003מום זה\u0004 בלבד, \u0003ו\u0004גם היה בה \u0003מום אחר\u0004 — \u0003אין זה מקח טעות.\u0004","ומעירים, \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003המוכר שפחה לחבירו, ואמר לו: שפחה זו שוטה היא, ניכפית היא\u0004 (חולה במחלת הנפילה), \u0003משועממת\u0004 (משוגעת) \u0003היא, והיה בה\u0004 באמת \u0003מום אחד\u0004 בלבד \u0003וסנפו בין המומין\u0004 — \u0003הרי זה מקח טעות.\u0004 ואולם אם מנה בה \u0003מום זה ומום אחר\u0004 — \u0003אין זה מקח טעות.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא לרב אשי:\u0004 ואם \u0003היו בה כל המומין הללו, מהו\u0004 הדין בכגון זה, האם יכול הקונה לטעון שלא האמין לו וחשב שהמוכר אינו מדבר ברצינות? \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב מרדכי לרב אשי: הכי אמרינן משמיה\u0004 \u0005[כך אומרים אנו משמו]\u0006 של \u0003רבא:\u0004 אם \u0003היו בה כל המומין הללו\u0004 — \u0003אין זה מקח טעות,\u0004 שהרי פירש לו הכל. ואם הקונה לא האמין — אין המוכר אשם.","\u0003השוכר את החמור\u0004 כדי \u0003להביא עליה חטין והביא עליה\u0004 משקל זהה של \u0003שעורין\u0004 שהם קלים מן החטים וניזק החמור — \u0003חייב\u0004 אף על פי שהעמיס עליו אותו משקל עצמו. וכן אם שכר להוביל עליה \u0003תבואה והביא עליה תבן\u0004 כמשקל התבואה — \u0003חייב, מפני שהנפח\u0004 היתר \u0003קשה\u0004 לבהמה \u0003כמשאוי\u0004 עצמו. ואולם אם שכר חמור כדי להביא \u0003להביא\u0004 עליו \u0003לתך\u0004 (נפח של חצי כור שהם חמש עשרה סאה) \u0003חטין, והביא\u0004 עליו \u0003לתך שעורין\u0004 — \u0003פטור,\u0004 שהרי השעורין קלות יותר, והביא אותו נפח עצמו. \u0003ו\u0004בכלל \u0003אם מוסיף על משאו\u0004 יותר משהתנה — \u0003חייב. וכמה יוסיף על משאו ויהא חייב? סומכוס אומר משום\u0004 (בשם) \u0003ר' מאיר:\u0004 כשמוסיף \u0003סאה לגמל\u0004 או \u0003שלשה קבין לחמור.\u0004","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים בגרסת המשנה. \u0003אביי אמר: \"קשה כמשאוי\" תנן\u0004 \u0005[שנינו].\u0006 \u0003רבא אמר: \"קשה למשאוי\" תנן\u0004 \u0005[שנינו].\u0006 ומסבירים, \u0003אביי אמר: \"קשה כמשאוי\" תנן,\u0004 ופירושו: \u0003נפחא כי תקלא\u0004 \u0005[הנפח\u0006 הוא \u0005כמו המשקל],\u0006 \u0003ו\u0004לכן \u0003אי\u0004 \u0005[אם]\u0006 \u0003מוסיף שלשה קבין\u0004 שהוא שיעור רציני המזיק לחמור — \u0003חייב. רבא אמר \"קשה למשאוי\" תנן,\u0004 ומשמעו: \u0003תקלא כי תקלא\u0004 \u0005[משקל כמשקל]\u0006 \u0003ונפחא הוי\u0004 \u0005[והנפח הוא]\u0006 \u0003תוספת,\u0004 ולכן אינו חייב עד שישווה משקל השעורים למשקל החטים (ולא שלושה קבין בלבד), ואז נחשבת תוספת הנפח כמזיקה. ומנסים להביא ראיה.","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]:\u0006 אם שכר את החמור כדי \u0003להביא\u0004 עליו \u0003לתך חטין והביא לתך שעורים\u0004 — \u0003פטור, ואם הוסיף על משאו\u0004 — \u0003חייב. מאי לאו\u0004 \u0005[האם לא]\u0006 הכוונה שלא הביא בדיוק לתך שעורים אלא הוסיף \u0003שלשת קבין?!\u0004 ודוחים: \u0003לא,\u0004 שהוסיף \u0003סאה\u0004 שלמה. ומקשים: \u0003והא עלה קתני\u0004 \u0005[והרי עליה,\u0006 על המשנה, \u0005שנינו]\u0006 בברייתא: \u0003כמה יוסיף על משאו ויהא חייב? סומכוס אומר משום\u0004 (בשם) \u0003ר' מאיר: סאה לגמל, שלשה קבין לחמור!\u0004","ודוחים: \u0003הכי קאמר\u0004 \u0005[כך אמר],\u0006 כך יש להבין: \u0003היכא\u0004 \u0005[במקום]\u0006 ש\u0003לא שני\u0004 \u0005[שינה],\u0006 שאמר שיביא \u0003חטין והביא חטין, שעורין והביא שעורין, כמה יוסיף על משאו ויהא חייב?\u0004 על זה \u0003סומכוס אומר משום ר' מאיר: סאה לגמל שלשה קבין לחמור.\u0004","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר מברייתא: שכר את החמור \u0003להביא לתך\u0004 \u0003ו\u0004הוסיף על המדה סאה ו\u0003הביא\u0004"],["\u0003שש עשרה\u0004 סאין \u0003שעורין\u0004 — \u0003חייב.\u0004 ומכאן נדקדק: \u0003הא\u0004 \u0005[הרי]\u0006 אם הוסיף רק \u0003שלשת קבין\u0004 — \u0003פטור! תרגמה\u0004 \u0005[הסבירה]\u0006 \u0003אביי:\u0004 כאן מדובר \u0003במחיקתא\u0004 \u0005[במחוקות],\u0006 שלא מדד את נפח השעורים במידה גדושה אלא במחוקה, שהביא פחות קצת מן השיעור ולכן ההבדל שם הוא בכדי סאה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003קב\u0004 הוא תוספת גדולה מדי \u0003לכתף\u0004 \u0005[לסבל],\u0006 ואם ניזק בהוספה — חייב לשלם לו. \u0003אדריב\u0004 (חצי כור) \u0003לעריבה\u0004 (לאניה קטנה), \u0003כור\u0004 הוא תוספת גדולה מדי \u0003לספינה, שלשת כורים לבורני\u0004 (לאניה) \u0003גדולה.\u0004","\u0003אמר מר: קב לכתף.\u0004 ושואלים לגופו של ענין: \u0003אם איתא דלא מצי ביה\u0004 \u0005[אמנם אינו יכול\u0006 לעמוד \u0005בו]\u0006 במשא זה הלא הסבל \u0003בר דעת הוא, לשדיה\u0004 \u0005[שיזרוק אותו]\u0006 ממנו ולא יינזק! \u0003אמר אביי:\u0004 מדובר \u0003ב\u0004אופן \u0003ש\u0004המשא \u0003חבטו,\u0004 הפילו \u0003לאלתר\u0004 \u0005[מיד]\u0006 לפני שהספיק להורידו מעליו. \u0003רבא אמר: אפילו תימא\u0004 \u0005[תאמר]\u0006 שמדובר \u0003בשלא חבטו לאלתר\u0004 \u0005[מיד],\u0006 \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 \u0003אלא לאגרא יתירא\u0004 \u0005[לשכר יתר]\u0006 שיכול הוא לדרוש על תוספת זו. \u0003רב אשי אמר:\u0004 אף על פי שבר דעת הוא יתכן שלא ידע שהמשא יתר, ו\u0003הוא,\u0004 הסבל \u0003סבור\u0004 ש\u0003חולשא הוא דנקיט ליה\u0004 \u0005[שתקפה אותו]\u0006 לפי שעה, ולא שהוסיפו במשאו.","שנינו: \u0003כור לספינה, שלשת כורים לבורני גדולה. אמר רב פפא: שמע מינה\u0004 \u0005[למד מכאן]\u0006 מן השיעורים הללו כי \u0003סתם ספינות בת תלתין כורין\u0004 \u0005[בנות שלושים כורים]\u0006 הן, שזהו נפח מטען הספינה. שהרי בכל המקרים שיעור התוספת לנזק הוא אחד משלושים של המשא הרגיל. ושואלים: \u0003למאי נפקא מינה\u0004 \u0005[מה יוצא מכאן]?\u0006 ומשיבים: \u0003למקח וממכר,\u0004 שהקונה ספינה סתם ידע שזה צריך להיות שיעורה.","\u0003כל האומנין\u0004 הלוקחים לביתם חומרי גלם לעבד אותם — \u0003שומרי שכר הן\u0004 על אותו חפץ, עד שיוחזר לבעלים. \u0003וכולן שאמרו\u0004 לבעלים: סיימתי את העבודה \u0003טול את שלך והבא מעות\u0004 — הרי האומן הזה מאז נעשה \u0003שומר חנם.\u0004 אמר אדם לחבירו: \u0003שמור לי ואשמור לך\u0004 — הרי אותו שומר נעשה \u0003שומר שכר,\u0004 שהרי מקבל שכר שמירה עבור שמירתו. אמר לו חבירו: \u0003שמור לי, ואמר לו: הנח לפני\u0004 — הרי זה \u0003שומר חנם.\u0004","\u0003הלוהו על המשכון\u0004 — הרי המלוה המחזיק במשכון הוא \u0003שומר שכר\u0004 על משכון זה. \u0003ר' יהודה אומר: אם הלוהו מעות\u0004 — הריהו \u0003שומר חנם\u0004 על המשכון, ו\u0003אם הלוהו פירות\u0004 — הריהו \u0003שומר שכר. אבא שאול אומר: רשאי אדם להשכיר משכונו של עני\u0004 שנמסר לידו \u0003להיות פוסק והולך עליו\u0004 מחיר שימושו, ועל ידי כך יפחית מעט מעט מן החוב \u0003מפני שהוא כמשיב אבידה,\u0004 שהרי על ידי כך נמצא העני מרויח, ואם לא יעשה כן — לא העני נהנה מן החפץ ולא אחר נהנה ממנו.","ומציעים: \u0003לימא מתניתין\u0004 \u0005[\u0006האם \u0005לומר כי משנתנו]\u0006 ש\u0003לא כ\u0004שיטת \u0003ר' מאיר\u0004 היא? \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003שוכר\u0004 שלא נתפרש בתורה מה דינו, \u0003כיצד\u0004 הוא \u0003משלם? ר' מאיר אומר:\u0004 דינו \u0003כשומר חנם. ר' יהודה אומר:\u0004 דינו \u0003כשומר שכר.\u0004 ואומן דינו כשוכר, שהרי הוא מחזיק את החפץ בידו כדי להרויח בו, ונמצא כאילו שכרו מנותן העבודה. ואם כן, משנתנו אינה כדעת ר' מאיר!","ודוחים: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שכשיטת \u0003רבי מאיר\u0004 היא משנתנו, ואולם האומן דינו כשומר שכר כי \u0003בההיא\u0004 \u0005[באותה]\u0006 \u0003הנאה דקא שביק כולי עלמא ואגיר ליה לדידיה\u0004 \u0005[שהוא מניח את כולם ושוכר אותו]\u0006 — \u0003הוי עילויה\u0004 \u0005[הרי הוא\u0006 נעשה \u0005עליו]\u0006 \u0003שומר שכר.\u0004 ומקשים: \u0003אי הכי\u0004 \u0005[אם כן]\u0006 \u0003שוכר נמי\u0004 \u0005[גם כן]\u0006 אפשר לומר כי \u0003בההיא\u0004 \u0005[באותה]\u0006 \u0003הנאה דקא שביק כולי עלמא ומוגר ליה לדידיה\u0004 \u0005[שהוא מניח את כל העולם ומשכיר לו]\u0006 — \u0003הוי עילויה\u0004 \u0005[הרי הוא עליה]\u0006 \u0003שומר שכר.\u0004","\u0003אלא\u0004 יש לדחות מה שאמרנו, ולומר באופן אחר: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שמשנתנו \u0003כ\u0004שיטת \u0003ר' מאיר\u0004 היא, אלא \u0003בההיא\u0004 \u0005באותה]\u0006 \u0003הנאה דקא יהיב ליה טפי פורתא\u0004 \u0005[שהוא נותן לו משהו יותר]\u0006 — \u0003הוי עילויה\u0004 \u0005[הרי הוא עליה]\u0006 \u0003שומר שכר.\u0004","ומקשים: ה\u0003שוכר נמי\u0004 \u0005[גם כן],\u0006 \u0003מי לא עסקינן דקא משוי ליה טפי פורתא\u0004 \u0005[האם אין אנו עוסקים\u0006 באופן \u0005שהוא מוסיף לו קצת יותר],\u0006 ובכל זאת נחשב לר' מאיר כשומר חינם! \u0003אלא\u0004 יש לדחות את מה שאמרנו, ולומר כך: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שמשנתנו כשיטת \u0003ר' מאיר\u0004 היא, אלא \u0003בההיא\u0004 \u0005[באותה]\u0006 \u0003הנאה\u0004 שיש לאומן \u0003דתפיש ליה אאגריה\u0004 \u0005[שהחזיק אותו,\u0006 את החפץ, ומובטח על ידי כך \u0005בשכרו],\u0006 \u0003דלא בעי למיעל ולמיפק אזוזי\u0004 \u0005[\u0006ו\u0005שאינו צריך להיכנס ולצאת\u0006 כדי לתבוע ממנו \u0005מעות],\u0006 שהרי החפץ בידו, ויכול להחזיקו עד שיקבל תשלום — \u0003הוי עליה\u0004 \u0005[הרי הוא עליה]\u0006 \u0003שומר שכר.\u0004","\u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 כמשמעות המשנה, ללא הסברים אלה, ואף על פי כן שיטת ר' מאיר היא, \u0003כדמחליף\u0004 \u0005[כפי שהיה מחליף]\u0006 \u0003רבה בר אבוה ותני\u0004 \u0005[ו\u0006היה \u0005שונה]\u0006 באותה ברייתא כך: \u0003שוכר כיצד משלם? ר' מאיר אומר: כשומר שכר, ר' יהודה אומר: כשומר חנם.\u0004 ועל כן משנתנו כר' מאיר.","שנינו במשנה: \u0003וכולן,\u0004 האומנים, \u0003שאמרו\u0004 לבעלים: \u0003\"טול את שלך והבא מעות\"\u0004 — נעשה האומן \u0003שומר חנם. תנן התם\u0004 \u0005[שנינו שם\u0006 במשנה\u0005]:\u0006 \u0003אמר לו\u0004 ה\u0003שואל\u0004 למשאיל \u0003\"שלח\u0004 את הבהמה אותה שאלתי, אלי \u0003\",\u0004 \u0003ושלחה\u0004 אליו \u0003ומתה\u0004 בדרך — \u0003חייב\u0004 השואל, \u0003וכן בשעה שמחזירה\u0004 — שאם שלחה ביד אחר, כל עוד לא חזרה ממש ליד הבעלים — חייב באחריותה.","\u0003אמר רפרם בר פפא אמר רב חסדא: לא שנו\u0004 שהשואל חייב \u0003אלא שהחזירה בתוך ימי שאילתה,\u0004 שהרי קיבל על עצמו אחריות שמירתה כל זמן שהיא שאולה אצלו, וכל עוד לא בטלה ההשאלה — האחריות עליו. \u0003אבל\u0004 אם החזירה \u0003לאחר ימי שאילתה\u0004 — \u0003פטור,\u0004 שעל ידי מסירה לשליח יצא ידי חובתו. \u0003מתיב\u0004 \u0005[מקשה]\u0006 על כך \u0003רב נחמן בר פפא:\u0004 הרי שנינו: \u0003וכולן שאמרו \"טול את שלך והבא מעות\"\u0004 — הרי זה \u0003שומר חנם.\u0004"],["\u0003הא\u0004 \u0005[הרי]\u0006 אם אמר רק \u0003\"גמרתיו\"\u0004 דינו כ\u0003שומר שכר,\u0004 משמע, שאפילו לאחר גמר המלאכה נשאר באחריותו הקודמת! ודוחים: \u0003לא,\u0004 לא כך צריך לדייק אלא: \u0003הא\u0004 \u0005[הרי]\u0006 אם אמר לו \u0003\"הבא מעות וטול את שלך\"\u0004 — \u0003שומר שכר\u0004 הוא.","ושואלים: \u0003אבל,\u0004 אם כן, כאשר יאמר \u0003\"גמרתיו\", מאי\u0004 \u0005[מה\u0006 דינו\u0005]\u0006 — כ\u0003שומר חנם? אי הכי, אדתני\u0004 \u0005[אם כן, עד שהוא שונה]\u0006 במשנה ועוסק בדין חדש \u0003\"וכולן שאמרו טול את שלך והבא מעות\u0004 — \u0003שומר חנם\", נשמעינן\u0004 \u0005[ישמיע לנו]\u0006 בדין זה של \u0003\"גמרתיו\", וכל שכן\u0004 כאשר אמר לו \u0003\"טול את שלך\"!\u0004","ודוחים: \u0003\"טול את שלך\" אצטריכא ליה\u0004 \u0005[הוצרכה לו]\u0006 לפרש. ומדוע — \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006 כי מאותה שעה \u0003שומר חנם נמי לא הוי\u0004 \u0005[גם כן איננו],\u0006 ואין עליו כל אחריות, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שבכל זאת דינו כשומר חינם, ויש לו אחריות מסויימת.","\u0003איכא דאמרי\u0004 \u0005[יש אומרים]\u0006 ענין זה בלשון אחרת, ש\u0003אמר רב נחמן בר פפא: אף אנן נמי תנינא\u0004 \u0005[אנחנו גם כן שנינו]\u0006 שממשנתנו אפשר להביא ראיה לדברי רפרם בר פפא, שהרי שנינו: \u0003וכולן שאמרו \"טול את שלך והבא מעות\"\u0004 — הריהו \u0003שומר חנם, מאי לאו\u0004 \u0005[האם לא]\u0006 \u0003הוא הדין\u0004 גם כשאמר לו \u0003\"גמרתיו\".\u0004 ודוחים: \u0003לא, \"טול את שלך\" שאני\u0004 \u0005[שונה]\u0006 וכפי שאמרנו תחילה.","אותה סוגיה עצמה נוסחה בצורה נוספת: \u0003הונא מר בר מרימר קמיה\u0004 \u0005[לפני]\u0006 \u0003רבינא רמי מתניתין אהדדי ומשני\u0004 \u0005[היה מטיל,\u0006 מראה סתירה, בין \u0005המשניות ומתרץ];\u0006 \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003וכולן שאמרו \"טול את שלך והבא מעות\"\u0004 — \u0003שומר חנם. ו\u0004לכאורה \u0003הוא הדין ל\u0004זה שאמר \u0003\"גמרתיו\". ורמינהו\u0004 \u0005[ואנו מטילים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו: \u0003אמר לו\u0004 ה\u0003שואל\u0004 למשאיל \u0003\"שלח\u0004 את הבהמה אלי \u0003\", ושלחה ומתה\u0004 בדרך — \u0003חייב, וכן בשעה שמחזירה! ומשני\u0004 \u0005[ומתרץ]\u0006 זאת לפי מה ש\u0003אמר רפרם בר פפא אמר רב חסדא: לא שנו אלא שהחזיר בתוך ימי שאילתה, אבל\u0004 אם החזירה \u0003לאחר ימי שאילתה\u0004 — \u0003פטור.\u0004","בנושא זה \u0003איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 ללומדים שאלה זו: מה שאמרנו שאם מחזירה לאחר זמן שאילתה פטור, האם \u0003פטור מ\u0004חומרת דיני \u0003שואל, וחייב\u0004 עדיין \u0003כשומר שכר, או דלמא\u0004 \u0005[שמא]\u0006 \u0003שומר שכר נמי לא הוי\u0004 \u0005[גם כן איננו]?\u0006 \u0003אמר אמימר: מסתברא\u0004 \u0005[מסתבר]\u0006 לומר כי \u0003פטור מ\u0004דיני \u0003שואל, ו\u0004אולם \u0003חייב\u0004 עדיין \u0003כשומר שכר, הואיל ו\u0004מקודם \u0003נהנה מהנה הוה\u0004 \u0005[היה\u0006 ממנה\u0005],\u0006 והרי זה כמי שקיבל שכר עבור הפרה שהיתה בידו.","ומעירים: \u0003תניא כוותיה\u0004 \u0005[שנוייה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003אמימר:\u0004 \u0003הלוקח כלים מבית האומן לשגרן\u0004 (לשלחן) במתנה \u0003לבית חמיו, ואמר לו\u0004 לאומן: \u0003אם מקבלין אותן ממני\u0004 כמתנה — \u0003אני נותן לך\u0004 את \u0003דמיהן, ואם לאו\u0004 \u0005[לא],\u0006 אלא יחזירו את המתנה — \u0003אני נותן לך לפי טובת הנאה שבהן,\u0004 כלומר, אשלם לך סכום מסויים כפי שווי ההנאה שהיתה לי בכך שיודעים הם שברצוני היה לשלוח להם מתנה, \u0003ונאנסו,\u0004 אירע אונס בכלים הללו ונשברו, אם היה אונס זה \u0003ב\u0004שעת \u0003הליכה\u0004 — \u0003חייב,\u0004","\u0003ב\u0004שעת \u0003חזירה\u0004 — \u0003פטור, מפני שהוא כנושא שכר\u0004 ופטור מאונסים. הרי שגם לאחר הזמן ששאל את החפץ מן האומן, כל עוד לא הוחזר לבעליו — דינו עדיין כשומר שכר.","מסופר: \u0003ההוא גברא דזבין ליה חמרא לחבריה\u0004 \u0005[אדם אחד מכר חמור לחבירו]\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003קא ממטינא ליה לדוכתא\u0004 \u0005[אני אביא אותו למקום]\u0006 \u0003פלוני, אי מזדבנא\u0004 \u0005[אם תימכר\u0006 הבהמה\u0005]\u0006 — \u0003מוטב, ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 — \u0003מהדרנא ליה נהליך\u0004 \u0005[אחזיר אותה לך].\u0006 \u0003אזל\u0004 \u0005[הלך]\u0006 \u0003ולא אזדבנא\u0004 \u0005[נמכרה\u0006 הבהמה\u0005],\u0006 \u0003ובהדי דקא אתא אתניס\u0004 \u0005[וכאשר הוא בא,\u0006 חזר, \u0005אירעו אונס\u0006 בה\u0005].\u0006 \u0003אתא לקמיה\u0004 \u0005[בא\u0006 הדבר \u0005לפני]\u0006 \u0003רב נחמן, חייביה\u0004 \u0005[חייב אותו]\u0006 את הלוקח.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רבא לרב נחמן\u0004 ממה ששנינו: \u0003נאנסו, בהליכה\u0004 — \u0003חייב, ובחזרה\u0004 — \u0003פטור, מפני שהוא כנושא שכר,\u0004 ומדוע אתה מחייב אותו, הלא כאן אירע האונס בחזירתו?!","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 יש לחלק בין המקרים, כי \u0003חזרה דהאי\u0004 \u0005[חזרתו של זה]\u0006 — \u0003הליכה היא. מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? — \u0003סברא הוא\u0004 \u0005[סברה היא]:\u0006 שהרי \u0003ב\u0004שעת \u0003חזירתו, אילו אשכח לזבוניה\u0004 \u0005[היה מוצא\u0006 אפשרות \u0005למוכרה]\u0006 \u0003מי\u0004 \u0005[האם]\u0006 \u0003לא זבנה\u0004 \u0005[היה מוכר אותה]?\u0006 ואם כן, לא נשתנה דינו בעצם בשעת חזרה עד שמחזירה לבעלים ממש, ומשום כך דינו כשואל.","שנינו במשנה שאם אמר לו \u0003\"שמור לי ואשמור לך\"\u0004 — הרי הוא \u0003שומר שכר.\u0004 ומקשים: \u0003ואמאי\u0004 \u0005[ומדוע]?\u0006 הלא \u0003שמירה בבעלים היא,\u0004 שהרי הבעלים מצויים עם החפץ תוך כדי שמירה, וכלל בידינו שאם היו הבעלים עסוקים במלאכה לצורך השומר — פטור השומר! \u0003אמר רב פפא:\u0004 הכוונה היא ש\u0003אמר ליה \"שמור לי היום ואשמור לך למחר\",\u0004 שבשעת הגניבה לא היו הבעלים עסוקים במלאכתם, ואין זו איפוא באותה שעה שמירה בבעלים.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים],\u0006 אמר לו: \u0003\"שמור לי ואשמור לך\",\u0004 או \u0003\"השאילני ואשאילך\",\u0004 או \u0003\"שמור לי ואשאילך\",\u0004 או \u0003\"השאילני ואשמור לך\"\u0004 — \u0003כולן נעשו שומרי שכר זה לזה.\u0004 ומקשים: \u0003אמאי\u0004 \u0005[מדוע]\u0006 הם שומרי שכר הלא \u0003שמירה בבעלים היא! אמר רב פפא:\u0004 צריכים להבין לא שהתנו זה עם זו לשמור באותה שעה, אלא \u0003ש\u0004\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003\"שמור לי היום ואשמור לך למחר\".\u0004","מסופר: \u0003הנהו אהלויי\u0004 \u0005[אומני אהל,\u0006 מין עשב שממנו מפיקים חומר לכביסה\u0005]\u0006 שהיו הולכים יחד ו\u0003כל יומא\u0004 \u0005[יום]\u0006 \u0003הוה אפי לה חד מינייהו\u0004 \u0005[היה אופה להם אחד מהם].\u0006 \u0003ההוא יומא\u0004 \u0005[יום אחד]\u0006 \u0003אמרו ליה לחד מינייהו\u0004 \u0005[לו לאחד מהם]:\u0006 \u0003זיל אפי לן\u0004 \u0005[לך אפה לנו].\u0006 \u0003אמר להו\u0004 \u0005[הם]:\u0006 \u0003נטרו\u0004 \u0005[שמרו]\u0006 \u0003לי\u0004 את \u0003גלימאי\u0004 \u0005[גלימתי].\u0006 \u0003אדאתא פשעו\u0004 \u0005[עד שבא\u0006 בחזרה, \u0005התרשלו]\u0006 \u0003בה\u0004 בשמירתה \u0003ואגנוב\u0004 \u0005[ונגנבה].\u0006 \u0003אתו לקמיה\u0004 \u0005[באו\u0006 לדין \u0005לפני]\u0006 \u0003רב פפא, חייבינהו\u0004 \u0005[\u0006ו\u0005חייב אותם].\u0006","\u0003אמרו ליה רבנן\u0004 \u0005[חכמים]\u0006 \u0003לרב פפא: אמאי\u0004 \u0005[מדוע]\u0006 מחייב אתה אותם? הלא \u0003פשיעה בבעלים היא! אכסיף\u0004 \u0005[התבייש]\u0006 רב פפא על ששכח דבר פשוט כזה. \u0003לסוף איגלאי מילתא דההוא שעתא שכרא הוה קא שתי\u0004 \u0005[התברר הדבר שבאותה שעה שיכר היה שותה]\u0006 ולא אפה, וכיון שבאותה שעה לא עשה מלאכה עבורם — לא היתה כאן שמירה בבעלים. ונמצא שכיון רב פפא לאמת.","ושואלים: \u0003הניחא למאן דאמר\u0004 \u0005[זה נוח ל\u0006דעת \u0005מי שאומר]\u0006 שאפילו אם היתה \u0003פשיעה בבעלים פטור\u0004 — \u0003משום הכי אכסיף\u0004 \u0005[כך התבייש],\u0006 \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 שבפשיעה \u0003חייב\u0004 — \u0003אמאי אכסיף\u0004 \u0005[מדוע התבייש]?\u0006 \u0003אלא\u0004 כך היה המעשה: \u0003ההוא יומא לאו דידיה הוה\u0004 \u0005[אותו יום לא יום שלו היה],\u0006 שלא היה זה תורו לאפות, \u0003ואמרו ליה לדידיה\u0004 \u0005[לו לאותו\u0006 אדם\u0005]:\u0006 \u0003זיל אפי לן את\u0004 \u0005[לך אפה לנו אתה],\u0006 \u0003ואמר להו\u0004 \u0005[להם]:\u0006 \u0003בההוא אגרא דקא אפינא לכו נטורו גלימאי\u0004 \u0005[בשכר זה שאני אופה לכם\u0006 שלא לפי התור \u0005שמרו את גלימתי]\u0006"],["\u0003עד דאתא\u0004 \u0005[שבא]\u0006 וחזר — \u0003אגניב\u0004 \u0005[נגנב].\u0006 \u0003אתו לקמיה\u0004 \u0005[באו\u0006 \u0003לפני]\u0004 \u0003רב פפא חייבינהו\u0004 \u0005[\u0006ו\u0005חייב אותם].\u0006 \u0003אמרו ליה רבנן\u0004 \u0005[לו חכמים]\u0006 \u0003לרב פפא: הא\u0004 \u0005[הרי]\u0006 \u0003שמירה בבעלים היא! אכסיף\u0004 \u0005[התבייש].\u0006 \u0003לסוף איגלאי מילתא דההיא שעתא שכרא הוה שתי\u0004 \u0005[\u0006ו\u0005לבסוף נתגלה הדבר שבאותה שעה שיכר היה שותה]\u0006 ולא אפה, ולא היתה שם שמירה בבעלים.","מסופר: \u0003הנהו בי תרי דהוו קא מסגו באורחא, חד אריך וחד גוצא\u0004 \u0005[שנים היו מהלכים בדרך, אחד היה גבוה ואחד נמוך].\u0006 \u0003אריכא רכיב חמרא והוה ליה סדינא\u0004 \u0005[הגבוה היה רוכב על חמור והיה עליו סדין],\u0006 \u0003גוצא מיכסי סרבלא וקא מסגי בכרעיה\u0004 \u0005[\u0006ו\u0005הנמוך היה מכוסה במעיל\u0006 צמר \u0005והיה הולך ברגליו].\u0006 \u0003כי מטי לנהרא\u0004 \u0005[כאשר הגיע לנהר]\u0006 לא רצה שיספוג הסרבל מים רבים בנהר ויכביד עליו, \u0003שקליה לסרבליה ואותביה עילוי חמרא\u0004 \u0005[לקח את מעילו והניחו על החמור]\u0006 \u0003ושקליה לסדיניה\u0004 \u0005[ולקח את סדינו]\u0006 של \u0003ההוא ואיכסי ביה\u0004 \u0005[והתכסה בו]\u0006 \u0003שטפוה מיא לסדיניה\u0004 \u0005[\u0006ו\u0005שטפו המים את סדינו].\u0006","\u0003אתא לקמיה\u0004 \u0005[באו\u0006 לדין \u0005לפני]\u0006 \u0003רבא, חייביה\u0004 \u0005[חייבו]\u0006 לשלם עבור הסדין. \u0003אמרו ליה\u0004 \u0005[לו]\u0006 \u0003רבנן לרבא: אמאי\u0004 \u0005[מדוע]\u0006 מחייב אתה אותו? הלא \u0003שאלה בבעלים היא! אכסיף\u0004 \u0005[התבייש]\u0006 רבא. \u0003לסוף איגלאי מילתא\u0004 \u0005[לבסוף נתגלה הדבר]\u0006 ש\u0003בלא דעתיה שקליה\u0004 \u0005[דעתו,\u0006 ידיעתו \u0005נטלו],\u0006 \u0003ובלא דעתיה אותביה\u0004 \u0005[דעתו הניחו]\u0006 ואם כן לא היתה פה שאילה אלא גזילה.","מסופר: \u0003ההוא גברא דאוגר ליה חמרא לחבריה\u0004 \u0005[אדם אחד השכיר חמור לחבירו],\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003חזי, לא תיזול באורחא\u0004 \u0005[ראה, אל תלך בדרך\u0006] של \u0003נהר פקוד דאיכא מיא\u0004 \u0005[שיש\u0006 שם \u0005מים\u0006 רבים בנהר\u0005],\u0006 \u0003זיל באורחא\u0004 \u0005[לך בדרך]\u0006 של \u0003נרש דליכא מיא\u0004 \u0005[שאין\u0006 שם \u0005מים].\u0006 \u0003אזיל באורחא\u0004 \u0005[הלך בדרך]\u0006 של \u0003נהר פקוד\u0004 שלא כפי שאמרו לו, \u0003ומית חמרא\u0004 \u0005[\u0006\u0005ומת החמור].\u0006 \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 בחזרה \u0003אמר: אין, באורחא\u0004 \u0005[כן,\u0006 אכן \u0005בדרך]\u0006 של \u0003נהר פקוד אזלי\u0004 \u0005[הלכתי],\u0006 \u0003ומיהו ליכא מיא\u0004 \u0005[ואולם לא היו\u0006 שם \u0005מים],\u0006","\u0003אמר רבא:\u0004 כאן אפשר להאמין לו על פי הנימוק: \u0003מה ליה\u0004 \u0005[לו]\u0006 \u0003לשקר,\u0004 שהרי \u0003אי בעי אמר ליה\u0004 \u0005[אם היה\u0006 רוצה לשקר \u0005היה אומר לו]:\u0006 \u0003אנא באורחא\u0004 \u0005[אני בדרך\u0006] של \u0003נרש אזלי\u0004 \u0005[הלכתי].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי:\u0004 הנימוק של \u0003\"מה לי לשקר\" במקום עדים\u0004 — \u0003לא אמרינן\u0004 \u0005[אין אנו אומרים],\u0006 שבמקום שיש עדים שיכולים לברר את הדבר אין אנו סומכים על הנימוק של \"מה לי לשקר\" להאמין לו. וכאן כיון שידוע שבדרך נהר פקוד יש תמיד מים, הרי הוא כסותר עדות הידועה לכל, ואינו נאמן.","שנינו במשנה שאם אמר לו \u0003\"שמור לי\", ואמר לו: \"הנח לפני\"\u0004 — הרי זה \u0003שומר חנם. אמר רב הונא:\u0004 ואם \u0003אמר לו \"הנח לפניך\"\u0004 — \u0003אינו לא שומר חנם ולא שומר שכר,\u0004 ואין עליו אחריות כלל. \u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]\u0006 שאלה זו: אמר לו \u0003\"הנח\" סתמא\u0004 \u0005[סתם],\u0006 \u0003מאי\u0004 \u0005[מה\u0006 הדין\u0005]?\u0006 ומציעים, \u0003תא שמע\u0004 \u0005[בא\u0006 ו\u0005שמע]:\u0006 \u0003שמור לי ואמר לו \"הנח לפני\"\u0004 — \u0003שומר חנם.\u0004 ונדייק: \u0003הא סתמא\u0004 \u0005[הרי סתם]\u0006 שלא אמר \"לפני\" — \u0003ולא כלום.\u0004","ודוחים: \u0003אדרבה, מדאמר\u0004 \u0005[ממה שאמר]\u0006 \u0003רב הונא: \"הנח לפניך\" הוא\u0004 ש\u0003אינו שומר חנם ולא שומר שכר, הא\u0004 \u0005[הרי]\u0006 אם אמר \"הנח\" \u0003סתמא\u0004 — \u0003שומר חנם הוי\u0004 \u0005[הוא]!\u0006 \u0003אלא מהא ליכא למשמע מינה\u0004 \u0005[מזה אי אפשר לשמוע,\u0006 ללמוד, \u0005ממנו]\u0006 בדרך הדיוק.","ומציעים: \u0003לימא כתנאי\u0004 \u0005[נאמר\u0006 שיש מחלוקת \u0005תנאים]\u0006 בדבר, ששנינו: \u0003אם הכניס\u0004 חפציו לחצר חבירו \u0003ברשות בעל חצר\u0004 וניזקו שם — \u0003חייב\u0004 בעל הבית. \u0003רבי אומר: בכולם אינו חייב עד שיקבל עליו בעל הבית\u0004 במפורש \u0003לשמור.\u0004 ולכאורה מדובר שם כשמכניסים סתם, ואם כן נחלקו כבר תנאים בשאלה מה אחריותו של האיש!","ודוחים: \u0003ממאי\u0004 \u0005[ממה]\u0006 מוכיח אתה זאת? \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003עד כאן\u0004 \u0003לא\u0004 שמענו כי \u0003קאמרי רבנן התם\u0004 \u0005[חכמים שם]\u0006 \u0003אלא בחצר,\u0004 ש\u0003בת נטורי\u0004 \u0005[שמירה]\u0006 \u0003היא,\u0004 ולכן \u0003כי קאמר ליה \"עייל\"\u0004 \u0005[כאשר אמר לו \"הכנס\"]\u0006 — \u0003\"עייל דאינטר\u0004 \u0005[הכנס שאשמור]\u0006 \u0003לך\" קאמר ליה\u0004 \u0005[אמר לו],\u0006 שלכך התכוון. \u0003אבל הכא, שוקא לאו בר נטורי הוא, \"אנח ותיב נטר לך\" קאמר ליה\u0004 \u0005[כאן,\u0006 ב\u0005שוק לו\u0006 לא מקום \u0005שמירה הוא, \"הנח ושב ושמור לך\" אמר לו].\u0006","\u0003אי נמי\u0004 \u0005[או גם כן]\u0006 אפשר לומר ההיפך: \u0003עד כאן\u0004 \u0003לא\u0004 שמענו כי \u0003קאמר\u0004 \u0005[אמר]\u0006 \u0003רבי התם\u0004 \u0005[שם]\u0006 \u0003אלא בחצירו, דלעיולי רשותא קא בעי למשקל מיניה\u0004 \u0005[שכדי להכניס רשות הוא צריך לקבל ממנו]\u0006 \u0003וכי יהיב ליה רשותא לעיולי\u0004 \u0005[וכאשר נתן לו רשות להיכנס]\u0006 לא הבטיח לו דבר, אלא \u0003\"תיב ונטר\u0004 \u0005[שב ואשמור]\u0006 \u0003לך קאמר ליה\u0004 \u0005[אמר לו].\u0006 \u0003אבל הכא\u0004 \u0005[כאן]\u0006 בשוק שאמר לו סתם \"הנח\" — \u0003\"הנח ואנא מנטרנא\u0004 \u0005[ואני שומר]\u0006 לך \u0003\" קאמר ליה\u0004 \u0005[אמר לו].\u0006 \u0003דאי סלקא דעתך\u0004 \u0005[שאם עולה על דעתך\u0006 לומר כי \u0003\"הנח ותיב ונטר\u0004 \u0005[ושב ושמור]\u0006 \u0003\"\u0004\u0003קאמר ליה\u0004 \u0005[אמר לו],\u0006 \u0003אי לאותבה\u0004 \u0005[אם\u0006 רק \u0005להניחה]\u0006 — וכי \u0003רשותא בעי למשקל מיניה\u0004 \u0005[רשות\u0006 הוא \u0005צריך לקבל ממנו]\u0006 להניחה ברשות הרבים? ואם כן אין לקשר בהכרח בין השיטות.","שנינו במשנה שאם \u0003הלוהו על המשכון\u0004 — הרי המלוה הוא \u0003שומר שכר\u0004 על המשכון. ומעירים: \u0003לימא מתניתין\u0004 \u0005[האם לומר כי משנתנו]\u0006 שלא \u0003כ\u0004דעת \u0003רבי אליעזר\u0004 היא? \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003המלוה את חבירו על המשכון ואבד המשכון\u0004 — \u0003ישבע\u0004 שלא פשע בשמירתו \u0003ויטול מעותיו\u0004 שהלווהו, אלו \u0003דברי ר' אליעזר.\u0004","\u0003ר' עקיבא אומר: יכול\u0004 הלווה \u0003לומר לו: כלום הלויתני אלא על המשכון? אבד המשכון\u0004 — \u0003אבדו מעותיך. אבל\u0004 אם \u0003הלוהו אלף זוז בשטר והניח לו משכון עליהם,\u0004 במקרה זה \u0003דברי הכל:\u0004 אם \u0003אבד המשכון\u0004 — \u0003אבדו מעותיו.\u0004 ולכאורה נובע מכאן שלדברי ר' אליעזר שומר המשכון הוא שומר חנם!","ודוחים: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שמשנתנו \u0003כ\u0004דעת \u0003ר' אליעזר\u0004 היא, \u0003ולא קשיא\u0004 \u0005[ואינו קשה];\u0006 \u0003כאן\u0004 בברייתא מדובר באופן \u0003שמשכנו בשעת הלואתו\u0004 ונטילת המשכון אז היא כתזכורת בלבד. \u0003כאן\u0004 — \u0003שמשכנו שלא בשעת הלואתו\u0004 אלא לקח ממנו לאחר זמן כדי לזרז את הגבייה, וכיון שכך — יש לו ענין בשמירת המשכון, ונעשה עליו כשומר שכר.","ומקשים: \u0003והא אידי ואידי\u0004 \u0005[והרי זה וזה]\u0006 גם במשנה וגם בברייתא,"],["\u0003\"הלוהו על המשכון\" קתני\u0004 \u0005[שנה],\u0006 שמשמע שבשעת ההלוואה נתן לו משכון! \u0003אלא,\u0004 יש לדחות את מה שאמרנו ולתרץ באופן אחר: \u0003לא קשיא\u0004 \u0005[אינו קשה];\u0006 \u0003כאן\u0004 בברייתא מדובר באופן \u0003שהלוהו מעות, כאן\u0004 במשנה — \u0003שהלוהו פירות.\u0004","ומקשים: \u0003והא מדקתני סיפא\u0004 \u0005[והרי ממה ששנינו בסופה]\u0006 של המשנה, \u0003ר' יהודה אומר: הלוהו מעות\u0004 — \u0003שומר חנם, הלוהו פירות\u0004 — \u0003שומר שכר. מכלל\u0004 הדברים אתה למד כי \u0003לתנא קמא\u0004 \u0005[הראשון]\u0006 \u0003לא שני ליה\u0004 \u0005[אינו שונה לו],\u0006 ואין מקום לתירוץ זה!","ומשיבים: כל המשנה \u0003כולה\u0004 כשיטת \u0003ר' יהודה היא, וחסורי מיחסרא והכי קתני\u0004 \u0005[וחסרה\u0006 המשנה \u0005וכך יש לשנות]:\u0006 \u0003הלוהו על המשכון\u0004 — הריהו \u0003שומר שכר, במה דברים אמורים\u0004 — \u0003שהלוהו פירות, אבל\u0004 אם \u0003הלוהו מעות\u0004 — הריהו \u0003שומר חנם. שר' יהודה אומר:\u0004 אם \u0003הלוהו מעות\u0004 — הריהו \u0003שומר חנם,\u0004 ואם \u0003הלוהו פירות\u0004 — הריהו \u0003שומר שכר.\u0004","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 אתה מפרש, נמצא כי \u0003קמה\u0004 \u0005עומדת]\u0006 וסוברת \u0003לה מתניתין\u0004 \u0005[משנתנו]\u0006 ש\u0003לא כ\u0004שיטת \u0003ר' עקיבא\u0004 וקשה לומר כך, כי רוב חכמי המשנה היו תלמידיו, ומן הסתם בשיטתו הלכו. \u0003אלא מחוורתא מתניתין דלא\u0004 \u0005[אלא ברור שמשנתנו אינה]\u0006 \u0003כ\u0004שיטת \u0003ר' אליעזר\u0004 היא.","ומציעים: \u0003לימא\u0004 \u0005[\u0006האם \u0005לומר]\u0006 ש\u0003ב\u0004ש\u0003לא שוי\u0004 \u0005[שווה]\u0006 ה\u0003משכון שיעור זוזי\u0004 \u0005[הכסף]\u0006 שהלוה, \u0003וב\u0004ענין דברי \u0003שמואל קא מיפלגי\u0004 \u0005[הם חלוקים].\u0006 ש\u0003אמר שמואל: האי מאן דאוזפיה אלפא זוזי לחבריה\u0004 \u0005[מי שהלוה אלף זוז לחבירו]\u0006 \u0003ואנח ליה קתא דמגלא עילוייהו\u0004 \u0005[והניח לו קת של מגל עליהם\u0006 כמשכון\u0005],\u0006 שבוודאי שווה רק חלק קטן מאד של ההלוואה, ובכל זאת אם \u0003אבד קתא דמגלא\u0004 \u0005[אבדה קת המגל]\u0006 — \u0003אבדו אלפא זוזי\u0004 \u0005[אלף הזוזים].\u0006","ודוחים: \u0003אי\u0004 \u0003ב\u0004ש\u0003לא שוי\u0004 \u0005[שווה]\u0006 ה\u0003משכון שיעור זוזי\u0004 \u0005[כסף]\u0006 — \u0003דכולי עלמא לית להו\u0004 \u0005[לדעת הכל אין להם,\u0006 אינם מקבלים\u0005]\u0006 את שיטת \u0003שמואל,\u0004 \u0003והכא\u0004 \u0005[וכאן]\u0006 מדובר \u0003בדשוי\u0004 \u0005[ב\u0006אופן \u0005ש\u0006היה המשכון \u0005שווה]\u0006 \u0003שיעור זוזי\u0004 \u0005[הכסף],\u0006 \u0003וקא מיפלגי\u0004 \u0005[והם חלוקים]\u0006 \u0003ב\u0004דברי ר' יצחק. ש\u0003אמר\u0004","\u0003ר' יצחק: מנין לבעל חוב שקונה משכון,\u0004 כלומר, המשכון נעשה לכל ענין כרכושו של המלווה, \u0003שנאמר: \"\u0004השב תשיב לו את העבוט... \u0003ולך תהיה צדקה\"\u0004 (דברים כד, יג), ו\u0003אם אינו קונה משכון,\u0004 אלא המשכון נחשב ברשות בעליו, \u0003צדקה מנא ליה\u0004 \u0005[מנין לו]?\u0006 הלא לא נתן דבר משלו! \u0003אלא\u0004 \u0003מכאן לבעל חוב שקונה משכון.\u0004","ודוחים: \u0003ותסברא\u0004 \u0005[והאם יכול אתה לסבור כן]?\u0006 \u0003אימור\u0004 \u0005[אמור]\u0006 ש\u0003אמר ר' יצחק\u0004 הלכה זו \u0003במשכנו שלא בשעת הלואתו\u0004 אלא שנטל משכון כדי לגבות חובו, \u0003אבל משכנו בשעת הלואתו\u0004 — \u0003מי\u0004 \u0005[האם]\u0006 \u0003אמר?\u0004","\u0003אלא\u0004 כך יש לומר: \u0003משכנו שלא בשעת הלואתו\u0004 — \u0003כולי עלמא אית להו\u0004 \u0005[לדעת הכל יש להם,\u0006 מקבלים הם\u0005]\u0006 את דברי \u0003ר' יצחק. והכא\u0004 \u0005[וכאן]\u0006 מדובר \u0003במשכנו בשעת הלואתו,\u0004 ובשאלה מה דינו של \u0003שומר אבידה קא מיפלגי\u0004 \u0005[חלוקים הם].\u0006 \u0003דאיתמר\u0004 \u0005[שנאמר]\u0006 שנחלקו אמוראים בבעיה מה אחריותו של \u0003שומר אבידה,\u0004 שאם מצא אדם אבידה, וזו אבדה או שנגנבה ממנו, מה אחריותו כלפי הבעלים? \u0003רבה אמר:\u0004 דינו \u0003כשומר חנם, רב יוסף אמר: כשומר שכר.\u0004","ומציעים: \u0003לימא\u0004 \u0005[\u0006האם \u0005לומר]\u0006 כי דברי \u0003רב יוסף תנאי היא\u0004 \u0005[\u0006במחלוקת \u0005תנאים הם\u0006 שנויים\u0005]?\u0006 ודוחים: \u0003לא,\u0004 אפשר לומר כי \u0003בשומר אבידה\u0004 — \u0003דכולי עלמא אית להו\u0004 \u0005[לדעת הכל יש להם,\u0006 מקבלים הם\u0005]\u0006 את דברי \u0003רב יוסף,\u0004 \u0003והכא\u0004 \u0005[וכאן]\u0006"],["\u0003במלוה צריך למשכון קמיפלגי\u0004 \u0005[נחלקו],\u0006 כלומר, אם המלוה רוצה להשתמש במשכון עצמו, וינכה את דמי השימוש בו מסכום ההלוואה. \u0003מר סבר\u0004 \u0005[חכם זה סבור]:\u0006 \u0003מצוה קא עביד\u0004 \u0005[הוא עשה]\u0006 \u0003שהלוהו,\u0004 ואם כן מקבל שכר — שכר מצוה — גם על המשכון שבידו, \u0003והוי\u0004 \u0005[והרי הוא]\u0006 \u0003שומר שכר. ומר סבר\u0004 \u0005[וחכם זה סבר]:\u0006 \u0003לאו\u0004 \u0005[לא]\u0006 \u0003מצוה קא עביד\u0004 \u0005[הוא עושה],\u0006 \u0003שלהנאתו מתכוין, ו\u0004אם כן \u0003הוי\u0004 \u0005[הרי הוא]\u0006 עבור המשכון רק \u0003שומר חנם.\u0004","שנינו במשנה ש\u0003אבא שאול אומר: מותר לאדם להשכיר משכונו של עני להיות פוחת והולך\u0004 מן ההלוואה. \u0003אמר רב חנן בר אמי אמר שמואל: הלכה כאבא שאול. ו\u0004אולם יש לסייג ולומר כי \u0003אף אבא שאול לא אמר\u0004 דבריו \u0003אלא במרא\u0004 (מעדר), \u0003ופסל\u0004 (מפסלת), \u0003וקרדום, הואיל ונפיש אגרייהו וזוטר פחתייהו\u0004 \u0005[ומרובה שכרם ומועט הפחת שלהם].\u0006","\u0003המעביר חבית ממקום למקום ושברה, בין\u0004 שהיה \u0003שומר חנם בין\u0004 שהיה \u0003שומר שכר\u0004 — \u0003ישבע\u0004 שלא התרשל וייפטר. \u0003ר' אליעזר אומר:\u0004 אכן \u0003זה וזה,\u0004 שומר שכר ושומר חנם — \u0003ישבע, ותמיה אני אם יכולין זה וזה לישבע.\u0004 שאכן, כך שמעתי מרבותי, אבל אינני מבין מדוע פסקו כך.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003המעביר חבית לחבירו ממקום למקום ושברה, בין\u0004 שהיה \u0003שומר חנם בין\u0004 שהיה \u0003שומר שכר\u0004 — \u0003ישבע\u0004 שלא התרשל וייפטר, אלו \u0003דברי ר' מאיר. ר' יהודה אומר: שומר חנם\u0004 — \u0003ישבע\u0004 וייפטר, \u0003נושא שכר\u0004 — \u0003ישלם. רבי אליעזר אומר: זה וזה ישבע, ותמיה אני אם יכולין זה וזה לישבע.\u0004","ושואלים כדי לברר את הסברות: \u0003למימרא\u0004 \u0005[האם\u0006 לומר\u0005]\u0006 ש\u0003סבר ר' מאיר\u0004 כי \u0003נתקל לאו\u0004 \u0005[לא]\u0006 \u0003פושע\u0004 \u0005[רשלן]\u0006 \u0003הוא\u0004 ויש בכך מעין אונס? \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003נשברה כדו\u0004 של אדם ברשות הרבים \u0003ולא סילקו\u0004 משם, \u0003נפלה גמלו ולא העמידה, ר' מאיר מחייב בהיזיקן\u0004 שגרמו לאחרים, \u0003וחכמים אומרים: פטור מדיני אדם וחייב בדיני שמים.\u0004 שאמנם אי אפשר לחייבו בבית דין, ואולם מכל מקום יש לו אחריות מוסרית. \u0003וקיימא לן\u0004 \u0005[ומוחזק בידינו]\u0006 כי בשאלה של \u0003נתקל פושע פליגי\u0004 \u0005[חלוקים הם]\u0006 באיזו מדה אומרים שההתקלות באה מחמת פשיעה־רשלנות של הנתקל. ואם כן ברור שר' מאיר סבור שנתקל פושע הוא!","\u0003אמר ר' אלעזר: תברה\u0004 \u0005[שבורה],\u0006 כלומר, באמת אין הדברים נאמרים לפי שיטה אחת, ועלינו לומר כי \u0003מי ששנה זו לא שנה זו,\u0004 שיש שתי שיטות בדברי ר' מאיר. \u0003ואתא\u0004 \u0005[ובא]\u0006 \u0003ר' יהודה למימר\u0004 \u0005[לומר]\u0006 שיטה אחרת: \u0003שומר חנם\u0004 — \u0003ישבע, נושא שכר\u0004 — \u0003ישלם. האי כי דיניה והאי כי דיניה\u0004 \u0005[זה כדינו וזה כדינו],\u0006 שהרי שומר חנם פטור מגניבה ואבידה, ושומר שכר חייב בהם. \u0003ואתא\u0004 \u0005[ובא]\u0006 \u0003ר' אליעזר למימר\u0004 \u0005[לומר]\u0006 \u0003אין, גמרא\u0004 \u0005[המסורת]\u0006 היא \u0003כ\u0004שיטת \u0003ר' מאיר,\u0004 וכך קבלתי מרבותי. \u0003ומיהו\u0004 \u0005[אולם]\u0006 \u0003תמיה אני אם יכולין זה וזה לישבע.\u0004","ומדוע — \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003שומר חנם משתבע\u0004 \u0005[נשבע]\u0006 ש\u0003לא פשע\u0004 \u0005[התרשל]\u0006 \u0003בה\u0004 כפי ההלכה הכתובה בתורה, שעל כך חייב הוא להשבע: \u0003אלא שומר שכר אמאי משתבע\u0004 \u0005[מדוע נשבע]?\u0006 הלא אפילו \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003לא פשע\u0004 \u0005[התרשל]\u0006 \u0003נמי שלומי בעי\u0004 \u0005[גם כן לשלם הוא צריך],\u0006 שהוא אחראי גם על אבידה. \u0003ואפילו שומר חנם נמי\u0004 \u0005[גם כן],\u0006 \u0003התינח\u0004 \u0005[נניח]\u0006 אם נשברה החבית \u0003במקום מדרון,\u0004 שמפני הקושי להובילה אירעה התקלה. ואולם אם נשברה \u0003שלא במקום מדרון, מי מצי משתבע\u0004 \u0005[האם יכול\u0006 הוא \u0005להשבע]\u0006 ש\u0003לא פשע\u0004 \u0005[התרשל],\u0006 הרי ברור אז שרשלנותו היא שגרמה!"],["\u0003ואפילו במקום מדרון נמי\u0004 \u0005[גם כן]\u0006 \u0003התינח היכא דליכא\u0004 \u0005[זה נוח במקום שאין]\u0006 \u0003ראיה,\u0004 וכגון שלא היו שם עדים וכיוצא בזה, \u0003אבל היכא דאיכא\u0004 \u0005[במקום שיש]\u0006 \u0003ראיה\u0004 — \u0003ניתי\u0004 \u0005[שיביא]\u0006 \u0003ראיה ונפטר\u0004 \u0005[וייפטר],\u0006 ומדוע מחייבים אותם שבועה? \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003איסי בן יהודה אומר:\u0004 אמר הכתוב \u0003\"\u0004ומת או נשבר או נשבה \u0003אין ראה. שבעת ה' תהיה בין שניהם\"\u0004 (שמות כב, ט–י), ומכאן נלמד \u0003הא\u0004 \u0005[הרי]\u0006 שאם \u0003יש רואה\u0004 — ש\u0003יביא ראיה ויפטר\u0004 ולא ישבע.","\u0003ור' חייא בר אבא אמר\u0004 בשם \u0003ר' יוחנן:\u0004 אין זה קושי, כי \u0003שבועה זו תקנת חכמים היא\u0004 לתקנת העולם, \u0003שאם אי\u0004 (אין) \u0003אתה אומר כן\u0004 שיוכל להפטר בשבועה — \u0003אין לך אדם המעביר חבית לחבירו ממקום למקום,\u0004 שיחשוש שמא תשבר ויצטרך לשלם.","ושואלים: \u0003היכי משתבע\u0004 \u0005[כיצד נשבע],\u0006 מה נוסח שבועה זו? \u0003אמר רבא:\u0004 אומר \u0003שבועה שלא בכוונה שברתיה. ואתא\u0004 \u0005[ובא]\u0006 \u0003ר' יהודה למימר\u0004 \u0005[לומר]:\u0006 \u0003שומר חנם\u0004 אכן \u0003ישבע, נושא שכר ישלם, האי כדיניה והאי כדיניה\u0004 \u0005[זה כדינו וזה כדינו].\u0006 \u0003ואתא\u0004 \u0005[ובא]\u0006 \u0003ר' אלעזר למימר\u0004 \u0005[לומר]:\u0006 \u0003אין, גמרא\u0004 \u0005[כן, המסורת]\u0006 היא \u0003כ\u0004שיטת \u0003ר' מאיר,\u0004 \u0003ומיהו\u0004 \u0005[ואולם],\u0006 \u0003תמיה אני אם יכולים זה וזה לישבע.\u0004","וטעמו: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003שומר חנם\u0004 — \u0003משתבע\u0004 \u0005[נשבע]\u0006 \u0003שלא פשע\u0004 \u0005[התרשל]\u0006 \u0003בה,\u0004 \u0003אלא שומר שכר אמאי משתבע\u0004 \u0005[מדוע נשבע]?\u0006 \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003לא פשע נמי בעי שלומי\u0004 \u0005[גם כן צריך לשלם].\u0006 \u0003ואפילו שומר חנם נמי\u0004 \u0005[גם כן],\u0006 \u0003הא תינח\u0004 \u0005[זה נוח]\u0006 אם נשברה \u0003במקום מדרון,\u0004 ואולם אם נשברה \u0003שלא במקום מדרון מי מצי משתבע\u0004 \u0005[האם יכול\u0006 הוא \u0005להשבע]\u0006 \u0003שלא פשע?\u0004","\u0003ואפילו במקום מדרון נמי\u0004 \u0005[גם כן],\u0006 \u0003הא תינח היכא דליכא\u0004 \u0005[זה נוח במקום שאין]\u0006 \u0003ראיה,\u0004 ואולם \u0003היכא דאיכא\u0004 \u0005[במקום שיש]\u0006 \u0003ראיה\u0004 — \u0003ניתי\u0004 \u0005[שיביא]\u0006 \u0003ראיה ויפטר.\u0004 \u0003דתניא\u0004 \u0005[שהרי שנינו\u0006 בברייתא\u0005],\u0006 \u0003איסי בן יהודה אומר: \"אין ראה שבעת ה' תהיה בין שניהם\" הא\u0004 \u0005[הרי]\u0006 אם \u0003יש רואה\u0004 — \u0003יביא ראיה ויפטר.\u0004","בענין הלכות אלה מסופר: \u0003ההוא גברא דהוה קא מעבר חביתא דחמרא בריסתקא\u0004 \u0005[אדם אחד היה מעביר חבית יין בשוק]\u0006 של \u0003מחוזא ותברה בזיזא\u0004 של \u0003מחוזא\u0004 \u0005[ושברה באחד מבליטות החומה].\u0006 \u0003אתא לקמיה\u0004 \u0005[בא\u0006 הענין \u0005לפני]\u0006 \u0003רבא.\u0004 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003ריסתקא\u0004 \u0005[השוק]\u0006 של \u0003מחוזא שכיחי בה אינשי, זיל, אייתי\u0004 \u0005[מצויים בו אנשים, לך, הבא]\u0006 \u0003ראיה ואיפטר\u0004 \u0005[והיפטר].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב יוסף בריה\u0004 \u0005[בנו]:\u0006 \u0003כמאן\u0004 \u0005[כמי]\u0006 פוסק אתה – \u0003כאיסי\u0004 בן יהודה? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אין\u0004 \u0005[כן]\u0006 \u0003כאיסי, וסבירא לן כוותיה\u0004 \u0005[וסבורים אנו כשיטתו]\u0006 שמקובלת שיטתו להלכה. מסופר: \u0003ההוא גברא\u0004 \u0005[אדם אחד]\u0006 ש\u0003אמר ליה לחבריה\u0004 \u0005[לו לחבירו]:\u0006 \u0003זיל זבין\u0004 \u0005[לך קנה]\u0006 \u0003לי ארבע מאה דני חמרא\u0004 \u0005[מאות כדי יין].\u0006 \u0003אזל זבן ליה\u0004 \u0005[הלך\u0006 ו\u0005קנה לו].\u0006 \u0003לסוף אתא לקמיה\u0004 \u0005[לבסוף בא לפניו]\u0006 ו\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003זביני\u0004 \u0005[קניתי]\u0006 \u0003לך ארבע מאה דני חמרא ותקיפו להו\u0004 \u0005[מאות כדי יין והחמיצו להם].\u0006 \u0003אתא לקמיה\u0004 \u0005[בא\u0006 הדבר \u0005לפני]\u0006 \u0003רבא,\u0004 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003ארבע מאה דני חמרא תקיפי\u0004 \u0005[מאות חביות יין שהחמיצו]\u0006 \u0003קלא אית לה למילתא\u0004 \u0005[קול יש לו לדבר],\u0006 כלומר, מאורע כזה ודאי ידוע ומפורסם לרבים, ולכן \u0003זיל אייתי\u0004 \u0005[לך הבא]\u0006 \u0003ראיה דמעיקרא כי מזבנת להו חמרא מעליא הוה, ואיפטר\u0004 \u0005[שמתחילה כאשר קנית אותם יין טוב היה,\u0006 \u0005והיפטר]\u0006 בלא שבועה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב יוסף בריה\u0004 \u0005[בנו]:\u0006 \u0003כמאן\u0004 \u0005[כמי]\u0006 פוסק אתה כאן — \u0003כאיסי\u0004 בן יהודה? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אין\u0004 \u0005[כן],\u0006 \u0003כאיסי, וסבירא לן כוותיה\u0004 \u0005[וסבורים אנו כשיטתו].\u0006","","","מסופר: \u0003אתקין\u0004 \u0005[התקין]\u0006 \u0003רב חייא בר יוסף ב\u0004עיר \u0003סיכרא\u0004 שהוא היה החכם בעיר זו: \u0003הני דדרו באגרא ואיתבר\u0004 \u0005[אלה שנושאים\u0006 משא במוט \u0005ונשבר]\u0006 החפץ — \u0003נשלם פלגא\u0004 \u0005[שישלמו חצי].\u0006 \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר — המוט הזה שמשתמשים בו לשאת \u0003נפיש לחד וזוטר לתרי\u0004 \u0005[מרובה\u0006 מכוחו \u0005של\u0006 אדם \u0005אחד וקטן\u0006 משל \u0005שנים],\u0006 שמצד אחד קשה מאוד לטעון אותו לבד, ואין רגילים לשאתו בשנים, ואם נשבר — הרי זה \u0003קרוב לאונס,\u0004 \u0003ו\u0004מצד שני אם טענו לבדו — הרי זה \u0003קרוב לפשיעה,\u0004 ולכן מתפשרים במחצית. ואולם אם נשא \u0003בדיגלא\u0004 \u0005[בעץ\u0006 העשוי למשא כפול\u0005]\u0006 — \u0003משלם כולה\u0004 \u0005[משלם הכל],\u0006 שוודאי רשלנות היא זו כשמנסה לקחת דבר שאינו לפי כוחו.","מסופר: \u0003רבה בר בר חנן תברו ליה הנהו שקולאי חביתא דחמרא\u0004 \u0005[שברו לו הסבלים חבית יין]\u0006 שנשכרו להוביל, \u0003שקל לגלימייהו\u0004 \u0005[לקח את גלימותיהם]\u0006 כדי ליפרע מן הגלימות את מחיר היין. \u0003אתו\u0004 \u0005[באו]\u0006 ו\u0003אמרו לרב\u0004 מה עשה. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הב להו גלימייהו\u0004 \u0005[תן להם\u0006 את \u0005גלימותיהם].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבה בר בר חנן: וכי \u0003דינא הכי\u0004 \u0005[כך\u0006 הוא \u0005הדין]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אין\u0004 \u0005[כן],\u0006 שנאמר \u0003\"למען תלך בדרך טובים\"\u0004 (משלי ב, כ). \u0003יהיב להו גלימייהו\u0004 \u0005[נתן להם\u0006 את \u0005גלימותיהם].\u0006 \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003עניי אנן, וטרחינן כולה יומא, וכפינן, ולית לן מידי\u0004 \u0005[עניים אנחנו, וטרחנו כל היום, ואנו רעבים, ואין לנו דבר];\u0006 \u0003אמר ליה\u0004 \u0005[אמר לו]\u0006 רב לרבה בר בר חנן: \u0003זיל הב אגרייהו\u0004 \u0005[לך תן\u0006 להם \u0005שכרם].\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 וכי \u0003דינא הכי\u0004 \u0005[הדין כך]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אין\u0004 \u0005[כן],\u0006 שכן נאמר: \u0003\"וארחות צדיקים תשמר\"\u0004 (שם).","","\u0003השוכר את הפועלים\u0004 לעבוד אצלו \u0003ואמר להם להשכים ולהעריב\u0004 יותר מן הרגיל, \u0003מקום שנהגו שלא להשכים ושלא להעריב\u0004 — \u0003אינו רשאי לכופן\u0004 (להכריחם). \u0003מקום שנהגו לזון\u0004 את הפועלים העובדים אצלו — \u0003יזון.\u0004 מקום שנהגו \u0003לספק\u0004 להם מיני \u0003מתיקה\u0004 בסעודתם — \u0003יספק. הכל כמנהג המדינה.\u0004","מסופר: \u0003מעשה בר' יוחנן בן מתיא שאמר לבנו: צא שכור לנו פועלין. הלך\u0004 הבן, שכרם \u0003ופסק להם מזונות\u0004 בלי לפרש אלו מזונות.","\u0003וכשבא אצל אביו\u0004 וסיפר לו, \u0003אמר לו: בני, אפילו אם אתה עושה להם כסעודת שלמה בשעתו לא יצאת ידי חובתך עמהן\u0004 לתת להם מזונות כראוי להם, לפי \u0003שהן בני אברהם יצחק ויעקב\u0004 וראויים לכל כבוד. \u0003אלא עד\u0004 (כל עוד) \u0003שלא יתחילו במלאכה צא ואמור להם: על מנת שאין לכם עלי אלא פת וקטנית בלבד,\u0004 כדרך שנוהגים לתת לפועלים. \u0003רבן שמעון בן גמליאל אומר: לא היה צריך לומר\u0004 זאת, כי \u0003הכל כמנהג המדינה\u0004 ולפי מנהג המדינה כך זן אותם, ואין צורך לפרש.","על דברי המשנה שאין בעל הבית יכול לכפות את הפועלים להשכים ולהעריב לעבודתם שואלים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]!\u0006 ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא במקרה \u0003דטפא להו אאגרייהו\u0004 \u0005[שהוסיף להם על שכרם]\u0006 יותר מן המקובל. \u0003מהו דתימא\u0004 \u0005[שתאמר],\u0006 \u0003אמר להו\u0004 \u0005[\u0006יכול הוא \u0005לומר להם]:\u0006 \u0003הא דטפאי לכו אאגרייכו\u0004 \u0005[זה שהוספתי לכם על שכרכם]\u0006 \u0003אדעתא דמקדמיתו ומחשכיתו בהדאי\u0004 \u0005[על דעת שתשכימו ותחשיכו,\u0006 תעריבו, \u0005עמי],\u0006 על כן \u0003קא משמע לן דאמרו ליה\u0004 \u0005[השמיע לנו\u0006 שיכולים הם \u0005לומר לו]:\u0006 \u0003האי דטפת לן\u0004 \u0005[זה שהוספת לנו]\u0006 — הוא \u0003אדעתא דעבדינן\u0004 \u0005[על דעת שנעשה]\u0006 \u0003לך עבידתא שפירתא\u0004 \u0005[עבודה טובה יותר]\u0006 אבל לא הסכמנו להוסיף בזמן העבודה.","\u0003אמר ריש לקיש:\u0004"],["\u0003פועל בכניסתו\u0004 לעיר מעבודתו מוסיף קצת \u0003משלו,\u0004 שעובד עד הערב ואז חוזר לביתו, ואולם \u0003ביציאתו\u0004 לעבודה איננו מתחיל בעבודה בהשכמת הבוקר אלא \u0003משל בעל הבית,\u0004 לפי שאינו יוצא לעבודה לפני הזריחה, וכפי \u0003שנאמר: \"תזרח השמש יאספון ואל מעונתם ירבצון. יצא אדם לפעלו ולעבדתו עדי ערב\"\u0004 (תהלים קד, כב–כג). משמע שאדם יוצא לעבודתו בבוקר עם זריחת השמש, ועובד עד הערב.","כיון שכבר אמרו כי בזה הכל כמנהג המדינה, שואלים: \u0003וליחזי היכי נהיגי\u0004 \u0005[ושיראה איך נוהגים]\u0006 באותו מקום וכן יעשה, ולשם מה קבע ריש לקיש הלכה בזה? ומשיבים: מדובר פה \u0003בעיר חדשה\u0004 שאין לה מנהג קבוע. ומקשים: \u0003וניחזי מהיכא קא אתו\u0004 \u0005[ונראה מהיכן באו]\u0006 אנשי אותה עיר — וינהגו כמנהג מקומם! ומשיבים: \u0003בנקוטאי\u0004 \u0005[במלוקטים],\u0006 שבאו אנשים ממקומות שונים בעלי מנהגים נבדלים. \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 הסבר אחר: אפילו במקום שיש בו מנהג, אלא ש\u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003דאגריתו\u0004 \u0005[שאתם נשכרים]\u0006 \u0003לי\u0004 לעשות \u0003כ\u0004דין \u0003פועל דאורייתא\u0004 \u0005[מן התורה],\u0006 ובא ריש לקיש לומר מה מנהג פועל מן התורה, אף שבכל מקום מותר לשנות ממנהג זה.","כיון שהוזכר פסוק זה, מביאים מה ש\u0003דרש ר' זירא ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 כי \u0003תני\u0004 \u0005[שנה]\u0006 זאת \u0003רב יוסף\u0004 בברייתא: \u0003מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"תשת חשך ויהי לילה בו תרמש כל חיתו יער\"\u0004 (שם כ), \u0003\"תשת חשך ויהי לילה\"\u0004 — \u0003זה העולם הזה, שדומה ללילה. \"בו תרמש כל חיתו יער\"\u0004 — \u0003אלו רשעים שבו, שדומין לחיה שביער\u0004 שעכשיו הם השולטים בעולם.","אבל בעולם הבא: \u0003\"תזרח השמש יאספון ואל מעונתם ירבצון\"\u0004 (שם כב); \u0003\"תזרח השמש\"\u0004 — \u0003לצדיקים, \"יאספון\"\u0004 — \u0003רשעים לגיהנם, \"ואל מעונתם ירבצון\"\u0004 — ללמד: \u0003אין לך כל צדיק וצדיק שאין לו\u0004 בעולם הבא \u0003מדור\u0004 לעצמו \u0003לפי כבודו. \"יצא אדם לפעלו\"\u0004 (שם כג) — \u0003יצאו צדיקים לקבל שכרן, \"ולעבדתו עדי ערב\"\u0004 (שם) — מדובר \u0003במי שהשלים עבודתו עדי ערב,\u0004 עד ששקעה שמשו, עד יום מותו.","כיון שדנו בזמן שבו הולכים אנשים כרגיל לעבודתם, מביאים מעשה ארוך הקשור בכך. \u0003ר' אלעזר בר' שמעון אשכח לההוא פרהגונא דקא תפיס גנבי\u0004 \u0005[מצא פקיד אחד שהיה\u0006 תפקידו להיות \u0005תופס גנבים],\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003היכי יכלת להו, לאו כחיותא מתילי\u0004 \u0005[כיצד יכול אתה\u0006 לתפוס \u0005אותם,\u0006 וכי \u0005לא נמשלו\u0006 הגנבים \u0005כחיות]?\u0006 שהרי נאמר \u0003\"בו תרמש כל חיתו יער\"\u0004 (שם כ). \u0003איכא דאמרי מהאי קרא קאמר ליה\u0004 \u0005[יש אומרים\u0006 ש\u0005מפסוק זה אמר לו\u0006 ראיה\u0005],\u0006 שנאמר: \u0003\"יארב במסתר כאריה בסכה\u0004 יארוב לחטוף עני... \" (תהלים י, ט), וכיון שהרשעים ערומים כל כך, \u0003דלמא שקלת צדיקי ושבקת רשיעי\u0004 \u0005[שמא לוקח אתה\u0006 לבית הסוהר \u0005צדיקים,\u0006 אנשים שלא גנבו, \u0005ואתה מניח את הרשעים]?\u0006","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003ומאי אעביד\u0004 \u0005[ומה אעשה]?\u0006 הלא \u0003הרמנא דמלכא הוא\u0004 \u0005[פקודת המלך היא]\u0006 שאהיה תופס גנבים, ואני עושה כמיטב יכולתי. \u0003אמר\u0004 לו ר' אלעזר בר' שמעון: \u0003תא אגמרך היכי תעביד\u0004 \u0005[בא ואלמד אותך מה תעשה];\u0006 \u0003עול\u0004 \u0005[היכנס]\u0006 \u0003בארבע שעי\u0004 \u0005[שעות\u0006 ביום\u0005],\u0006 בערך בשעה עשר בבוקר \u0003לחנותא\u0004 \u0005[לחנות]\u0006 שבה מוכרים יין ומזונות, \u0003כי חזית איניש דקא שתי חמרא וקא נקיט כסא בידיה וקא מנמנם שאול עילויה\u0004 \u0005[כאשר תראה אדם השותה יין ומחזיק את הכוס בידו ומנמנם שאל עליו]\u0006 לברר מי הוא,","\u0003אי צורבא מרבנן\u0004 \u0005[אם תלמיד חכם]\u0006 \u0003הוא וניים\u0004 \u0005[ו\u0006הוא \u0005מנמנם]\u0006 — מן הסתם \u0003אקדומי קדים לגרסיה\u0004 \u0005[\u0006\u0005הקדים ללמודו\u0006 בהשכמת הבקר\u0005]\u0006 ומשום כך מנמנם הוא עכשיו. \u0003אי\u0004 \u0005[אם]\u0006 \u0003פועל הוא\u0004 — \u0003קדים קא עביד עבידתיה\u0004 \u0005[הקדים ועבד עבודתו],\u0006 \u0003ואי עבידתיה בליליא\u0004 \u0005[ו\u0006אפילו \u0005אם עבודתו בלילה]\u0006 — שמא \u0003רדודי רדיד\u0004 \u0005[עיצב חוטים]\u0006 שיתכן שלא שמעו אותו כשעובד. \u0003ואי\u0004 \u0005[ואם]\u0006 הוא \u0003לא\u0004 אחד מאלה — מן הסתם \u0003גנבא\u0004 \u0005[גנב]\u0006 \u0003הוא ותפסיה\u0004 \u0005[ותפוס אותו],\u0006 שכיון שהיה גנב בלילה הוא ישן ביום.","\u0003אישתמע מילתא בי מלכא\u0004 \u0005[נשמע הדבר בבית המלך]\u0006 שנתן עצה טובה זו, \u0003אמרו,\u0004 לפי פתגם מפורסם: \u0003קריינא דאיגרתא איהו ליהוי פרונקא\u0004 \u0005[קורא האיגרת הוא שיהיה שליח\u0006 הביצוע\u0005],\u0006 שמי שקרא ברבים את האגרת, הצו המלכותי, ייעשה הממונה על ביצוע הפקודה. ואף כאן כיון שאתה נותן עצות טובות כאלה — היה אתה הממונה על כך. \u0003אתיוה\u0004 \u0005[הביאו אותו]\u0006 את \u0003ר' אלעזר בר' שמעון\u0004 לפני השלטונות, ומינו אותו לתפקיד זה, \u0003וקא תפיס גנבי ואזיל\u0004 \u0005[והיה תופס גנבים והולך].\u0006 \u0003שלח ליה\u0004 \u0005[לו]\u0006 \u0003ר' יהושע בן קרחה\u0004 את הדברים הבאים: \u0003\"חומץ בן יין\"!\u0004 כלומר, הרי אתה כרשע (חומץ) לעומת אביך הצדיק ר' שמעון (יין), \u0003עד מתי אתה מוסר עמו של אלהינו להריגה\u0004 בידי המלכות?","\u0003שלח ליה\u0004 \u0005[לו]\u0006 ר' אלעזר: \u0003קוצים אני מכלה מן הכרם\u0004 שהרי אני מבער מישראל רק את הרשעים. \u0003שלח ליה\u0004 \u0005[לו]\u0006 בחזרה: \u0003יבא בעל הכרם ויכלה את קוציו,\u0004 אבל אתה אל תעשה זאת עבור המלכות. וכנראה שדברים אלה נשמעו גם ברבים, ומסופר: \u0003יומא חד פגע ביה ההוא כובס, קרייה\u0004 \u0005[יום אחד פגע בו כובס אחד\u0006 עם הארץ ו\u0005קראו]\u0006 לר' אלעזר \u0003\"חומץ בן יין\".\u0004 \u0003אמר\u0004 ר' אלעזר: \u0003מדחציף כולי האי\u0004 \u0005[מכיון ש\u0006הוא \u0005חצוף כל כך]\u0006 שקורא לתלמיד חכם בכינוי גנאי — \u0003שמע מינה רשיעא\u0004 \u0005[למד מכאן\u0006 ש\u0005רשע]\u0006 \u0003הוא.\u0004 \u0003אמר להו\u0004 \u0005[להם,\u0006 לשוטרים\u0005]:\u0006 \u0003תפסוהו\u0004 כפושע. \u0003תפסוהו\u0004 ודנו אותו למיתה,","\u0003לבתר דנח דעתיה\u0004 \u0005[לאחר שנחה דעתו,\u0006 נרגע מכעסו\u0005]\u0006 התחרט ר' אלעזר על ששלח אדם חף מפשע למות. \u0003אזל בתריה לפרוקיה\u0004 \u0005[הלך אחריו לפדותו]\u0006 \u0003ולא מצי\u0004 \u0005[יכול].\u0006 \u0003קרי עליה\u0004 \u0005[קרא עליו]:\u0006 \u0003\"שמר פיו ולשונו שמר מצרות נפשו\"\u0004 (משלי כא, כג), כלומר, לולא אמר הכובס דברים אלה לא היה נכנס בצרה זו. לבסוף \u0003זקפוהו\u0004 \u0005[תלו אותו]\u0006 את הכובס, \u0003קם תותי זקיפא וקא בכי\u0004 \u0005[עמד\u0006 ר' אלעזר \u0005תחת עץ התליה ובכה].\u0006 \u0003אמרו ליה\u0004 \u0005[לו]\u0006 אנשים: \u0003רבי, אל ירע בעיניך\u0004 שכך עשית לו, לפי שכובס זה היה רשע גמור עד \u0003שהוא ובנו\u0004 יחד \u0003בעלו נערה מאורסה ביום הכפורים\u0004 ועברו כמה וכמה עבירות חמורות במעשה זה עצמו. ובודאי מגיע לו עונש זה.","\u0003הניח\u0004 ר' אלעזר \u0003ידו על בני מעיו\u0004 ו\u0003אמר: שישו בני מעי, שישו! ומה ספיקות שלכם כך,\u0004 כלומר, שרק משום שראה בו חוצפה אמר שוודאי רשע הוא, \u0003ודאית שלכם\u0004 אותם גנבים שהוא מעניש לפי סברה ברורה — \u0003על אחת כמה וכמה\u0004 ובוודאי יפה עשה, ולא תפס אנשים חפים מפשע. ואמר: \u0003מובטח אני בכם,\u0004 בבני מעי, \u0003שאין רמה ותולעה שולטת בכם,\u0004 שכן זה הוא סימנו של צדיק גמור.","\u0003ואפילו הכי\u0004 \u0005[כך]\u0006 לאחר ששמע את המעשה \u0003לא מייתבא דעתיה\u0004 וחשש שמא גרם מיתה שלא כהוגן, ולכן עשה נסיון בעצמו. \u0003אשקיוהו סמא דשינתא ועיילוהו לביתא דשישא וקרעו לכריסיה\u0004 \u0005[השקו אותו סם שינה והכניסו אותו לבית של שיש\u0006 שבו היו עושים ניתוחים \u0005וקרעו את כרסו].\u0006 \u0003הוו מפקו מיניה דיקולי דיקולי דתרבא ומותבי בשמשא\u0004 \u0005[היו מוציאים ממנו סלים סלים של חלב ושמים בשמש]\u0006 \u0003ב\u0004חדשי \u0003תמוז ואב ולא מסרחי\u0004 \u0005[היה מסריח]\u0006 ועל ידי כך הוכיח ר' אלעזר בעצמו שצדיק גמור הוא, וכל שעשה — כהוגן עשה.","ומקשים: דבר זה אינו הוכחה, \u0003כל תרבא נמי לא סריח\u0004 \u0005[חלב גם כן אינו מסריח],\u0006 שחלב נקי רק נמס בחמה ולא יותר! ומשיבים: \u0003כל תרבא לא סריח, שורייקי סומקי מסריח\u0004 \u0005[חלב\u0006 נקי \u0005אינו מסריח,\u0006 אבל \u0005גידים אדומים\u0006 של דם שבו \u0005מסריחים]\u0006 ולכן חלב בלתי מעובד ריחו רע. \u0003הכא אף על גב דאיתא שורייקי סומקי\u0004 \u0005[כאן אף על פי שהיו גידים אדומים]\u0006 — \u0003לא מסריח\u0004 \u0005[הסריח]\u0006 והרי זו הוכחה שצדיק גמור הוא. \u0003קרי אנפשיה\u0004 \u0005[קרא על עצמו]\u0006 \u0003\"\u0004שויתי ה' לנגדי תמיד... \u0003אף בשרי ישכן לבטח\"\u0004 (תהילים טז, ח–ט).","מסופר: \u0003אף ר' ישמעאל בר' יוסי מטא\u0004"],["\u0003כי האי מעשה לידיה\u0004 \u0005[הגיע מעשה כזה לידו]\u0006 שמינוהו ראש המשטרה. \u0003פגע ביה\u0004 \u0005[פגש בו]\u0006 \u0003אליהו\u0004 הנביא\u0005,\u0006","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003עד מתי אתה מוסר עמו של אלהינו להריגה? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מאי אעביד\u0004 \u0005[מה אעשה]?\u0006 הלא \u0003הרמנא דמלכא הוא\u0004 \u0005[פקודת המלך היא]!\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אבוך ערק\u0004 \u0005[אביך ברח]\u0006 במקרה כזה \u0003לאסיא, את ערוק\u0004 \u0005[אתה ברח]\u0006 \u0003ללודקיא\u0004 ואל תכנס לתפקיד כזה.","כיון שהוזכרו חכמים אלה ומעשים דומים שאירעו להם, מסופר עוד עליהם: \u0003כי הוו מקלעי\u0004 \u0005[כאשר היו מזדמנים]\u0006 \u0003ר' ישמעאל בר' יוסי ור' אלעזר בר' שמעון בהדי הדדי\u0004 \u0005[ביחד],\u0006 \u0003הוה עייל בקרא דתורי בינייהו\u0004 \u0005[היה\u0006 יכול \u0005צמד שוורים להיכנס ביניהם\u0006 תחת כריסם\u0005]\u0006 \u0003ולא הוה נגעה בהו\u0004 \u0005[היה נוגע בהם],\u0006 כיון שהיו שמנים מאד.","ומספרים, \u0003אמרה להו ההיא מטרוניתא\u0004 \u0005[להם גבירה\u0006 רומאית \u0005אחת]:\u0006 \u0003בניכם אינם שלכם,\u0004 שמפני גודל כריסכם ודאי אינכם מסוגלים להזקק לנשיכם. \u0003אמרו לה: שלהן\u0004 (כרסן של נשינו) \u0003גדול משלנו.\u0004 אמרה להם: \u0003כל שכן\u0004 שאין הדבר אפשרי לכם. \u0003איכא דאמרי\u0004 \u0003הכי\u0004 \u0005[יש אומרים\u0006 ש\u0005כך]\u0006 \u0003אמרו לה:\u0004 \u0003\"כי כאיש גבורתו\"\u0004 (שופטים ח, כא), כלומר, כל אברינו מגודלים בהתאם לגודל כריסנו. \u0003איכא דאמרי, הכי\u0004 \u0005[יש אומרים\u0006 ש\u0005כך]\u0006 \u0003אמרו לה:\u0004 \u0003אהבה דוחקת את הבשר.\u0004","ושואלים: \u0003ולמה להו לאהדורי\u0004 \u0005[להם להשיב]\u0006 \u0003לה\u0004 על שאלה מחוצפת ומטופשת כזו? \u0003והא כתיב\u0004 \u0005[והרי נאמר]\u0006 \u0003\"אל תען כסיל כאיולתו\u0004 פן תשוה לו גם אתה\u0003\"\u0004 (משלי, כו, ד)! ומשיבים: זה שהשיבו לה הוא משום \u0003שלא להוציא לעז על בניהם,\u0004 שאם לא היו עונים הרי היו כמסכימים לדבר, ונמצא שבניהם ממזרים, ולכן הוצרכו לענות.","כיון שהוזכר מעשה זה בשומנם של חכמים אלה, מספרים כיוצא בזה ש\u0003אמר ר' יוחנן: איבריה\u0004 \u0005[איבריו]\u0006 של \u0003ר' ישמעאל בר' יוסי כחמת בת תשע קבין,\u0004 שהיו גדולים כנאד שמכיל תשעה קבים. \u0003אמר רב פפא: איבריה\u0004 \u0005[איבריו]\u0006 של \u0003ר' יוחנן כחמת בת חמשת קבין, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 \u0003בת שלשת קבין.\u0004 ומעירים: כרסו של \u0003רב פפא גופיה\u0004 \u0005[עצמו]\u0006 \u0003כי דקורי דהרפנאי\u0004 \u0005[כמו הסלים של הרפניא].\u0006","כיון שנאמרו דברים על שומנו של ר' יוחנן, מתארים עוד את מראהו. \u0003אמר ר' יוחנן: אנא אשתיירי משפירי\u0004 \u0005[אני נשארתי מהיפים]\u0006 של \u0003ירושלים,\u0004 שהיה יפה תואר מאד. ומספרים: \u0003האי מאן דבעי מחזי שופריה\u0004 \u0005[מי שרוצה לראות\u0006 מה היה \u0005יופיו]\u0006 של \u0003ר' יוחנן,\u0004 \u0003נייתי כסא דכספא מבי סלקי\u0004 \u0005[\u0006ש\u0005יביא כוס כסף מבית הצורף]\u0006 כשהיא חדשה והכסף לבן ביותר, \u0003ונמלייה פרצידיא דרומנא סומקא\u0004 \u0005[וימלא אותה גרעיני רימון אדום],\u0006 \u0003ונהדר ליה כלילא דוורדא סומקא לפומיה\u0004 \u0005[וישים זר ורדים אדומים על פיו]\u0006 של הכוס, \u0003ונותביה בין שמשא לטולא\u0004 \u0005[ויעמיד אותה בין החמה והצל],\u0006 \u0003ההוא זהרורי\u0004 \u0005[אותו הזוהר]\u0006 שיש לציור זה הוא \u0003מעין שופריה\u0004 \u0005[יופיו]\u0006 של \u0003ר' יוחנן.\u0004","ושואלים: \u0003איני\u0004 \u0005[\u0006האם \u0005כן הוא]\u0006 שהיה ר' יוחנן יפה כל כך? \u0003והאמר מר\u0004 \u0005[והרי אמר החכם]:\u0006 \u0003שופריה\u0004 \u0005[יופיו]\u0006 של \u0003רב כהנא\u0004 היה \u0003מעין שופריה\u0004 \u0005[יופיו]\u0006 של \u0003ר' אבהו, שופריה\u0004 \u0005[יופיו]\u0006 של \u0003ר' אבהו מעין שופריה\u0004 \u0005[יופיו]\u0006 של \u0003יעקב אבינו, שופריה\u0004 \u0005[יופיו]\u0006 של \u0003יעקב אבינו מעין שופריה\u0004 \u0005[יופיו]\u0006 של \u0003אדם הראשון,\u0004 ואדם הראשון הלא נברא בצלם אלקים, בתכלית השלמות. \u0003ואילו\u0004 את \u0003ר' יוחנן לא קא חשיב ליה\u0004 \u0005[מנה]\u0006 ברשימה זו, משמע שלא היה יפה כמותם! ומשיבים: \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003ר' יוחנן\u0004 ש\u0003הדרת פנים לא הויא ליה\u0004 \u0005[היתה לו],\u0006 שלא היה זקנו מגודל, ולכן לא היה נחשב מושלם בכל היופי.","ועוד מספרים על יופיו של ר' יוחנן: \u0003ר' יוחנן הוה אזיל ויתיב\u0004 \u0005[היה הולך ויושב]\u0006 על \u0003שערי\u0004 בית ה\u0003טבילה,\u0004 \u0003אמר\u0004 בלבו: \u0003כי סלקן\u0004 \u0005[כאשר עולות]\u0006 \u0003בנות ישראל\u0004 \u0003מטבילת מצוה לפגעו\u0004 \u0005[שיפגשו]\u0006 \u0003בי\u0004 תחילה, \u0003כי היכי דלהוו להו בני שפירי כוותי, גמירי אורייתא כוותי\u0004 \u0005[כדי שיהיו להם בנים יפים כמוני,\u0006 ו\u0005לומדי תורה כמוני],\u0006 שמוחזק בידם שתמונה הנחקקת בלב האשה בשעת זיווג משפיעה על דמות ילדיה.","\u0003אמ\u0004 \u0003רו ליה רבנן\u0004 \u0005[לו חכמים]:\u0006 וכי \u0003לא מסתפי מר מעינא בישא\u0004 \u0005[חושש אדוני מעין הרע]\u0006 שאתה כך מעמיד את עצמך לראוה? \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003אנא מזרעא\u0004 \u0005[אני מזרעו]\u0006 של \u0003יוסף קאתינא\u0004 \u0005[אני בא],\u0006 ש\u0003לא שלטא ביה עינא בישא\u0004 \u0005[שולטת בו עין הרע].\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"בן פרת יוסף בן פרת עלי עין\"\u0004 (בראשית מט, כב), \u0003ואמר ר' אבהו\u0004 בפירוש הפסוק: \u0003אל תקרי\u0004 \u0005[אל תקרא]\u0006 \u0003\"עלי עין\" אלא \"עולי עין\",\u0004 כלומר, מעולים ונעלמים מן העין, שאין העין הרעה שולטת בו.","\u0003ר' יוסי בר חנינא אמר מהכא\u0004 \u0005[מכאן]\u0006 יש ראיה לענין זה: שבברכת יעקב לבני יוסף נאמר \u0003\"וידגו לרב בקרב הארץ\"\u0004 (בראשית מח, טז), ללמד: \u0003מה דגים שבים מים מכסים אותם, ואין העין שולטת בהן\u0004 — \u0003אף זרעו של יוסף אין העין שולטת בהן.\u0004","ועוד מספרים מעשה אחר הקשור ביופיו של ר' יוחנן. \u0003יומא חד הוה קא סחי\u0004 \u0005[יום אחד היה שוחה]\u0006 \u0003ר' יוחנן בירדנא\u0004 \u0005[בירדן].\u0006 \u0003חזייה\u0004 \u0005[ראהו]\u0006 \u0003ריש לקיש ושוור לירדנא אבתריה\u0004 \u0005[וקפץ לירדן אחריו],\u0006 ובאותו זמן לא עסק ריש לקיש בתורה אלא היה קשור ללודרים בקרקס. \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יוחנן לריש לקיש \u0003חילך לאורייתא\u0004 \u0005[גבורתך לתורה],\u0006 כלומר, אדם גבור כמוך צריך להשקיע כוחו בעיסוק התורה! \u0003אמר ליה\u0004 \u0005[לו]\u0006 ריש לקיש: \u0003שופרך לנשי\u0004 \u0005[יופיך לנשים],\u0006 כלומר, יופי כמו שלך ראוי לאשה. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אי הדרת\u0004 \u0005[אם תחזור]\u0006 \u0003בך\u0004 ותשוב ללמוד את התורה שעזבת — \u0003יהיבנא\u0004 \u0005[אתן]\u0006 \u0003לך\u0004 את \u0003אחותי, דשפירא מינאי\u0004 \u0005[ש\u0006היא \u0005יפה ממני].\u0006 \u0003קביל עליה\u0004 \u0005[קבל על עצמו]\u0006 ריש לקיש לעשות כן. \u0003בעי למיהדר לאתויי מאניה\u0004 \u0005[רצה לחזור\u0006 בקפיצה \u0005להביא את בגדיו]\u0006 \u0003ולא מצי הדר\u0004 \u0005[היה יכול לחזור],\u0006 שכיון שקבל עליו עול תורה מיד נחלש.","\u0003אקרייה ואתנייה ושוייה גברא רבא\u0004 \u0005[לימד אותו\u0006 ר' יוחנן \u0005מקרא ומשנה ועשה אותו אדם גדול],\u0006 שנעשה ריש לקיש מגדולי חכמי ישראל בדורו. \u0003יומא חד הוו מפלגי בי מדרשא\u0004 \u0005[יום אחד היו חלוקים בבית המדרש]\u0006 בבעיה זו, ששנינו בברייתא: \u0003הסייף והסכין והפגיון והרומח\u0004 שהם כלי נשק, וכן \u0003מגל יד ומגל קציר, מאימתי מקבלין\u0004 הם \u0003טומאה\u0004 — \u0003משעת גמר\u0004","\u0003מלאכתן,\u0004 כדין שאר כלי מתכת. \u0003ו\u0004אולם נחלקו בשאלה \u0003מאימתי גמר מלאכתן? ר' יוחנן אומר: משיצרפם בכבשן,\u0004 ו\u0003ריש לקיש אמר:\u0004 לא די בצירוף בכבשן אלא \u0003משיצחצחן\u0004 אותם אחר כך \u0003במים.\u0004 ובתוך כדי הויכוח אמר לו ר' יוחנן בקצת כעס: \u0003לסטאה בלסטיותיה ידע\u0004 \u0005[שודד, בענייני שוד\u0006 הוא \u0005יודע],\u0006 כלומר, כיון שהיית גזלן בצעירותך הרי אתה בקיא בדברים אלה גם עכשיו! נעלב ריש לקיש ו\u0003אמר ליה\u0004 \u0005[לו]\u0006 לר' יוחנן: \u0003ומאי אהנת\u0004 \u0005[ומה הועלת]\u0006 \u0003לי\u0004 אם כן כשקרבתני ללמוד התורה? הלא \u0003התם\u0004 \u0005[שם]\u0006 בין הליסטים \u0003\"רבי\" קרו לי, הכא\u0004 \u0005[\u0006ו\u0005כאן]\u0006 \u0003\"רבי\" קרו\u0004 \u0005[קוראים]\u0006 \u0003לי!\u0004 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אהנאי לך דאקרבינך\u0004 \u0005[שקרבתי אותך]\u0006 \u0003תחת כנפי השכינה,\u0004 ומדוע אין אתה מכיר לי תודה?","בתוך כדי ויכוח זה \u0003חלש דעתיה\u0004 \u0005[חלשה דעתו,\u0006 נפגע ונעלב\u0005]\u0006 \u0003ר' יוחנן,\u0004 וכיון שהקפיד השפיעה הקפדתו ומיד \u0003חלש\u0004 \u0005[חלה]\u0006 \u0003ריש לקיש. אתאי אחתיה קא בכיא\u0004 \u0005[באה אחותו של\u0006 ר' יוחנן אשת ריש לקיש \u0005ובכתה]\u0006 לפניו שיתפלל על בעלה. \u0003אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003עשה בשביל בני\u0004 שיהא להם אב! \u0003אמר לה\u0004 בלשון הכתוב: \u0003\"עזבה יתמיך אני אחיה\"\u0004 (ירמיה מט, יא), שאני אדאג להם. אמרה לו: \u0003עשה בשביל אלמנותי,\u0004 שלא אשאר בודדה! \u0003אמר לה\u0004 את המשך הכתוב: \u0003\"ואלמנותיך עלי תבטחו\"\u0004 (שם).","ובסופו של דבר \u0003נח נפשיה\u0004 \u0005[נחה נפשו,\u0006 מת\u0005]\u0006 \u0003ר' שמעון בן לקיש\u0004 (ריש לקיש), \u0003והוה קא\u0004 \u0005[והיה]\u0006 \u0003מצטער ר' יוחנן בתריה טובא\u0004 \u0005[אחריו,\u0006 עליו, \u0005ביותר],\u0006 על חסרונו ועל מה שגרם לו. \u0003אמרו רבנן\u0004 \u0005[חכמים]:\u0006 \u0003מאן ליזיל ליתביה לדעתיה\u0004 \u0005[מי ילך\u0006 ו\u0005יישב את דעתו]\u0006 שלא יצטער כל כך? אמרו: \u0003ניזיל\u0004 \u0005[ילך]\u0006 \u0003ר' אלעזר בן פדת, דמחדדין שמעתתיה\u0004 \u0005[שמחודדות הלכותיו]\u0006 ויוכל להיות כעין תחליף לריש לקיש.","\u0003אזל יתיב קמיה\u0004 \u0005[הלך וישב לפניו].\u0006 \u0003כל מילתא דהוה אמר\u0004 \u0005[כל דבר שהיה אומר]\u0006 \u0003ר' יוחנן אמר ליה\u0004 \u0005[\u0006היה \u0005אומר לו]\u0006 ר' אלעזר: הרי \u0003תניא דמסייעא\u0004 \u0005[שנוייה\u0006 ברייתא \u0005שמסייעת]\u0006 \u0003לך,\u0004 לדבריך. \u0003אמר\u0004 לו ר' יוחנן: וכי \u0003את כבר לקישא\u0004 \u0005[אתה כבן לקיש],\u0006 וכי ביכולתך למלא את מקומו?! \u0003בר לקישא, כי הוה אמינא מילתא\u0004 \u0005[בן לקיש, כאשר הייתי אומר דבר],\u0006 \u0003הוה מקשי\u0004 \u0005[היה\u0006 הוא \u0005מקשה]\u0006 \u0003לי עשרין וארבע קושייתא\u0004 \u0005[קושיות],\u0006 \u0003ומפרקינא ליה\u0004 \u0005[והייתי מתרץ לו]\u0006 \u0003עשרין וארבעה פרוקי\u0004 \u0005[תירוצים],\u0006 \u0003וממילא רווחא שמעתא\u0004 \u0005[ומתוך כך היתה ההלכה מתרווחת]\u0006 — שבתוך המשא והמתן, הקושיות והתירוצים, היו הדברים מתבררים ומתבהרים. \u0003ואת אמרת\u0004 \u0005[ואתה אומר]\u0006 לי: \u0003\"תניא דמסייע לך\"\u0004 \u0005[\"שנויה\u0006 ברייתא \u0005המסייעת לך\"],\u0006 \u0003אטו לא ידענא דשפיר קאמינא\u0004 \u0005[וכי אינני יודע שיפה אמרתי]?\u0006 לא סיוע אני חסר, אלא להיפך: חסרה לי הבקורת המועילה של ריש לקיש.","\u0003הוה קא אזיל וקרע מאניה וקא בכי ואמר\u0004 \u0005[היה הולך וקורע את בגדיו ובוכה ואומר]:\u0006 \u0003\"היכא את בר לקישא, היכא את בר לקישא\"!\u0004 \u0005[\"היכן אתה בן לקיש, היכן אתה בן לקיש\"].\u0006 \u0003והוה קא צוח\u0004 \u0005[והיה צועק]\u0006 כך \u0003עד דשף דעתיה מיניה\u0004 \u0005[שניטלה דעתו ממנו].\u0006 \u0003בעו רבנן רחמי עליה ונח נפשיה\u0004 \u0005[בקשו חכמים רחמים עליו ונחה נפשו,\u0006 נפטר\u0005],\u0006 שלא ישאר במצב קשה זה."],["לאחר שאגב הדברים עסקנו בנושאים שונים אנו חוזרים למעשה הראשון של ר' אלעזר בר' שמעון שגרם לאותו כובס מחוצף למות, ובדק בעצמו ונוכח שצדיק הוא. ו\u0003אפילו הכי\u0004 \u0005[כך]\u0006 לאחר נסיון זה \u0003לא סמך ר' אלעזר בר' שמעון אדעתיה\u0004 \u0005[על דעתו],\u0006 \u0003קביל עליה יסורי\u0004 \u0005[\u0006ו\u0005קיבל על עצמו יסורים]\u0006 לכפר על עוונו. \u0003באורתא הוו מייכי ליה שיתין נמטי\u0004 \u0005[בערב היו מקפלים לו שישים\u0006 מצעות של \u0005לבד],\u0006 \u0003לצפרא נגדי מתותיה שיתין משיכלי דמא וכיבא\u0004 \u0005[בבקר היו מוציאים מתחתיו,\u0006 למרות הלבד, \u0005שישים כלים של דם ומוגלה].\u0006","\u0003למחר,\u0004 כלומר, בכל בוקר, \u0003עבדה ליה דביתהו שיתין מיני לפדא ואכיל להו וברי\u0004 \u0005[עשתה לו אשתו שישים מיני ליפתן ואכל אותם והבריא].\u0006 \u0003ולא הות שבקא ליה דביתהו למיפק לבי מדרשא כי היכי\u0004 \u0005[הניחה לו אשתו ללכת לבית המדרש כדי]\u0006 ש\u0003לא לדחקוהו רבנן\u0004 \u0005[ידחקוהו חכמים]\u0006 משום שחששה לבריאותו.","והוא היה ממשיך לנהוג באותו אופן, \u0003באורתא\u0004 \u0005[בערב]\u0006 \u0003אמר להו\u0004 \u0005[להם]\u0006 ליסוריו: \u0003אחיי ורעי, בואו! בצפרא\u0004 \u0005[בבוקר]\u0006 \u0003אמר\u0004 \u0003להו\u0004 \u0005[להם]:\u0006 \u0003זילו\u0004 \u0005[לכו]\u0006 \u0003מפני ביטול תורה. יומא חד שמעה דביתהו\u0004 \u0005[יום אחד שמעה אשתו]\u0006 מה הוא אומר, \u0003אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003את קא מייתית להו עילויך\u0004 \u0005[אתה\u0006 הוא \u0005שמביא אותם עליך]!\u0006 \u0003כלית ממון של בית אבא\u0004 במחלתך זו שאתה הוא הגורם לה — \u0003אימרדה, אזלה לבית נשא\u0004 \u0005[מרדה\u0006 בו \u0005והלכה\u0006 חזרה \u0005לבית אביה]\u0006 והוא נשאר בלא מי שיטפל בו, ובלא כסף.","\u0003סליקו ואתו הנך שיתין ספונאי\u0004 \u0005[עלו ובאו שישים ספנים],\u0006 \u0003עיילו ליה שיתין עבדי כי נקיטי שיתין ארנקי\u0004 \u0005[ובאו ששים ספנים, והכניסו,\u0006 הביאו, \u0005לו ששים עבדים כשהם מחזיקים\u0006 בידם \u0005ששים ארנקים],\u0006 \u0003ועבדו ליה שיתין מיני לפדא ואכיל להו\u0004 \u0005[ועשו לו שישים מיני ליפתן ואכל אותם]\u0006 שהיו אותם ספנים בסכנת טביעה, ונדרו שאם ינצלו בזכותו יביאו לו מתנות אלה. ונמצא שגם אחרי שהלכה אשתו היה מי שיטפל בו ברווחה.","\u0003יומא חד\u0004 \u0005[יום אחד]\u0006 \u0003אמרה לה\u0004 אשתו \u0003לברתה\u0004 \u0005[לבתה]:\u0006 \u0003זילי בקי באבוך מאי קא עביד האידנא\u0004 \u0005[לכי בדקי באביך מה הוא עושה כעת]?\u0006 \u0003אתיא\u0004 \u0005[באה]\u0006 אליו, \u0003אמר לה: זילי\u0004 \u0005[לכי]\u0006 ו\u0003אמרי לאמך:\u0004 \u0003שלנו,\u0004 רכושנו שלנו בבית כעת, \u0003גדול משלהם\u0004 משל בית משפחת אמך. \u0003קרי אנפשיה\u0004 \u0005[קרא על עצמו]\u0006 פסוק זה: \u0003\"היתה כאניות סוחר ממרחק תביא לחמה\"\u0004 (משלי לא, יד). \u0003אכל ושתי וברי נפק לבי מדרשא\u0004 \u0005[ושתה והבריא ויצא לבית המדרש],\u0006 שהרי בזמן זה לא היתה אשתו שם שתמנע אותו.","\u0003אייתו לקמיה שיתין מיני דמא\u0004 \u0005[הביאו לפניו שישים מיני דם]\u0006 שהביאו נשים כתמי דם, שהיה ספק בידן אם זה דם נדה והן אסורות לבעליהן, או היה זה דם מסוג אחר — \u0003טהרינהו\u0004 \u0005[\u0006ו\u0005טיהר אותם]\u0006 את כולם. \u0003הוה קא מרנני רבנן ואמרי\u0004 \u0005[והיו חכמים מרננים\u0006 אחריו \u0005ואומרים]:\u0006 \u0003סלקא דעתך לית בהו חד\u0004 \u0005[עולה על דעתך\u0006 ש\u0005אין בהם אחד]\u0006 שיש בו \u0003ספק?!\u0004 ומן הסתם טעה במשהו. \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003אם כמותי הוא\u0004 — \u0003יהיו כולם\u0004 כל הילדים שיוולדו עכשיו מנשים אלה שטהרתי לבעליהן \u0003זכרים, ואם לאו\u0004 \u0005[לא]\u0006 — \u0003תהא נקבה אחת ביניהם.\u0004 ואכן נתברר כי \u0003היו כולם זכרים.\u0004 ומספרים: \u0003ואסיקו להו\u0004 \u0005[וקראו להם]\u0006 \u0003\"אלעזר\" על שמיה\u0004 \u0005[על שמו]\u0006 לזכרון אותו מעשה.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 \u0003אמר רבי: כמה פריה ורביה ביטלה רשעה זו\u0004 — אשתו של ר' אלעזר בר' שמעון \u0003מישראל,\u0004 שהרי כשלא הניחה אותו לבוא לבית המדרש, כמה וכמה נשים לא היו טהורות לבעליהן מחמת הספק, שלא היה איש בקיא כמותו לטהרן.","\u0003כי הוה קא ניחא נפשיה\u0004 \u0005[כאשר נחה נפשו,\u0006 עמד למות\u0005]\u0006 ר' אלעזר, \u0003אמר לה לדביתהו\u0004 \u0005[לאשתו]:\u0006 \u0003ידענא בדרבנן דרתיחי\u0004 \u0005[יודע אני בחכמים ש\u0006הם \u0005כועסים]\u0006 \u0003עלי, ולא מיעסקי\u0004 \u0005[יתעסקו,\u0006 יטפלו\u0005]\u0006 \u0003בי שפיר\u0004 \u0005[יפה\u0006 בקבורתי\u0005].\u0006 \u0003אוגנין בעיליתאי ולא תדחלין מינאי\u0004 \u0005[השכיבי אותי\u0006 לאחר המיתה \u0005בעליית הגג ואל תפחדי\u0006 ממני\u0005]\u0006 שלא תארע בגופו כל תקלה וכל סרחון. \u0003אמר ר' שמואל בר נחמני: אישתעיא\u0004 \u0005[אמרה,\u0006 סיפרה\u0005]\u0006 \u0003לי אימיה\u0004 \u0005[אימו]\u0006 של \u0003ר' יונתן, דאישתעיא\u0004 \u0005[שאמרה,\u0006 סיפרה\u0005]\u0006 \u0003לה דביתהו\u0004 \u0005[אשתו]\u0006 של \u0003ר' אלעזר בר' שמעון:\u0004 \u0003לא פחות מתמני סרי\u0004 \u0005[משמונה עשרה],\u0006 \u0003ולא טפי מעשרין ותרין שנין\u0004 \u0005[יותר מעשרים ושתים שנה]\u0006 \u0003אוגניתיה בעיליתא\u0004 \u0005[הניחה אותו\u0006 כך \u0005בעלייה]\u0006 ובכל זאת,","\u0003כי הוה סליקנא מעיננא ליה במזייה, כי הוה משתמטא ביניתא מיניה הוה אתי דמא\u0004 \u0005[כאשר הייתי עולה לבדוק בשערותיו, כאשר היתה נתלשת שערה היה יוצא דם],\u0006 כלומר, נשאר כבשעת מותו ממש. \u0003יומא חד חזאי ריחשא דקא נפיק מאוניה\u0004 \u0005[יום אחד ראיתי תולעת היוצאת מאזנו],\u0006 \u0003חלש דעתאי\u0004 \u0005[חלשה דעתי]\u0006 מצער, שהנה רימה שולטת בגופו. \u0003איתחזי\u0004 \u0005[נראה]\u0006 \u0003לי\u0004 בעלי \u0003בחלמא\u0004 \u0005[בחלום]\u0006 ו\u0003אמר לי: לא מידי\u0004 \u0005[דבר]\u0006 \u0003הוא,\u0004 אין בכך ולא כלום, כי זהו עונש מיוחד משום ש\u0003יומא חד שמעי בזלותא דצורבא מרבנן\u0004 \u0005[יום אחד שמעתי שמזלזלים בתלמיד חכם]\u0006 \u0003ולא מחאי כדבעי\u0004 \u0005[מחיתי כפי שהיה ראוי]\u0006 \u0003לי,\u0004 ולכן נענשתי באוזן, מידה כנגד מידה.","ועוד מספרים: \u0003כי הוו אתו בי תרי לדינא\u0004 \u0005[כאשר היו באים שנים לדון]\u0006 אחרי מותו, \u0003הוו קיימי אבבא, אמר מר מילתיה ומר מילתיה\u0004 \u0005[היו עומדים על הפתח, היה זה אומר את דבריו וזה אומר את דבריו]\u0006 \u0003נפיק קלא מעיליתיה\u0004 \u0005[והיה יוצא קול מן העלייה],\u0006 \u0003ואמר: איש פלוני אתה חייב, איש פלוני אתה זכאי.\u0004 מספרים: \u0003יומא חד הוה קא מינציא דביתהו בהדי שבבתא\u0004 \u0005[יום אחד התקוטטה אשתו עם שכנתה],\u0006 \u0003אמרה לה\u0004 השכנה בלשון קללה: \u0003תהא כבעלה שלא ניתן לקבורה.\u0004 וכשנשמע המאורע ברבים, \u0003אמרי רבנן\u0004 \u0005[אמרו חכמים]:\u0006 \u0003כולי האי\u0004 \u0005[כל כך הרבה]\u0006 \u0003ודאי לאו אורח ארעא\u0004 \u0005[לא דרך ארץ]\u0006 הוא, ובוודאי חייבים אנו לטפל בו כראוי לו.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 שדבר אחר גרם, ש\u0003ר' שמעון בן יוחאי\u0004 אביו \u0003איתחזאי להו בחלמא\u0004 \u0005[נראה להם בחלום],\u0006 והוא אמר להם: \u0003פרידה אחת\u0004 (דבר אחד, גרגיר אחד) \u0003יש לי ביניכם, ואי\u0004 \u0005[ואין]\u0006 \u0003אתם רוצים להביאה אצלי\u0004 ולקוברו לידי? \u0003אזול רבנן לאעסוקי ביה\u0004 \u0005[הלכו חכמים לעסוק בו\u0006 בקבורתו\u0005]\u0006 ו\u0003לא שבקו\u0004 \u0005[הניחו]\u0006 להם \u0003בני\u0004 העיירה \u0003עכבריא\u0004 ששם היה מונח ר' אלעזר. ש\u0003כל שני דהוה ניים\u0004 \u0005[השנים שהיה 'ישן']\u0006 \u0003ר' אלעזר בר' שמעון בעיליתיה\u0004 \u0005[בעלייתו]\u0006 \u0003לא סליק\u0004 \u0005[באה]\u0006 \u0003חיה רעה למתייהו\u0004 \u0005[לעירם,\u0006 למקומם\u0005]\u0006 והבינו שזכותו מגינה עליהם, ולא רצו שיצא ותיבטל מהם הגנתו.","\u0003יומא חד מעלי יומא דכיפורי הוה, הוו טרידי\u0004 \u0005[יום אחד ערב יום כיפורים היה\u0006 ו\u0005היו\u0006 הכל \u0005טרודים].\u0006 \u0003שדרו רבנן\u0004 \u0005[שלחו חכמים]\u0006 \u0003לבני\u0004 העיירה \u0003בירי\u0004 הסמוכה \u0003ואסקוהו לערסיה\u0004 \u0005[והוציאו\u0006 את \u0005מיטתו]\u0006 \u0003ואמטיוה למערתא דאבוה\u0004 \u0005[והביאו אותו למערה\u0006 שבה היה קבור \u0005אביו,\u0006 ר' שמעון\u0005].\u0006 \u0003אשכחוה לעכנא דהדרא לה למערתא\u0004 \u0005[מצאו נחש המקיף את המערה]\u0006 ולא נתן לאנשים להיכנס. \u0003אמרו לה: עכנא עכנא\u0004 \u0005[נחש נחש]!\u0006 \u0003פתחי פיך ויכנס בן אצל אביו. פתח להו\u0004 \u0005[להם]\u0006 וקברוהו.","ועוד מספרים בשבח; לאחר מותו של ר' אלעזר \u0003שלח רבי לדבר באשתו\u0004 של ר' אלעזר בר' שמעון שתינשא לו. \u0003שלחה ליה\u0004 \u0005[לו]\u0006 תשובה: \u0003כלי שנשתמש בו קודש\u0004 הוא ר' אלעזר \u0003ישתמש בו חול\u0004 כמוך? \u0003תמן אמרין\u0004 \u0005[שם\u0006 בארץ ישראל \u0005אומרים]\u0006 שבפתגם עממי זה השתמשה: \u0003באתר דמרי ביתא תלא זייניה כולבא רעיא קולתיה תלא\u0004 \u0005[במקום שבעל הבית היה תולה את חרבו, הרועה הבזוי תולה את סלו].\u0006 כלומר, וכי ראוי אתה להיות במקומו של בעלי? \u0003שלח לה: נהי\u0004 \u0005[אם אמנם]\u0006 ש\u0003בתורה גדול\u0004 היה \u0003ממני, אבל במעשים טובים מי\u0004 \u0005[האם]\u0006 \u0003גדול\u0004 היה \u0003ממני? שלחה ליה\u0004 \u0005[לו]:\u0006 \u0003בתורה מיהא\u0004 \u0005[אם אמנם]\u0006 היה \u0003גדול ממך לא ידענא\u0004 \u0005[אין אני יודעת],\u0006 ואולם \u0003במעשים\u0004 טובים \u0003ידענא, דהא קביל עליה יסורי\u0004 \u0005[יודעת אני שהרי קיבל על עצמו יסורים].\u0006","ושואלים: \u0003בתורה מאי היא\u0004 \u0005[מה הוא],\u0006 מדוע היה רבי סבור שר' אלעזר בר' שמעון גדול ממנו? ומספרים: \u0003דכי הוו יתבי\u0004 \u0005[שכאשר היו יושבים]\u0006 \u0003רבן שמעון בן גמליאל ור' יהושע בן קרחה\u0004 שהיו גדולי הדור \u0003אספסלי\u0004 \u0005[על הספסלים]\u0006 \u0003יתבי קמייהו\u0004 \u0005[ישבו לפניהם]\u0006 \u0003ר' אלעזר בר' שמעון ורבי\u0004 שהיו אז צעירים לימים \u0003אארעא\u0004 \u0005[על הארץ]\u0006 כתלמידים,","\u0003מקשו ומפרקו\u0004 \u0005[היו מקשים ומתרצים],\u0006 שהיו נושאים ונותנים בהלכה ומחדשים דברים חשובים. \u0003אמרי\u0004 \u0005[אמרו]\u0006 החכמים: \u0003מימיהן אנו שותים,\u0004 כלומר, מתורתם אנו למדים \u0003והם יושבים על גבי קרקע?!\u0004 צריך לכבדם ולהושיבם עם החכמים למרות גילם הצעיר, \u0003עבדו להו ספסלי אסקינהו\u0004 \u0005[עשו להם ספסלים והעלו\u0006 גם \u0005אותם]\u0006 לשבת בין גדולי חכמים.","\u0003אמר להן רבן שמעון בן גמליאל\u0004 לחכמים: \u0003פרידה אחת\u0004 (גרגיר אחד) \u0003יש לי ביניכם\u0004 בני רבי יהודה, \u0003ואתם מבקשים לאבדה הימני?\u0004 שנראה שאתם רוצים לאבד את בני, שאם יושיבוהו בראש בגיל צעיר זה תשלוט בו עין הרע, \u0003אחתוהו\u0004 \u0005[הורידוהו]\u0006 את \u0003רבי\u0004 לפי בקשת אביו, וישב שוב על הקרקע. \u0003אמר להן ר' יהושע בן קרחה:\u0004 אם כן \u0003מי שיש לו אב\u0004 כרבן שמעון בן גמליאל \u0003יחיה, ומי שאין לו אב,\u0004 כר' אלעזר \u0003ימות?\u0004 הרי צריך לחשוש גם לר' אלעזר! \u0003אחתוהו נמי\u0004 \u0005[הורידוהו גם כן]\u0006 את \u0003ר' אלעזר בר' שמעון.\u0004 \u0003חלש דעתיה\u0004 \u0005[חלשה דעתו]\u0006 של ר' אלעזר, שנעלב משום שלא ידע את טעם הדברים, ו\u0003אמר: קא חשביתו ליה כוותי\u0004 \u0005[אתם חושבים אותי שהוא כמוני]?\u0006 הלא אני גדול ממנו.","כיון שכך, \u0003עד ההוא יומא כי\u0004 \u0005[אותו יום כאשר]\u0006 \u0003אמר רבי מילתא\u0004 \u0005[דבר]\u0006 \u0003הוה מסייע ליה\u0004 \u0005[היה\u0006 \u0003מסייע לו]\u0004 \u0003ר' אלעזר בר' שמעון\u0004 בהוכחות, \u0003מכאן ואילך כי הוה אמר\u0004 \u0005[כאשר היה אומר]\u0006 \u0003רבי: \"יש לי להשיב\"\u0004 (להקשות) בנושא מסויים \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' אלעזר בר' שמעון: כך וכך יש לך להשיב,\u0004 שהיה מקדים את הדברים ומנחש מה בדעתו של רבי, ומיד היה אומר לו: ו\u0003זו היא תשובתך,\u0004 כלומר, כך יש לדחות את דבריך. ו\u0003השתא\u0004 \u0005[ועכשיו]\u0006 אילו היית שואל זאת \u0003היקפתנו תשובות חבילות שאין בהן ממש.\u0004","\u0003חלש דעתיה\u0004 \u0005[חלשה דעתו,\u0006 נפגע\u0005]\u0006 \u0003רבי\u0004 על שכך הוא נוהג בו. \u0003אתא\u0004 \u0005[בא]\u0006 ו\u0003אמר ליה לאבוה\u0004 \u0005[לו לאביו].\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003בני, אל ירע\u0004 לך שהוא גדול כל כך, \u0003שהוא ארי בן ארי,\u0004 שהרי גם אביו ר' שמעון היה גדול הדור, \u0003ואתה ארי בן שועל,\u0004 שהקטין רבן שמעון בן גמליאל עצמו, ואמר שכיון שהוא קטן בחכמה מאביו של ר' אלעזר לכן אין פלא שהבן חריף כל כך. ועל כל פנים אז הכיר רבי לדעת את גדולתו של ר' אלעזר בתורה.","ומעירים, \u0003והיינו\u0004 \u0005[וזהו]\u0006 ש\u0003אמר\u0004 \u0003רבי: שלשה ענוותנין הן,\u0004 שהם גדולי עולם בענוה, \u0003ואלו הן: אבא,\u0004 רבן שמעון בן גמליאל"],["\u0003ובני בתירה, ויונתן בן שאול.\u0004 ומפרטים: \u0003רבן שמעון בן גמליאל\u0004 — \u0003הא דאמרן\u0004 \u0005[זו שאמרנו]\u0006 שהקטין עצמו בפני בנו. \u0003בני בתירה\u0004 שהיו נשיאים בישראל, וכאשר נשאלה שאלה שלא ידעו לענות עליה בא הלל ופתרה, מחלו על כבודם וכפי ש\u0003אמר מר\u0004 \u0005[החכם]\u0006 ש\u0003הושיבוהו בראש ומינוהו לנשיא עליהן. יונתן בן שאול\u0004 — \u0003דקאמר ליה\u0004 \u0005[שאמר לו]\u0006 \u0003לדוד: \"ואתה תמלך על ישראל ואני אהיה לך למשנה\"\u0004 (שמואל א' כג, יז), אף שיונתן היה בן מלך, ודוד היה בורח מפני שאול במדבר.","ואומרים: \u0003ממאי\u0004 \u0005[ממה]\u0006 אתה מסיק שכולם היו ענווים כל כך? \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003יונתן בן שאול\u0004 עשה כן משום \u0003דחזא דגריר עלמא בתר\u0004 \u0005[שראה שנגרר העולם,\u0006 כל האנשים, \u0005אחרי]\u0006 \u0003דוד\u0004 ולא ענוה יתירה היתה זו, אלא ראיית הדברים כהוייתם. \u0003בני בתירה נמי דחזו\u0004 \u0005[גם כן, שראו]\u0006 את \u0003הלל\u0004 שהוא \u0003עדיף מינייהו\u0004 \u0005[מהם\u0006 בתורה\u0005],\u0006 \u0003אלא רבן שמעון בן גמליאל ודאי ענוותן הוה\u0004 \u0005[היה].\u0006","\u0003אמר רבי,\u0004 כיון ששמע דברים אלה בשבח ר' אלעזר, משמע \u0003ש\u0004\u0003חביבין יסורין. קבל עליה תליסר שני\u0004 \u0005[קיבל עליו שלוש עשרה שנה]\u0006 של יסורים, \u0003שית בצמירתא\u0004 \u0005[שש\u0006 שנים \u0005בחולי הכליות]\u0006 \u0003ושבע\u0004 שנים \u0003בצפרנא\u0004 \u0005[בצפירנא].\u0006 \u0003ואמרי לה\u0004 \u0005[ויש אומרים]:\u0006 \u0003שבעה בצמירתא\u0004 \u0005[בחולי הכליות],\u0006 \u0003ושית בצפרנא\u0004 \u0005[ושש בצפירנא].\u0006","מספרים: \u0003אהורייריה דבי\u0004 \u0005[הרפתן של בית]\u0006 \u0003רבי הוה עתיר\u0004 \u0005[היה\u0006 \u0003עשיר]\u0004 \u0003משבור מלכא\u0004 \u0005[מלך\u0006 פרס\u0005],\u0006 שכן היו לרבי בהמות רבות כל כך ברפת, שאפילו מפסולתן אפשר היה להתעשר, ומכאן נבין כמה בהמות היו. \u0003כד הוה רמי כיסתא לחיותא הוה אזיל קלא בתלתא מילי\u0004 \u0005[כאשר היה שם תבן לפני הבהמות היה הולך הקול\u0006 של געייתם \u0005בשלושה מילין].\u0006 \u0003הוה מכוין דרמי בההיא שעתא דעייל\u0004 \u0005[\u0006ו\u0005היה מכוון לתת להם באותה שעה שנכנס]\u0006 \u0003רבי לבית הכסא\u0004 שלא ישמע קול צעקותיו, מפני הכאבים שהיה סובל, \u0003ואפילו הכי\u0004 \u0005[כך]\u0006 \u0003מעבר ליה קליה לקלייהו ושמעו ליה נחותי ימא\u0004 \u0005[היה קולו מתגבר על קולם\u0006 עד \u0005שהיו שומעים אותו יורדי הים],\u0006 שכל כך היו רבים יסוריו.","ומעירים: \u0003ואפילו הכי\u0004 \u0005[כך],\u0006 \u0003יסורי\u0004 \u0005[היסורים]\u0006 של \u0003ר' אלעזר בר' שמעון עדיפי\u0004 \u0005[עדיפים]\u0006 מאלו של \u0003רבי.\u0004 ש\u0003אילו\u0004 יסורי \u0003ר' אלעזר בר' שמעון מאהבה באו\u0004 עליו היסורים \u0003ומאהבה הלכו,\u0004 ואילו יסורי \u0003רבי\u0004 \u0003על ידי מעשה\u0004 שגרם הוא עצמו \u0003באו,\u0004 ו\u0003על ידי מעשה\u0004 אחר \u0003הלכו.\u0004","ומפרטים: \u0003על ידי מעשה באו מאי היא\u0004 \u0005[מה הוא,\u0006 מה היה הדבר\u0005]?\u0006 — \u0003דההוא עגלא דהוו קא ממטו ליה\u0004 \u0005[עגל אחד שהיו מוליכים אותו]\u0006 \u0003לשחיטה.\u0004 \u0003אזל תליא לרישיה בכנפיה\u0004 \u0005[הלך תלה\u0006 העגל \u0005ראשו בתוך כנף\u0006 בגדו\u0005]\u0006 של \u0003רבי\u0004 \u0003וקא בכי\u0004 \u0005[ובכה].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 לעגל: \u0003זיל\u0004 \u0005[\u0006\u0005לך]\u0006 \u0003לכך נוצרת\u0004 לשחיטה. \u0003אמרי\u0004 \u0005[אמרו]\u0006 משמים: \u0003הואיל ולא קא\u0004 \u0005[ואינו]\u0006 \u0003מרחם\u0004 על הבריות — \u0003ליתו עליה\u0004 \u0005[\u0006ש\u0005יבואו עליו]\u0006 \u0003יסורין.\u0004","ו\u0003על ידי מעשה\u0004 אחר \u0003הלכו\u0004 יסוריו, ומספרים: \u0003יומא חד הוה קא כנשא אמתיה\u0004 \u0005[יום אחד היה מטאטאה שפחתו]\u0006 של \u0003רבי ביתא\u0004 \u0005[את הבית],\u0006 \u0003הוה שדיא בני כרכושתא וקא כנשא להו\u0004 \u0005[היו מונחים שם בני חולדה והיתה מטאטאה אותם].\u0006 \u0003אמר לה: שבקינהו\u0004 \u0005[הניחי אותם],\u0006 הרי \u0003כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"ורחמיו על כל מעשיו\"\u0004 (תהלים קמה, ט). \u0003אמרו\u0004 משמים: \u0003הואיל ומרחם\u0004 — \u0003נרחם עליה\u0004 \u0005[עליו],\u0006 ואז פסקו יסוריו.","מספרים: \u0003כולהו שני יסורי\u0004 \u0005[כל שנות היסורים]\u0006 של \u0003ר' אלעזר לא שכיב איניש\u0004 \u0005[מת אדם]\u0006 \u0003בלא זמניה\u0004 \u0005[זמנו],\u0006 שכיון שיסורים שקיבל עליו היו כפרה לעוונות הדור. \u0003כולהו שני יסורי\u0004 \u0005[כל שנות היסורים]\u0006 של \u0003רבי לא איצטריך עלמא למיטרא\u0004 \u0005[הוצרך העולם לגשם]\u0006 והיתה רטיבות מספקת מחמת הטל. ש\u0003אמר רבה בר רב שילא: קשי יומא דמיטרא כיומא דדינא\u0004 \u0005[קשה יום המטר כיום הדין],\u0006 שירידת הגשמים גורמת הרבה פורענויות, מחמת ברקים ורעמים ושטפונות. \u0003ואמר אמימר: אי לאו\u0004 \u0005[אם לא]\u0006 היה \u0003צריך לעלמא\u0004 \u0005[לעולם]\u0006 לגשם — \u0003בעו רבנן רחמי עליה ומבטלי ליה\u0004 \u0005[היו חכמים מבקשים רחמים עליו ומבטלים אותו].\u0006 ו\u0003אפילו הכי\u0004 \u0005[כך]\u0006 שלא היה גשם, \u0003כי הוו עקרי פוגלא ממשרא הוה קיימא בירא מליא מיא\u0004 \u0005[כאשר היו עוקרים צנון מן הערוגה היתה נשארת גומה מלאה מים]\u0006 מרוב הרטיבות שבארץ.","מספרים עוד על היחסים בין רבי לחבירו, ר' אלעזר. \u0003איקלע\u0004 \u0005[הזדמן]\u0006 \u0003רבי לאתריה\u0004 \u0005[למקומו]\u0006 של \u0003ר' אלעזר בר' שמעון,\u0004 \u0003אמר להו\u0004 \u0005[להם]\u0006 לבני המקום: האם \u0003יש לו בן לאותו צדיק? אמרו לו: יש לו בן\u0004 והבן יצא לתרבות רעה \u0003וכל זונה שנשכרת\u0004 לאחרים \u0003בשנים שוכרתו בשמנה\u0004 מחמת יופיו. כיון ששמע רבי כך, רצה להוציאו ממצב זה, \u0003אתייה, אסמכיה\u0004 \u0005[הביא אותו, הסמיך אותו]\u0006 \u0003ב\u0004תואר \u0003רבי\u0004 \u0003ואשלמיה\u0004 \u0005[ומסרו]\u0006 \u0003לר' שמעון בן איסי בן לקוניא אחות דאמיה\u0004 \u0005[אחי אמו].\u0006","\u0003כל יומא הוה אמר\u0004 \u0005[יום היה\u0006 הבן \u0005אומר]:\u0006 \u0003לקרייתי אנא איזיל\u0004 \u0005[אני הולך]\u0006 מפני שהיה קשה עליו הלימוד. \u0003אמר ליה\u0004 \u0005[\u0006היה \u0005אומר לו]\u0006 ר' שמעון בן איסי: \u0003חכים עבדו יתך\u0004 \u0005[חכם עשו אותך],\u0006 \u0003וגולתא דדהבא פרסו עלך\u0004 \u0005[וטלית של זהב פרסו עליך],\u0006 \u0003ו\"רבי\" קרו\u0004 \u0005[קוראים]\u0006 \u0003לך, ואת אמרת לקרייתי אנא איזיל\u0004 \u0005[ואתה אומר לעירי אני הולך],\u0006 לא כדאי לך הדבר! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מומי\u0004 \u0005[נשבע אני]:\u0006 \u0003עזובה\u0004 ממני מחשבה \u0003דא\u0004 \u0005[זו],\u0006 שהחליט להשאר וללמוד. \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003גדל\u0004 ונעשה תלמיד חכם \u0003אתא יתיב במתיבתא\u0004 \u0005[בא\u0006 ו\u0005ישב בישיבתו]\u0006 של \u0003רבי,\u0004 \u0005[כאשר גדל\u0006 ונעשה תלמיד חכם \u0005בא וישב בישיבתו של רבי].\u0006 \u0003שמעיה לקליה\u0004 \u0005[שמע\u0006 רבי \u0005את קולו],\u0006 \u0003אמר: הא קלא דמי לקליה\u0004 \u0005[קול זה דומה לקולו]\u0006 של \u0003ר' אלעזר בר' שמעון.\u0004 \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003בריה\u0004 \u0005[בנו]\u0006 \u0003הוא\u0004 זה.","\u0003קרי עליה\u0004 \u0005[קרא\u0006 רבי \u0005עליו]\u0006 מקרא זה: \u0003\"פרי צדיק עץ חיים ולקח נפשות חכם\"\u0004 (משלי יא, ל) וכך יש להמליץ: \u0003\"פרי צדיק עץ חיים\"\u0004 — \u0003זה ר' יוסי בר' אלעזר בר' שמעון\u0004 שהוא פרי=בן צדיק, ונעשה בעצמו אדם גדול. \u0003\"ולקח נפשות חכם\"\u0004 — \u0003זה ר' שמעון בן איסי בן לקוניא\u0004 שהצליח להביאו לדרגה זו. וכדי להסביר עד כמה עלה בן זה במעלה.","\u0003כי נח נפשיה אמטוהו למערתא דאבוה\u0004 \u0005[כאשר נחה נפשו,\u0006 מת, \u0005הביאו אותו למערה\u0006 שבה נקבר \u0005אביו],\u0006 \u0003הוה הדרא לה עכנא למערתא\u0004 \u0005[היה נחש מקיף את המערה].\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003עכנא עכנא\u0004 \u0005[נחש נחש]!\u0006 \u0003פתח פיך ויכנס בן אצל אביו. לא פתחא להו\u0004 \u0005[פתח להם]\u0006 הנחש. \u0003כסבורים העם לומר שזה גדול מזה,\u0004 שלא זכה ר' יוסי בר' אלעזר להקבר עם אביו, משום שר' אלעזר גדול היה ממנו, ולא היה הבן ראוי להיקבר שם.","\u0003יצתה בת קול ואמרה: לא מפני שזה גדול מזה\u0004 במעלותיו, \u0003אלא זה\u0004 ר' אלעזר \u0003היה בצער מערה\u0004 עם אביו ר' שמעון שהתחבאו בה שלוש עשרה שני מפני הרומאים, \u0003וזה\u0004 הנכד \u0003לא היה בצער מערה\u0004 ומשום כך לא זכה להקבר עמם, אבל לא משום חסרון במעלותיו.","כיוצא בו מסופר: \u0003איקלע\u0004 \u0005[הזדמן]\u0006 \u0003רבי לאתריה\u0004 \u0005[למקומו]\u0006 של \u0003ר' טרפון,\u0004 \u0003אמר להו\u0004 \u0005[להם]\u0006 לבני המקום: \u0003יש לו בן לאותו צדיק שהיה מקפח את בניו?\u0004 שהיה זה סגנונו של ר' טרפון לומר \"אקפח את בניי אם אין הדבר כך...\". \u0003אמרו לו: בן אין לו, בן בת יש לו,\u0004 אלא שיצא לתרבות רעה, \u0003וכל זונה שנשכרת\u0004 לאחרים \u0003בשנים שוכרתו בשמנה.\u0004","\u0003אתיוהו לקמיה\u0004 \u0005[הביאוהו לפניו,\u0006 לפני רבי\u0005].\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אי הדרת\u0004 \u0005[אם תחזור]\u0006 \u0003בך\u0004 — \u0003יהיבנא\u0004 \u0005אתן\u0006 \u0003לך ברתאי\u0004 \u0005[את בתי\u0006 לאשה\u0005].\u0006 \u0003הדר ביה\u0004 \u0005[חזר בו]\u0006 ונעשה אדם גדול. \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 כי \u0003נסבה\u0004 \u0005[נשא אותה]\u0006 \u0003ו\u0004אחר כך \u0003גירשה.\u0004 \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 ש\u0003לא נסבה\u0004 \u0005[נשאה]\u0006 \u0003כלל,\u0004 \u0003כדי שלא יאמרו: בשביל זו חזר זה,\u0004 כי כשחזר בתשובה שלמה רצה שתהא זו תשובה מאהבה גמורה.","ושואלים: \u0003ולמה ליה\u0004 \u0005[לו]\u0006 לרבי \u0003כולי האי\u0004 \u0005[כל זה]\u0006 להתאמץ כל כך בתקנתם של צאצאי החכמים, שהיו לכאורה מופקרים? ומסבירים: ש\u0003אמר רב יהודה אמר רב, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 ש\u0003אמר\u0004 זאת \u0003ר' חייא בר אבא אמר ר' יוחנן, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 ש\u0003אמר\u0004 זאת \u0003ר' שמואל בר נחמני אמר ר' יונתן: כל המלמד את בן חבירו תורה זוכה ויושב בישיבה של מעלה, שנאמר: \"אם תשוב ואשיבך לפני תעמד\"\u0004 (ירמיה טו, יט), הרי שהשב ומשיב זוכה לעמוד לפני ה'.","\u0003וכל המלמד את בן עם הארץ תורה\u0004 מגיע לדרגה כזו ש\u0003אפילו הקדוש ברוך הוא גוזר גזירה\u0004 רעה — \u0003מבטלה בשבילו, שנאמר: \"ואם תוציא יקר מזולל כפי תהיה\"\u0004 (שם), שמי שמצליח לעשות דבר יקר \"מזולל\" מדבר פחות, ומאדם פחות — זוכה להיות כמו הקדוש ברוך הוא בעצמו.","ועוד בענין צאצאיהם של חכמים. \u0003אמר ר' פרנך אמר ר' יוחנן: כל שהוא תלמיד חכם, ובנו תלמיד חכם ובן בנו תלמיד חכם\u0004 — \u0003שוב אין תורה פוסקת מזרעו לעולם, שנאמר: \"ואני זאת בריתי\u0004 אותם אמר ה' רוחי אשר עליך ודברי אשר שמתי בפיך \u0003לא ימושו מפיך ומפי זרעך ומפי זרע זרעך אמר ה' מעתה ועד עולם\"\u0004 (ישעיהו נט, כא).","\u0003מאי\u0004 \u0005[מה]\u0006 ענין \u0003\"אמר ה'\"?\u0004 — כך צריך לפרש: \u0003אמר הקדוש ברוך הוא: אני ערב לך בדבר זה.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"מעתה ועד עולם\"?\u0004 הרי נאמרו כאן רק שלושה דורות! \u0003אמר ר' ירמיה,\u0004 לומר: \u0003מכאן ואילך\u0004 אחרי שלושה דורות רצופים של חכמים \u0003תורה מחזרת\u0004 כבר \u0003על אכסניא שלה,\u0004 כאדם המתרגל להיות באכסניא שחוזר אליה תמיד. אף משפחה זו, כיון שזכתה למורשת של תורה — תורה כבר נשארת דבוקה בהם.","מסופר: \u0003רב יוסף יתיב ארבעין תעניתא\u0004 \u0005[ישב ארבעים תעניות]\u0006 על קנין התורה וזכירתה, \u0003ואקריוהו\u0004 \u0005[והקריאו לו\u0006 בחלום\u0005]\u0006 את הכתוב \u0003\"לא ימושו מפיך\". יתיב\u0004 \u0005[ישב]\u0006 \u0003ארבעים תעניתא אחריני ואקריוהו\u0004 \u0005[תעניות אחרות והקריאו לו]\u0006 \u0003\"לא ימושו מפיך ומפי זרעך\". יתיב\u0004 \u0005[ישב]\u0006 \u0003מאה תעניתא אחריני אתא ואיקריוהו\u0004 \u0005[תעניות אחרות, בא והקריאו לו]\u0006 את הכתוב \u0003\"לא ימושו מפיך ומפי זרעך ומפי זרע זרעך\". אמר: מכאן ואילך לא צריכנא\u0004 \u0005[אין אני צריך\u0006 להתענות \u0005עוד]\u0006 שתשאר תורה במשפחתי, כי \u0003תורה מחזרת על אכסניא שלה.\u0004","כיון שדובר כאן על תעניותיו של רב יוסף מספרים: \u0003ר' זירא כי סליק לארעא דישראל\u0004 \u0005[כאשר עלה לארץ ישראל]\u0006 \u0003יתיב\u0004 \u0005[ישב]\u0006 \u0003מאה תעניתא\u0004 \u0005[תעניות]\u0006 כדי \u0003דלשתכח גמרא בבלאה מיניה כי היכי\u0004 \u0005[ישב מאה תעניות שישתכח התלמוד הבבלי ממנו כדי]\u0006 ש\u0003לא נטרדיה\u0004 \u0005[יטריד אותו]\u0006 מלהגיע לדרך הלימוד של ארץ ישראל, שכיון ששיטת הלימוד שונה שם ולא רצה שיבלבל אותו לימודו הקודם. \u0003יתיב\u0004 \u0005[ישב]\u0006 \u0003מאה\u0004 תעניות \u0003אחריניתא\u0004 \u0005[אחרות]\u0006 ש\u0003לא לשכוב\u0004 \u0005[ימות]\u0006 \u0003ר' אלעזר בשניה\u0004 \u0005[בשנותיו,\u0006 בימיו\u0005],\u0006 \u0003ונפלין עילויה מילי דצבורא\u0004 \u0005[ויפלו עליו ענייני הציבור],\u0006 שכל עוד היה ר' אלעזר קיים הוא היה ראש הישיבה, וכל ענייני הכלל היו מוטלים עליו, ויכול היה ר' זירא לעסוק במנוחה בתורה לעצמו. \u0003ויתיב\u0004 \u0005[וישב]\u0006 \u0003מאה\u0004 תעניות \u0003אחריני\u0004 \u0005[אחרות]\u0006 כדי ש\u0003לא נשלוט ביה נורא דגיהנם\u0004 \u0005[תשלוט בו אש הגיהנום].\u0006","ומספרים: \u0003כל תלתין יומי הוה בדיק נפשיה\u0004 \u0005[שלשים יום היה בודק את עצמו]\u0006 אם עדיין הוא בדרגה זו, כיצד היה עושה? \u0003שגר תנורא סליק ויתיב בגויה\u0004 \u0005[הסיק את התנור עלה וישב בתוכו]\u0006 \u0003ולא הוה שלטא ביה נורא\u0004 \u0005[היתה שולטת בו האש].\u0006 \u0003יומא חד יהבו רבנן עינא ואיחרכו שקיה, וקרו ליה \"קטין חריך שקיה\"\u0004 \u0005[יום אחד נתנו בו חכמים עיניהם\u0006 בקנאה \u0005ונחרכו שוקיו\u0006 באש, \u0005וקראו לו\u0006 מאז \u0005\"הגוץ חרוך השוקיים\"].\u0006","ועוד בנושא של קנין התורה, \u0003אמר רב יהודה אמר רב: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"מי האיש החכם ויבן את זאת ואשר דבר פי ה' אליו ויגדה על מה אבדה הארץ\u0004 נצתה כמדבר מבלי עובר\u0003\"\u0004 (ירמיה ט, יא), \u0003דבר זה\u0004"],["\u0003אמרו חכמים\u0004 (\"מי האיש החכם\") \u0003ולא פירשוהו, אמרו נביאים\u0004 (\"ואשר דבר ה' אליו\") \u0003ולא פירשוהו, עד שפירשו הקדוש ברוך הוא בעצמו. שנאמר: \"ויאמר ה' על עזבם את תורתי אשר נתתי לפניהם\"\u0004 (ירמיהו ט, יב). \u0003אמר רב יהודה אמר רב:\u0004 לא שלא למדו תורה כלל, אלא \u0003שלא ברכו בתורה תחילה\u0004 — שעסקו בתורה אבל לא התייחסו אליה כנושא של קדושה, כתורת ה'.","\u0003אמר רב חמא: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 בכתוב \u0003\"בלב נבון תנוח חכמה ובקרב כסילים תודע\"\u0004 (משלי יד, לג), \u0003\"בלב נבון תנוח חכמה\"\u0004 — \u0003זה תלמיד חכם בן תלמיד חכם, \"ובקרב כסילים תודע\"\u0004 — \u0003זה תלמיד חכם בן עם הארץ,\u0004 שכיון שהוא בן עם הארץ הוא מתפאר קצת בחכמתו. \u0003אמר עולא: היינו דאמרי אינשי\u0004 \u0005[זה שאומרים בני אדם]\u0006 בפתגם עממי: \u0003אסתירא בלגינא קיש קיש קריא\u0004 \u0005[מטבע קטנה בכד מקשקשת וקוראה\u0006 בקול\u0005]\u0006 ואילו כד מלא מטבעות גדולות אין קולן נשמע.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' ירמיה לר' זירא: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 בכתוב \u0003\"קטן וגדול שם הוא ועבד חפשי מאדניו\"\u0004 (איוב ג, יט) \u0003אטו לא ידעינן\u0004 \u0005[וכי אין אנו יודעים]\u0006 שבשאול \u0003קטן וגדול שם הוא? אלא\u0004 כך צריך לפרש: \u0003כל המקטין עצמו על דברי תורה בעולם הזה\u0004 — \u0003נעשה גדול לעולם הבא, וכל המשים עצמו כעבד על\u0004 קניית \u0003דברי תורה בעולם הזה\u0004 — \u0003נעשה חפשי לעולם הבא.\u0004","ועוד בשבחם של חכמים. \u0003ריש לקיש הוה\u0004 \u0005[היה]\u0006 \u0003מציין מערתא דרבנן\u0004 \u0005[\u0006את \u0005מערות\u0006 הקבורה של \u0005חכמים],\u0006 \u0003כי מטא למערתיה\u0004 \u0005[כאשר הגיע אל מערתו]\u0006 של \u0003ר' חייא איעלמא מיניה\u0004 \u0005[נעלמה ממנו]\u0006 ולא יכול היה למוצאה. \u0003חלש דעתיה\u0004 \u0005[חלשה דעתו\u0006 מבושה\u0005]\u0006 מדוע אינו זוכה לכך. \u0003אמר: רבונו של עולם!\u0004 וכי \u0003לא פלפלתי תורה כמותו? יצתה בת קול ואמרה לו: תורה כמותו פלפלת,\u0004 ואולם \u0003תורה כמותו לא ריבצת\u0004 (לימדת ברבים).","וכעין מה שמסופר: \u0003כי הוו מינצו\u0004 \u0005[כאשר היו רבים]\u0006 \u0003ר' חנינא ור' חייא, אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' חנינא לר' חייא:\u0004 וכי \u0003בהדי דידי קא מינצית\u0004 \u0005[עמי את רב]?\u0006 \u0003חס וחלילה, אי משתכחא\u0004 \u0005[אם\u0006 \u0003תשתכח]\u0004 \u0003תורה מישראל מהדרנא לה מפילפולי\u0004 \u0005[אחזיר אותה בפלפולי],\u0006 שאוכל לשחזר את כל דברי התורה שנשתכחו, על פי סברתי. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' חייא לר' חנינא: בהדי דידי קא מינצית\u0004 \u0005[עמי את רב]?\u0006 \u0003דעבדי\u0004 \u0005[שעשיתי]\u0006 \u0003לתורה\u0004 ש\u0003לא תשתכח מישראל.\u0004","\u0003מאי עבידנא\u0004 \u0005[מה אני עושה]\u0006 — \u0003אזלינא ושדינא כיתנא וגדלינא נישבי, וציידנא טבי ומאכילנא בשרייהו ליתמי\u0004 \u0005[אני הולך וזורע פשתן ושוזר ממנו רשתות, וצד צבאים ומאכיל מבשרם ליתומים]\u0006 \u0003ואריכנא מגילתא וכתבנא\u0004 \u0005[ועושה מגילות\u0006 מעורם \u0005וכותב]\u0006 \u0003חמשה חומשי\u0004 תורה עליהם, \u0003וסליקנא למתא ומקרינא\u0004 \u0005[ואני הולך לעיר ומלמד]\u0006 ל\u0003חמשה ינוקי\u0004 \u0005[תינוקות]\u0006 \u0003בחמשה חומשי\u0004 תורה, לכל אחד מהם חומש אחד, \u0003ומתנינא שיתא ינוקי שיתא סדרי\u0004 \u0005[ומלמד אני משנה לששה תינוקות ששה סדרים]\u0006 \u0003ואמרנא להו\u0004 \u0005[ואני אומר להם]:\u0006 \u0003עד דהדרנא ואתינא אקרו אהדדי ואתנו אהדדי\u0004 \u0005[שאחזור\u0006 ואבוא לכאן \u0005תלמדו מקרא זה לזה ולמדו משנה זה לזה]\u0006 ועל ידי כך \u0003עבדי\u0004 \u0005[עושה אני]\u0006 \u0003לתורה\u0004 ש\u0003לא תשתכח מישראל.\u0004","ומעירים, \u0003היינו\u0004 \u0005[וזהו]\u0006 ש\u0003אמר רבי:\u0004 \u0003כמה גדולים מעשי חייא! אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' ישמעאל בר' יוסי:\u0004 וכי מעשיו \u0003גדולים\u0004 \u0003אפילו ממר\u0004 \u0005[מ\u0006מעשי \u0005אדוני]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אין\u0004 \u0005[כן].\u0006 ושאל עוד: \u0003אפילו מ\u0004מעשיו של \u0003אבא\u0004 התנא ר' יוסי? \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003חס וחלילה! לא תהא כזאת בישראל\u0004 לומר על מישהו שהוא גדול מר' יוסי.","ועוד לענין גדולתו של ר' חייא, \u0003אמר ר' זירא: אמש\u0004 בלילה \u0003נראה לי\u0004 בחלום \u0003ר' יוסי בר' חנינא. אמרתי לו:\u0004 בעולם עליון \u0003אצל מי אתה תקוע,\u0004 ליד מי אתה נמצא שם? \u0003אמר לי: אצל ר' יוחנן.\u0004 והוספתי לשאול אותו: \u0003ור' יוחנן אצל מי?\u0004 אמר לי: \u0003אצל ר' ינאי. ור' ינאי אצל מי?\u0004 — \u0003אצל ר' חנינא, ור' חנינא אצל מי\u0004 — \u0003אצל ר' חייא. אמרתי לו: ור' יוחנן אצל ר' חייא\u0004 סמוך לו, \u0003לא\u0004 היה ראוי להיות שם? \u0003אמר לי: באתר דזקוקין דנורא ובעורין דאשא\u0004 \u0005[במקום ש\u0006יש \u0005ניצוצות של אור ובעירה של\u0006 \u0005אש]\u0006 — \u0003מאן מעייל בר נפחא לתמן\u0004 \u0005[מי יכניס את בן הנפח,\u0006 ר' יוחנן, \u0005לשם]?!\u0006","\u0003אמר רב חביבא: אשתעי\u0004 \u0005[ספר]\u0006 \u0003לי רב חביבא בר סורמקי: חזי ליה ההוא מרבנן דהוה שכיח\u0004 \u0005[ראיתי אחד החכמים שהיה מצוי]\u0006 ומתגלה \u0003אליהו\u0004 הנביא \u0003גביה\u0004 \u0005[אצלו],\u0006 \u0003דלצפרא הוו שפירן עיניה, ולאורתא דמיין כדמיקלין בנורא\u0004 \u0005[שבבוקר היו עיניו יפות\u0006 ובריאות \u0005ולערב היו נראות כאילו נשרפו באש].\u0006 \u0003אמרי ליה\u0004 \u0005[אמרתי לו]:\u0006 \u0003מאי האי\u0004 \u0005[מה זאת]?\u0006 \u0003ואמר לי: דאמרי ליה\u0004 \u0005[שאמרתי לו]\u0006 \u0003לאליהו: אחוי\u0004 \u0005[הראה]\u0006 \u0003לי רבנן כי סלקי למתיבתא\u0004 \u0005[את החכמים כאשר הם עולים לישיבה]\u0006 שב\u0003רקיע. אמר לי: בכולהו מצית אסתכולי בהו, לבר מגוהרקא\u0004 \u0005[בכולם יכול אתה להסתכל בהם, חוץ מאשר במרכבתו]\u0006 של \u0003ר' חייא דלא תסתכל ביה\u0004 \u0005[שאין אתה יכול להסתכל בה].\u0006 ושאל: \u0003מאי סימנייהו\u0004 \u0005[מה הסימנים]\u0006 שידע מרכבתו של מי היא? \u0003בכולהו אזלי מלאכי כי סלקי ונחתי\u0004 \u0005[בכולם הולכים מלאכים כאשר הם עולים ויורדים],\u0006 שהמלאכים נושאים אותם, \u0003לבר מגוהרקא\u0004 \u0005[חוץ מאשר המרכבה]\u0006 של \u0003ר' חייא דמנפשיה סליק ונחית\u0004 \u0005[שמעצמה\u0006 היא \u0005עולה ויורדת],\u0006 מפני גודל מעלתו.","\u0003לא מצאי לאוקמא אנפשאי, אסתכלי\u0004 \u0005[יכולתי להעמיד את עצמי,\u0006 להתאפק, \u0005והסתכלתי]\u0006 \u0003בה,\u0004 \u0003אתו תרי בוטיטי דנורא ומחיוהו לההוא גברא וסמינהו לעיניה\u0004 \u0005[באו שני לפידי אש והיכוהו\u0006 את עיניו \u0005של האיש ההוא,\u0006 כלומר, עיני \u0005ועוורו את עיניו].\u0006 \u0003למחר אזלי אשתטחי אמערתיה, אמינא\u0004 \u0005[השתטחתי על מערת\u0006 קבורתו, ו\u0005אמרתי]:\u0006 \u0003מתנייתא דמר מתנינא, ואתסאי\u0004 \u0005[את המשניות של אדוני אני לומד, והתרפאתי]\u0006 אבל נשארו העינים שרופות.","ועוד מסופר בשבחו של ר' חייא: \u0003אליהו\u0004 הנביא \u0003הוה שכיח במתיבתא\u0004 \u0005[היה מצוי בישיבתו]\u0006 של \u0003רבי,\u0004 \u0003יומא חד ריש ירחא הוה, נגה ליה\u0004 \u0005[יום אחד ראש חדש היה, התאחר לו]\u0006 \u0003ולא אתא\u0004 \u0005[בא].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבי: \u0003מאי טעמא נגה ליה למר\u0004 \u0005[מה טעם התאחר,\u0006 התעכב, \u0005אדוני]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אדאוקימנא\u0004 \u0005[עד שהעמדתי]\u0006 את \u0003אברהם\u0004 אבינו משנתו \u0003ומשינא ידיה ומצלי ומגנינא ליה\u0004 \u0005[ורחצתי\u0006 את \u0005ידיו והתפלל והשכבתי אותו];\u0006 \u0003וכן ליצחק וכן ליעקב.\u0004 שאל רבי את אליהו: \u0003ולוקמינהו בהדי הדדי\u0004 \u0005[ושיעמידום יחד]!\u0006 ענה לו: \u0003סברי\u0004 \u0005[חשבתי]\u0006 שאם אעשה כך \u0003תקפי ברחמי ומייתי ליה\u0004 \u0005[יתחזקו בתפילה\u0006 שלושתם יחד \u0005ויביאו]\u0006 את ה\u0003משיח בלא זמניה\u0004 \u0005[זמנו],\u0006 בטרם עת.","\u0003אמר\u0004 \u0003ליה\u0004 \u0005[לו]\u0006 רבי: \u0003ו\u0004האם \u0003יש דוגמתן בעולם הזה\u0004 שיכולים להתפלל ולהיענות? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003איכא\u0004 \u0005[יש]\u0006 והם \u0003ר' חייא ובניו. גזר רבי תעניתא\u0004 \u0005[תענית],\u0006 \u0003אחתינהו\u0004 \u0005[הוריד אותם]\u0006 את \u0003ר' חייא ובניו\u0004 להתפלל לפני התיבה. ואכן ראו שתפילתם נשמעת מיד כאשר \u0003אמר\u0004 ר' חייא \u0003\"משיב הרוח\"\u0004 — \u0003ונשבה זיקא\u0004 \u0005[נשבה רוח],\u0006 \u0003אמר \"מוריד הגשם\"\u0004 — \u0003ואתא מיטרא\u0004 \u0005[וירד גשם],\u0006 \u0003כי מטא למימר\u0004 \u0005[כאשר הגיע לומר]\u0006 \u0003\"מחיה המתים\"\u0004 — \u0003רגש עלמא\u0004 \u0005[סער העולם].\u0006","\u0003אמרי ברקיעא\u0004 \u0005[אמרו ברקיע,\u0006 בשמים\u0005]:\u0006 \u0003מאן גלי רזיא בעלמא\u0004 \u0005[מי\u0006 זה \u0005גילה סודות בעולם]?\u0006 \u0003אמרי\u0004 \u0005[אמרו\u0006 שם\u0005]:\u0006 \u0003אליהו\u0004 הוא שגילה סוד זה. \u0003אתיוהו\u0004 \u0005[הביאוהו]\u0006 את \u0003אליהו, מחיוהו שתין פולסי דנורא\u0004 \u0005[\u0006ו\u0005הכו אותו\u0006 כעונש ב\u0005ששים שבטים של אש].\u0006 \u0003אתא אידמי להו כדובא דנורא, על בינייהו וטרדינהו\u0004 \u0005[בא\u0006 אליהו למטה \u0005נדמה להם כדוב של אש, נכנס ביניהם וטרד אותם]\u0006 בתפילתם, ולכן לא הגיעו לומר \"מחיה המתים\".","מסופר: \u0003שמואל ירחינאה אסייה\u0004 \u0005[\u0006המומחה בענייני \u0005הירח\u0006 \u0005רופאו]\u0006 של \u0003רבי הוה\u0004 \u0005[היה].\u0006 \u0003חלש\u0004 \u0005[חלה]\u0006 \u0003רבי בעיניה\u0004 \u0005[בעיניו].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 שמואל: \u0003אימלי\u0004 \u0005[אמלא,\u0006 אשים\u0005]\u0006 \u0003לך סמא\u0004 \u0005[סם]\u0006 בעין לרפאותה. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא יכילנא\u0004 \u0005[אין אני יכול]\u0006 שחלוש אני, וחושש מן הכאב. אמר לו: \u0003אשטר\u0004 \u0005[אמרח]\u0006 \u0003לך משטר\u0004 \u0005[משחה]\u0006 מלמעלה. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא יכילנא\u0004 \u0005[אין אני יכול].\u0006 \u0003הוה מותיב ליה בגובתא דסמני תותי בי סדייה, ואיתסי\u0004 \u0005[היה שם לו את\u0006 התרופות \u0005בקנה של סממנים תחת הכר שלו, והתרפא]\u0006 וללמדנו כמה היה גדול ברפואה.","\u0003הוה קא\u0004 \u0005[היה]\u0006 \u0003מצטער,\u0004 משתדל \u0003רבי למסמכיה\u0004 \u0005[לסמוך אותו]\u0006 בתואר \"רבי\", \u0003ולא הוה מסתייעא מילתא\u0004 \u0005[היה עולה הדבר]\u0006 בידו, שבכל פעם היה הדבר מתעכב. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 שמואל: \u0003לא לצטער מר\u0004 \u0005[אל יצטער אדוני]\u0006 על כך, שכיון שיודע אני שלא יעלה בידך, \u0003שכן\u0004 \u0003לדידי חזי לי סיפרא\u0004 \u0005[אני ראיתי את ספרו]\u0006 של \u0003אדם הראשון\u0004 שבו כתובים סדרי כל הדורות, \u0003וכתיב ביה\u0004 \u0005[וכתוב בו]:\u0006 \u0003שמואל ירחינאה\u0004"]]};
